window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0182", [{"word":"management","ipa_uk":"/məˈneɪdʒmənt/","ipa_us":"/məˈneɪdʒmənt/","definition_zh":"管理；经营；（企业的）管理层；对疾病或局面的处理方式","definition_en":"the activity of running and controlling an organization or process, or the people who do it","core_image":"一只手把散在各处的线头收拢，编成一股能拉动的缰绳","scene":"四家分店各做各的账，月底总对不上数，后来同一个人统一排班、定采购、查库存。Careful management brought the four branches onto one schedule.","sceneCN":"这里 management 指把分散的人、钱与流程收在一起加以调度（第 1 个义项：对组织的统筹经营）；句意：细致的管理让四家分店归到同一张时间表上。图中可辨识物件：账本、排班表、货箱、统一的门牌。","pos":[{"tag":"n.","zh":"管理；经营；管理层；（对疾病、局面的）处理方式"}],"collocations":[{"phrase":"management team","zh":"管理团队"},{"phrase":"top management","zh":"高层管理层"},{"phrase":"management system","zh":"管理体系"},{"phrase":"time management","zh":"时间管理"},{"phrase":"crisis management","zh":"危机处理"},{"phrase":"risk management","zh":"风险管理"}],"forms":[{"label":"单数（统称，不可数）","form":"management"},{"label":"复数（指多家机构的管理层）","form":"managements"},{"label":"动词原形","form":"manage"},{"label":"现在分词","form":"managing"},{"label":"施动者名词","form":"manager"},{"label":"形容词","form":"managerial"}],"derivatives":[{"word":"manager","pos":"n.","zh":"管理者；经理"},{"word":"managerial","pos":"adj.","zh":"管理的；经理层的"},{"word":"manage","pos":"v.","zh":"管理；经营；应付"},{"word":"manageable","pos":"adj.","zh":"可控制的；易处理的"},{"word":"mismanagement","pos":"n.","zh":"管理不善"}],"senses":[{"no":"01","title":"Running an organization","titleCN":"把一个组织的各项工作统筹起来","definition":"the activity of planning, organizing and controlling the work of an organization so that it runs well","definitionCN":"对一个组织的各项工作加以计划、组织与控制，使其运转良好","example":"Good management kept the shipyard busy through the downturn.","exampleCN":"良好的管理让这家船厂在衰退期仍有活干。","why":"The word began as handling a horse with the hand, and running a firm is that same gesture applied to people, money and schedules.","whyCN":"这个词最初指用手摆弄、驯服一匹马；经营一家公司，就是把同样的动作施加到人、钱与日程上。"},{"no":"02","title":"The people in charge","titleCN":"负责决策的那一群人","definition":"the group of senior people who make the main decisions in an organization","definitionCN":"在一个组织里作出主要决策的高层群体","example":"Management agreed to freeze hiring until spring.","exampleCN":"管理层同意把招聘冻结到春天。","why":"Once the activity became a permanent job, the people who did it could be spoken of as one body.","whyCN":"当这种活计变成常设职位，做这件事的人就被当作一个整体来说。"},{"no":"03","title":"Skill in handling people","titleCN":"与人打交道的分寸","definition":"the ability to deal with people and awkward situations without letting them get out of hand","definitionCN":"与人以及棘手局面打交道时不让事情失控的能力","example":"It took patient management to keep the two departments speaking.","exampleCN":"要让两个部门继续对话，需要很有耐心的周旋。","why":"A rider controls a horse by feel rather than force, and the same word covers handling people by feel.","whyCN":"骑手靠手感而不是蛮力控制马匹，这个词也用来指靠分寸感与人相处。"},{"no":"04","title":"Careful use of resources","titleCN":"对钱财与时间的节制使用","definition":"the careful control of money, time or supplies so that nothing is wasted","definitionCN":"对金钱、时间或物资的谨慎支配，使什么也不被浪费","example":"Tighter management of the fuel budget halved the depot's winter costs.","exampleCN":"对燃料预算更严格的把控让仓库的冬季开支减半。","why":"What the hand holds it can also ration; the horse-training word grew into the sense of not letting a supply run out.","whyCN":"手握得住东西，也就能分配它；驯马那个词由此长出「不让储备用尽」的意思。"},{"no":"05","title":"Medical care over time","titleCN":"对慢性病的长期治疗与监控","definition":"the treatment and steady control of a disease or condition, especially one that lasts","definitionCN":"对疾病或身体状况进行治疗与持续控制，尤指长期存在的情况","example":"Pain management now includes a weekly check with a nurse.","exampleCN":"疼痛管理现在包含每周由护士做的一次复查。","why":"A doctor who keeps a disease in hand for months is managing it in the same old sense of handling.","whyCN":"医生把一种病在手里管上几个月，用的仍是「用手把控」那个老意思。"},{"no":"06","title":"Control of land and animals","titleCN":"对土地、畜群等自然资源的经营","definition":"the control and use of land, animals or natural resources according to a plan","definitionCN":"按计划对土地、牲畜或自然资源加以控制与使用","example":"The ranch's grazing management keeps the grass from wearing out.","exampleCN":"牧场的放牧管理让草场不至于被耗尽。","why":"Herds and fields were the first things a hand had to manage, so land and livestock keep the oldest layer of meaning.","whyCN":"畜群与田地是手最早要照管的对象，因此土地与牲畜保留了最古老的那层意思。"},{"no":"07","title":"Management as a subject","titleCN":"作为一门学科的管理学","definition":"the study of how organizations are run, taught as an academic subject","definitionCN":"研究组织如何运转的学问，作为一门学科来教授","example":"He added a management course to his engineering degree.","exampleCN":"他在工程学位之外又加了一门管理课程。","why":"In the twentieth century the handling of firms was written down, taught and examined, and so became a discipline.","whyCN":"到了二十世纪，经营企业的门道被写成教材、被教授、被考试，于是成了一门学问。"},{"no":"08","title":"The handling of an event","titleCN":"对某一具体事件或局面的处置","definition":"the way a particular problem, crisis or event is dealt with","definitionCN":"对某个具体问题、危机或事件的应对方式","example":"The management of the flood response drew criticism from residents.","exampleCN":"洪水应对的处置方式招来了居民的批评。","why":"Here the object of handling shrinks from a whole firm to one event, but the gesture itself stays the same.","whyCN":"这里被把控的对象从整个公司缩小到一桩事件，动作本身没有变。"}],"etymology":{"intro":{"en":"Management is the noun of manage, which came through Italian from Latin manus 'hand'. The modern business sense grew out of handling horses, then households, then firms.","cn":"management 是 manage 的名词，而 manage 经意大利语上溯到拉丁 manus「手」；现代企业义由驯马、理家一路扩展到经营公司。"},"items":[{"era":"LATIN MANUS","en":"Manus meant 'hand' and also the power to hold something under control, so handling and controlling were one idea from the start.","cn":"manus 意为「手」，也指把某物握在控制之下的权力，因此「用手摆弄」与「掌控」从一开始就是一个念头。"},{"era":"ITALIAN MANEGGIARE","en":"Italian maneggiare, built on mano 'hand', meant to handle an object and especially to train a horse; the horse sense is the one usually cited for the English verb.","cn":"意大利语 maneggiare 由 mano「手」构成，指用手操作物件，尤指驯马；英语动词最常被追溯到的是驯马这一义。"},{"era":"SIXTEENTH CENTURY","en":"Manage entered English in the sixteenth century, first of handling horses and weapons; management, the noun of the activity, followed in the same period.","cn":"manage 在十六世纪进入英语，最初用于摆弄马匹与兵器；指这项活动的名词 management 也在同一时期出现。"},{"era":"FRENCH REINFORCEMENT","en":"French ménager 'to run a household' is generally thought to have strengthened the sense of ordering a household or estate, which later widened to a business.","cn":"一般认为法语 ménager「料理家务」强化了「安排家务与产业」这一义，后来再扩大到经营企业。"},{"era":"SUFFIX -MENT","en":"The noun suffix -ment, from Latin -mentum through French, names the activity or its result, which is how management came to mean both the doing and the body that does it.","cn":"这个名词后缀经法语来自拉丁语中表示动作或结果的后缀，management 因此既指「做这件事」，也指「做这件事的那群人」。"},{"era":"APPROXIMATE FIRST DATES","en":"The first recorded dates for the business and academic senses are approximate; the word itself is well attested from the sixteenth century.","cn":"企业义与学科义的最早记录年代为约数；这个词本身在十六世纪已有充分记录。"}]},"similar":{"note":{"en":"The first group looks or sounds like management; the second group names neighbouring ways of running something.","cn":"第一组在形音上与 management 相近；第二组是意思相邻的其他「经营、支配」说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"manage","ipa":"/ˈmænɪdʒ/","tag":"same root","definition":"The verb behind the noun; it keeps the plain action of handling a firm or a horse.","definitionCN":"名词背后的动词，保留「摆弄、经营一家公司或一匹马」的直白动作。"},{"word":"manager","ipa":"/ˈmænɪdʒə/","tag":"same root","definition":"The person who performs the activity, formed with the agent suffix; it is not the activity itself.","definitionCN":"做这件事的人，由施动后缀构成，不是这项活动本身。"},{"word":"managerial","ipa":"/ˌmænɪˈdʒɪəriəl/","tag":"same root","definition":"The adjective describing anything connected with managers or their methods.","definitionCN":"形容词，描述与管理者或管理方法有关的事物。"},{"word":"manège","ipa":"/mæˈneɪʒ/","tag":"same Italian source","definition":"A riding school, from the same Italian word for handling horses; the link is the stable, not the office.","definitionCN":"指马术学校，同出那个表示驯马的意大利词；联系在马厩，而不在办公室。"},{"word":"manacle","ipa":"/ˈmænəkl/","tag":"same root, different sense","definition":"From Latin manica 'sleeve, handcuff', also built on manus, but it names a restraint rather than a skill.","definitionCN":"来自拉丁 manica「袖子、手铐」，同样由 manus 构成，但指束缚之物，不是经营的本事。"}]},{"heading":"NEAR MEANING","entries":[{"word":"administration","ipa":"/ədˌmɪnɪˈstreɪʃn/","tag":"near meaning","definition":"The running of an institution according to its rules; it stresses procedure more than direction.","definitionCN":"按规章维持机构运转，强调程序多过掌舵。"},{"word":"governance","ipa":"/ˈɡʌvənəns/","tag":"near meaning","definition":"The system by which an organization is directed and held accountable, rather than the daily work of running it.","definitionCN":"指组织被引导并接受问责的制度，而非日常经营的具体事务。"},{"word":"stewardship","ipa":"/ˈstjuːədʃɪp/","tag":"near meaning","definition":"Careful, responsible handling of money or resources left in one's charge.","definitionCN":"对受托的钱财资源做审慎负责的照管。"},{"word":"control","ipa":"/kənˈtrəʊl/","tag":"near meaning","definition":"Authority to direct something; it names the power, while management names the whole activity.","definitionCN":"支配某事的权力；它指权力本身，management 指整套活动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin root, the real word family and real fixed phrases.","cn":"正常联想使用真实的拉丁词根、真实的同族词与真实的固定搭配。"},"normal":[{"en":"Manus is Latin for hand, so management is literally handling.","cn":"manus 是拉丁语「手」，management 字面上就是「用手摆弄、照管」。"},{"en":"The family runs manage, manager, managerial, manageable and mismanagement.","cn":"同族词有 manage、manager、managerial、manageable 与 mismanagement。"},{"en":"Fixed phrases mark the everyday sense: time management, crisis management, top management.","cn":"固定说法标出日常义：时间管理、危机处理、高层管理层。"},{"en":"The noun suffix -ment turns the act of managing into the thing called management.","cn":"名词后缀把「管理」这个动作变成名为 management 的事物。"},{"en":"Italian maneggiare first meant to train a horse by hand, which is the oldest picture in the word.","cn":"意大利语 maneggiare 最初指用手驯马，这是这个词里最古老的画面。"}],"abstract":[{"en":"Picture a hand closing on four loose threads at once and pulling them into one line.","cn":"想象一只手一次攥住四根散线，把它们拉成一条直线。"},{"en":"Picture a rider who never pulls hard, only shifts weight, and the whole herd follows.","cn":"想象一位从不猛拉缰绳、只挪动重心的骑手，整群马都跟着走。"},{"en":"Picture a desk where every paper is already filed before anyone asks for it.","cn":"想象一张桌子，别人还没开口要，每份纸就已经归好了位。"}]},"examples":[{"en":"Local clinics improved their management of patient records last year.","cn":"本地诊所去年改善了对病人档案的管理。"},{"en":"The management of the harbour was split between two agencies.","cn":"港口的经营权被分给了两个机构。"},{"en":"She studied management after six years on the factory floor.","cn":"在车间干了六年后，她去攻读管理学。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「man（人）+ age（年纪）+ ment（名词）」——管人管到上年纪，就是管理","word":"management"},"root":"拉丁 manus「手」→ 意大利 maneggiare「用手操作、驯马」→ 法语 ménager「料理家务」→ 英语 manage「管理」；末尾是名词后缀。","sensesIntro":{"en":"Eight senses follow one hand: it runs a firm, becomes a body of managers, handles people, rations supplies, holds a disease in check, works land and herds, turns into a taught subject, and finally grips a single event.","cn":"八个义项围绕同一只手：经营一家公司、聚成一群管理者、应对人、分配物资、把病管住、照料土地与畜群、变成一门被教授的学问，最后攥住一桩具体事件。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand gathers loose threads and pulls them into a single rein.","cn":"核心意象：一只手把散开的线头收拢，拉成一根缰绳。"},"chain":["HAND ON THE REIN","FIRM UNDER CONTROL","BODY OF MANAGERS","HANDLING PEOPLE","RATIONED SUPPLIES","TAUGHT SUBJECT"],"branches":[{"senses":"01","en":"THE HAND ITSELF: planning, organizing and controlling a whole firm is the original gesture at full size.","cn":"手本身：对一个公司作计划、组织与控制，就是最初那个动作放到最大。"},{"senses":"02 · 03","en":"WHO HOLDS THE REIN: the handlers become a standing body, and their feel for people becomes a skill.","cn":"谁握着缰绳：做事的人聚成常设群体，他们待人的手感变成一种本事。"},{"senses":"04","en":"WHAT IS RATIONED: the hand decides how much fuel, time or money may leave the store.","cn":"被分配的东西：手决定有多少燃料、时间或钱可以从库里出去。"},{"senses":"05 · 06","en":"CARE OVER TIME: a disease and a pasture are both kept in condition by regular attention.","cn":"长期的照料：疾病与牧场都靠按时看顾才维持在可用状态。"},{"senses":"07 · 08","en":"FROM PRACTICE TO OBJECT: the habit is written down as a subject, or narrowed to one event.","cn":"从做法变成对象：这套习惯被写成学科，或被收窄到一桩事件上。"}]},"affixes":{"intro":{"en":"Management is built from a Latin hand and a noun suffix, and the hand also supports several English words.","cn":"management 由一个拉丁语「手」和一个名词后缀构成，这个「手」还支撑起若干英语词。"},"latinIntro":{"en":"Latin manus gives manual, manacle and mandate; the Italian verb maneggiare gives manage and its English family.","cn":"拉丁 manus 衍生 manual（手册）、manacle（手铐）与 mandate（委托）；意大利语 maneggiare 衍生 manage 及其英语词族。"},"items":[{"word":"manus","structure":"Latin noun, fourth declension","meaning":"hand; power to hold","meaningCN":"手；握持之力","example":"The root supplies the picture of a hand on a rein.","exampleCN":"这个词根提供「手握缰绳」的画面。"},{"word":"maneggiare","structure":"Italian verb, from mano","meaning":"to handle; to train a horse","meaningCN":"用手操作；驯马","example":"The stable sense is the oldest source of the English word.","exampleCN":"马厩里的这一义是英语词最早的来源。"},{"word":"manage","structure":"maneggiare through French to English","meaning":"to run or handle","meaningCN":"经营；应付","example":"One hand can manage a horse, a household or a firm.","exampleCN":"一只手可以管马、理家，也可以管公司。"},{"word":"management","structure":"manage plus -ment (activity or result)","meaning":"the activity of running; the managers","meaningCN":"经营；管理层","example":"The suffix turns the deed into the thing named.","exampleCN":"后缀把动作变成被命名的事物。"},{"word":"manager","structure":"manage plus -er (one who acts)","meaning":"the person who runs the work","meaningCN":"负责运转的人","example":"The agent suffix names the hand that holds the rein.","exampleCN":"施动后缀点出握缰的那只手。"},{"word":"managerial","structure":"manager plus -ial (relating to)","meaning":"of managers or their methods","meaningCN":"管理者的；管理方法的","example":"The adjective describes the hand's work, not the hand.","exampleCN":"形容词描述手的活儿，而不是手本身。"},{"word":"manageable","structure":"manage plus -able (can be done)","meaning":"able to be controlled","meaningCN":"可控的；易对付的","example":"What can be held in one hand is manageable.","exampleCN":"一只手握得住的东西就是可控的。"},{"word":"mismanagement","structure":"mis- (wrongly) plus management","meaning":"running something badly","meaningCN":"管理不善","example":"The prefix says the hand gripped the rein the wrong way.","exampleCN":"前缀说明这只手握错了缰绳。"},{"word":"-ment","structure":"Latin -mentum through French","meaning":"suffix of activity or result","meaningCN":"表示动作或结果的名词后缀","example":"It is the same ending as in agreement and movement.","exampleCN":"它与「同意」「移动」两个词用的是同一个词尾。"}],"latinEntries":[{"word":"manus","structure":"manus, manus (n., fourth declension)","meaning":"hand","meaningCN":"手"},{"word":"mandare","structure":"manus plus dare 'to give'","meaning":"to put into someone's hand; entrust","meaningCN":"交到他人手里；委托"},{"word":"manica","structure":"manica, manicae (n., first declension)","meaning":"sleeve; glove; handcuff","meaningCN":"袖子；手套；手铐"}],"derivatives":[{"word":"manager","pos":"n.","zh":"管理者；经理"},{"word":"managerial","pos":"adj.","zh":"管理的；经理层的"},{"word":"manageable","pos":"adj.","zh":"可控制的"},{"word":"mismanagement","pos":"n.","zh":"管理不善"}]}},{"word":"manager","ipa_uk":"/ˈmænɪdʒə/","ipa_us":"/ˈmænɪdʒər/","definition_zh":"经理；管理者；球队或乐队的事务负责人；某项事务的专责人","definition_en":"a person whose job is to organize and control the work of a business, team or activity","core_image":"缰绳从一只手伸向前方，前后都是一队等着被安排的人","scene":"演出前一天设备出了故障，那个人逐个打电话借音箱、改场地、重排时间。A manager solves problems before the audience notices.","sceneCN":"这里 manager 指为一项活动统筹人、事与资源的人（第 1 个义项：负责机构或团队运转的人）；句意：一位经理在观众察觉之前就把问题解决掉。图中可辨识物件：音箱、改期通知、场地平面图、装设备的木箱。","pos":[{"tag":"n.","zh":"经理；管理者；事务负责人"}],"collocations":[{"phrase":"store manager","zh":"门店经理"},{"phrase":"project manager","zh":"项目经理"},{"phrase":"sales manager","zh":"销售经理"},{"phrase":"general manager","zh":"总经理"},{"phrase":"line manager","zh":"直线主管；直接上级"},{"phrase":"team manager","zh":"团队主管"}],"forms":[{"label":"单数","form":"manager"},{"label":"复数","form":"managers"},{"label":"动词原形","form":"manage"},{"label":"抽象名词","form":"management"},{"label":"形容词","form":"managerial"},{"label":"职位名词","form":"managership"}],"derivatives":[{"word":"managerial","pos":"adj.","zh":"管理的；经理层的"},{"word":"managership","pos":"n.","zh":"经理职位"},{"word":"manageress","pos":"n.","zh":"女经理（旧称）"},{"word":"management","pos":"n.","zh":"管理；管理层"},{"word":"manage","pos":"v.","zh":"管理；经营"}],"senses":[{"no":"01","title":"The person who runs a business","titleCN":"掌管一家企业或团队的人","definition":"a person employed to run a business, a team or a group of workers","definitionCN":"受雇掌管一家企业、一支团队或一群工人的人","example":"The manager of the repair shop orders parts and sets the rota.","exampleCN":"修理店的经理负责订零件、排班表。","why":"Manager is the noun of the hand that holds the rein, so it names whoever keeps the whole body of work moving.","whyCN":"manager 是握缰那只手的名词形式，指让全部工作继续转动的那个人。"},{"no":"02","title":"Head of one department","titleCN":"某一部门的负责人","definition":"the person who heads a single department or function within a larger organization","definitionCN":"在较大机构中主管某一个部门或职能的人","example":"The sales manager reports to the regional director.","exampleCN":"销售经理向区域总监汇报。","why":"One department is a single rein of the firm, and its head pulls only that one.","whyCN":"一个部门只是公司的一根缰绳，它的负责人只拉这一根。"},{"no":"03","title":"Boss of a sports team","titleCN":"运动队的领队或主教练","definition":"the person who picks the players and directs a team during matches","definitionCN":"挑选球员并在比赛中指挥球队的人","example":"The manager changed formation after the first goal.","exampleCN":"第一个球之后，主教练换了阵型。","why":"The Italian verb behind the word was used of training horses, so a team boss keeps the oldest sense alive.","whyCN":"这个词背后的意大利语动词用于驯马，因此球队主帅保留了最古老的那层意思。"},{"no":"04","title":"Business agent for performers","titleCN":"艺人或乐队的事务代理人","definition":"someone who handles contracts, bookings and money for a performer or group","definitionCN":"替艺人或团体处理合同、演出安排与收入的人","example":"Her manager turned down the film offer on her behalf.","exampleCN":"她的经纪人替她推掉了那部电影的邀约。","why":"A performer needs someone to handle contracts the way a rider handles the direction of a horse.","whyCN":"艺人需要有人替他打理合同，就像骑手替马把握方向。"},{"no":"05","title":"Someone who looks after another's money or property","titleCN":"替他人打理钱财产业的人","definition":"a person employed to look after money, land or property for its owner","definitionCN":"受雇替业主照管钱财、土地或房产的人","example":"The estate manager hires the gardeners and pays the bills.","exampleCN":"产业经理雇请园丁，并支付各项账单。","why":"Money and land are things a hand holds on another's behalf, so the handler is named after the hand.","whyCN":"钱财与土地是手替别人握着的东西，因此这个代管者以「手」来命名。"},{"no":"06","title":"A program that organizes things","titleCN":"整理文件或窗口的计算机程序","definition":"a piece of software that organizes files, windows or settings","definitionCN":"整理文件、窗口或设置的软件","example":"The download manager keeps the parts in order.","exampleCN":"下载管理器把各个分段按顺序放好。","why":"Software does by rule what a hand did by feel: it keeps the pieces sorted in their places.","whyCN":"软件用规则去做手凭手感做的事：把各个零碎归到各自的位置。"},{"no":"07","title":"The person in charge of one project","titleCN":"某一项目的专责负责人","definition":"the person responsible for one project from start to finish","definitionCN":"从头到尾对某一个项目负责的人","example":"The project manager moved the launch back by a month.","exampleCN":"项目经理把上线日期往后推了一个月。","why":"A project is one bounded task, and its manager holds only that task until it is finished.","whyCN":"一个项目是一项有边界的工作，项目经理只管这一件，直到它完成。"},{"no":"08","title":"The person in charge of a shop","titleCN":"一家店铺的现场负责人","definition":"the person who runs a single shop or branch day to day","definitionCN":"日复一日经营一家店铺或分店的人","example":"The store manager counts the till before locking up.","exampleCN":"门店经理在锁门前清点收银账目。","why":"A shop is a small ring of work, and one person keeps that ring turning every day.","whyCN":"一家店是一个小小的循环，一个人每天让它转起来。"}],"etymology":{"intro":{"en":"Manager adds the agent suffix to manage, a word that came from Italian horse handling. The role names grew apart as firms, clubs and estates each needed a handler.","cn":"manager 在 manage 之后加上施动后缀；manage 来自意大利语的驯马行话。随着公司、俱乐部与产业各自需要有人打理，这个称呼分化出不同角色。"},"items":[{"era":"LATIN MANUS","en":"Manus 'hand' also carried the idea of control, which is why a handler and a controller share one root.","cn":"manus「手」同时带有掌控之意，因此「动手的人」与「掌控的人」共用同一个词根。"},{"era":"ITALIAN MANEGGIARE","en":"Maneggiare meant to handle and especially to train a horse; the trainer of horses is the oldest kind of manager.","cn":"maneggiare 指用手操作，尤指驯马；驯马人就是最古老的一类管理者。"},{"era":"SIXTEENTH CENTURY","en":"Manage is recorded in English from the sixteenth century, and manager, the one who manages, from the late sixteenth century; both dates are approximate.","cn":"manage 在十六世纪见于英语记录，指做这件事的 manager 则见于十六世纪晚期；两个年代都是约数。"},{"era":"AGENT SUFFIX","en":"The Old English suffix -er marks the doer of an action, so manager is literally the handling one.","cn":"古英语的施动后缀标记动作的执行者，因此 manager 字面上就是「动手打理的那一个」。"},{"era":"NEW ROLES","en":"Sports clubs, theatres and country estates gave the word its separate everyday roles in the eighteenth and nineteenth centuries.","cn":"体育俱乐部、剧院与乡间产业在十八、十九世纪分别赋予这个词不同的日常角色。"}]},"similar":{"note":{"en":"The first group shares shape or root with manager; the second group names other people who direct work.","cn":"第一组与 manager 共享形音或词根；第二组是其他指挥工作的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"manage","ipa":"/ˈmænɪdʒ/","tag":"same root","definition":"The verb, naming the action rather than the person.","definitionCN":"动词，指动作而不是人。"},{"word":"management","ipa":"/məˈneɪdʒmənt/","tag":"same root","definition":"The activity or the whole body of managers, not one individual.","definitionCN":"指这项活动或整个管理层，不是单个个人。"},{"word":"manège","ipa":"/mæˈneɪʒ/","tag":"same Italian source","definition":"A riding school, from the same Italian word for handling horses.","definitionCN":"马术学校，同出那个表示驯马的意大利词。"},{"word":"mannequin","ipa":"/ˈmænɪkɪn/","tag":"different root","definition":"From Dutch manneken 'little man'; the shared shape is accidental, and it names a dummy.","definitionCN":"来自荷兰语 manneken「小人」；形似只是巧合，它指服装模特或假人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"supervisor","ipa":"/ˈsuːpəvaɪzə/","tag":"near meaning","definition":"One who watches over workers directly; the emphasis is on checking, not on running the whole unit.","definitionCN":"直接看管工人的人，强调检查，而不是经营整个单元。"},{"word":"administrator","ipa":"/ədˈmɪnɪstreɪtə/","tag":"near meaning","definition":"One who runs an institution's procedures and records; the focus is rules and paper.","definitionCN":"维持机构程序与记录的人，重心在规章与文书。"},{"word":"director","ipa":"/dəˈrektə/","tag":"near meaning","definition":"A member of the top board or the head of a whole organization.","definitionCN":"董事会成员或整个机构的负责人。"},{"word":"boss","ipa":"/bɒs/","tag":"near meaning","definition":"An informal word for whoever gives orders; it says nothing about handling work well.","definitionCN":"指发号施令者的口语词，并不含「把工作打理得好」的意思。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real suffix, the real word family and real job titles.","cn":"正常联想使用真实的后缀、真实的同族词与真实的职位名称。"},"normal":[{"en":"Manus is hand, and -er is the doer, so manager is the one with a hand on the work.","cn":"manus 是手，施动后缀指做事的人，manager 就是那只按在工作上的手。"},{"en":"The family runs manage, management, managerial and managership.","cn":"同族词有 manage、management、managerial 与 managership。"},{"en":"Real titles show the spread: store manager, project manager, sales manager.","cn":"真实职位显示它的分布：门店经理、项目经理、销售经理。"},{"en":"The oldest picture is a horse trainer, because the Italian verb meant exactly that.","cn":"最古老的画面是驯马人，因为那个意大利语动词本就是这个意思。"},{"en":"A manager is measured by the work that keeps moving, not by tasks done personally.","cn":"衡量一位经理的，是继续运转的工作，而不是他亲手做完的活儿。"}],"abstract":[{"en":"Picture a stagehand who fixes a broken light while the curtain is still closed.","cn":"想象幕布还没拉开，一名舞台工作人员已经把坏掉的灯修好。"},{"en":"Picture a rider who steers with the knees and leaves both hands free.","cn":"想象一位用膝盖控向、腾出双手的骑手。"},{"en":"Picture a person standing at the joint of four pipes, turning each valve a little.","cn":"想象一个人站在四根管道的接合处，把每个阀门都拧一点。"}]},"examples":[{"en":"The branch manager rewrote the rota so nobody worked six days straight.","cn":"分店经理重排了班表，没人再连上六天。"},{"en":"A good manager knows which decisions can wait until Monday.","cn":"好的管理者知道哪些决定可以等到周一再做。"},{"en":"The band's manager cancelled the tour rather than cut the fee.","cn":"乐队经纪人宁可取消巡演，也不肯压低酬劳。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「man（人）+ ager（上年纪的人）」——公司里管人又上了年纪的那位，就是经理","word":"manager"},"root":"拉丁 manus「手」→ 意大利 maneggiare「驯马、操作」→ 英语 manage「管理」+ 施动后缀「做事的人」。","sensesIntro":{"en":"Eight senses follow one hand from a whole firm down to a single shop: the general runner, a department head, a team boss, an agent for another, a keeper of property, a sorting program, one project and one counter.","cn":"八个义项沿着同一只手，从整个公司缩小到一家店铺：总管、部门负责人、球队主帅、代他人打理事务者、产业代管人、整理文件的程序、单个项目、一个柜台。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand on the rein, with a line of people and tasks behind it.","cn":"核心意象：一只手握着缰绳，身后是一队人与一列待办的事。"},"chain":["HAND ON THE REIN","RUNNER OF A FIRM","HEAD OF A FUNCTION","TEAM BOSS","KEEPER OF ONE TASK","SMALLEST RING"],"branches":[{"senses":"01","en":"THE WHOLE REIN: the general manager holds every part of the business at once.","cn":"整根缰绳：总经理同时握住企业的每一部分。"},{"senses":"02 · 03","en":"TWO KINDS OF CAPTAIN: one leads a department, the other leads players.","cn":"两种带队人：一个带部门，一个带球员。"},{"senses":"04 · 05","en":"ACTING FOR ANOTHER: an agent handles a career, an estate manager handles property.","cn":"代他人出手：经纪人打理职业生涯，产业经理打理房产。"},{"senses":"06 · 07","en":"ORGANIZING INSTRUMENTS: software sorts files, a project lead sorts tasks.","cn":"整理的工具：软件归置文件，项目负责人归置任务。"},{"senses":"08","en":"ONE SMALL RING: a single shop is the smallest circle a manager keeps turning.","cn":"最小的循环：一家店铺是经理让它转动的最小一圈。"}]},"affixes":{"intro":{"en":"Manager is a Latin-rooted verb plus an English agent suffix, and the same root reaches several everyday words.","cn":"manager 是一个拉丁词根的动词加上英语施动后缀，这个词根还通向若干日常词。"},"latinIntro":{"en":"Latin manus gives manual, manacle and mandate; the Italian verb gives manage and its English family.","cn":"拉丁 manus 衍生 manual、manacle 与 mandate；意大利语动词衍生 manage 及其英语词族。"},"items":[{"word":"manus","structure":"Latin noun, fourth declension","meaning":"hand; power to hold","meaningCN":"手；握持之力","example":"The root supplies the hand that holds the work.","exampleCN":"这个词根提供握持工作的那只手。"},{"word":"maneggiare","structure":"Italian verb, from mano","meaning":"to handle; to train a horse","meaningCN":"用手操作；驯马","example":"The horse trainer is the oldest manager.","exampleCN":"驯马人是最古老的管理者。"},{"word":"manage","structure":"maneggiare through French to English","meaning":"to run or handle","meaningCN":"经营；应付","example":"The verb names the action behind every manager.","exampleCN":"这个动词命名每位经理背后的动作。"},{"word":"manager","structure":"manage plus -er (one who acts)","meaning":"one who runs the work","meaningCN":"负责运转的人","example":"The suffix marks the doer, not the deed.","exampleCN":"后缀标出执行者，而不是动作。"},{"word":"management","structure":"manage plus -ment (activity)","meaning":"running an organization; the managers","meaningCN":"经营；管理层","example":"The noun names the activity the manager performs.","exampleCN":"名词指经理所做的这项活动。"},{"word":"managerial","structure":"manager plus -ial (relating to)","meaning":"of managers or their methods","meaningCN":"管理者的；管理方法的","example":"The adjective shifts the focus from person to practice.","exampleCN":"形容词把人换成做法。"},{"word":"managership","structure":"manager plus -ship (office or state)","meaning":"the post of manager","meaningCN":"经理职位","example":"The suffix names the office rather than the person.","exampleCN":"后缀指职位，不指人。"},{"word":"manageable","structure":"manage plus -able (can be done)","meaning":"able to be controlled","meaningCN":"可控的；易对付的","example":"A load one hand can hold is manageable.","exampleCN":"一只手能握住的量就是可控的。"},{"word":"-er","structure":"Old English agent suffix","meaning":"one who performs an action","meaningCN":"表示动作执行者的后缀","example":"It also builds teacher, driver and keeper.","exampleCN":"它也构成「教师」「司机」与「看守者」等词。"}],"latinEntries":[{"word":"manus","structure":"manus, manus (n., fourth declension)","meaning":"hand","meaningCN":"手"},{"word":"mandare","structure":"manus plus dare 'to give'","meaning":"to entrust, put in hand","meaningCN":"委托；交到手里"},{"word":"manica","structure":"manica, manicae (n., first declension)","meaning":"sleeve; glove; handcuff","meaningCN":"袖子；手套；手铐"}],"derivatives":[{"word":"managerial","pos":"adj.","zh":"管理的；经理层的"},{"word":"managership","pos":"n.","zh":"经理职位"},{"word":"manageress","pos":"n.","zh":"女经理（旧称）"},{"word":"management","pos":"n.","zh":"管理；管理层"}]}},{"word":"managerial","ipa_uk":"/ˌmænɪˈdʒɪəriəl/","ipa_us":"/ˌmænəˈdʒɪriəl/","definition_zh":"管理的；经理阶层的；与管理方法有关的","definition_en":"relating to the running of an organization or to managers and their methods","core_image":"一张并排摆着三张表格的桌子，一只手把它们对齐到同一条边上","scene":"评审会上，人们不再问某个人做了多少件活，而问他怎样分派任务、怎样花掉那笔预算。The panel now judges managerial skill rather than sheer output.","sceneCN":"这里 managerial 指与管理职责和管理方法有关的（第 1 个义项：属于管理工作的）；句意：评审小组现在评判的是管理能力，而不是单纯的产出。图中可辨识物件：三张表格、预算信封、座牌、铅笔。","pos":[{"tag":"adj.","zh":"管理的；经理阶层的；管理方法的"}],"collocations":[{"phrase":"managerial position","zh":"管理职位"},{"phrase":"managerial staff","zh":"管理人员"},{"phrase":"managerial skills","zh":"管理技能"},{"phrase":"managerial experience","zh":"管理经验"},{"phrase":"managerial level","zh":"管理层级"},{"phrase":"managerial style","zh":"管理风格"}],"forms":[{"label":"原级","form":"managerial"},{"label":"比较级","form":"more managerial"},{"label":"最高级","form":"most managerial"},{"label":"副词","form":"managerially"},{"label":"名词（经理）","form":"manager"},{"label":"名词（管理）","form":"management"}],"derivatives":[{"word":"managerially","pos":"adv.","zh":"以管理的方式；在管理层面"},{"word":"manager","pos":"n.","zh":"经理；管理者"},{"word":"management","pos":"n.","zh":"管理；管理层"},{"word":"manage","pos":"v.","zh":"管理；经营"}],"senses":[{"no":"01","title":"Of management as an activity","titleCN":"属于管理这项工作的","definition":"connected with the work of planning and running an organization","definitionCN":"与计划并经营一个组织的工作有关的","example":"The report separates managerial duties from technical ones.","exampleCN":"这份报告把管理职责与技术职责分开。","why":"The adjective is built on manager, so it describes the work the manager does rather than the manager in person.","whyCN":"这个形容词由 manager 构成，因此描述的是经理所做的活，而不是经理其人。"},{"no":"02","title":"Of a manager's post","titleCN":"属于经理职位的","definition":"belonging to a post that carries authority over other staff","definitionCN":"属于对其他人具有管辖权的职位","example":"She was promoted into a managerial post after two years.","exampleCN":"两年后她被提升到一个管理职位。","why":"A post is managerial when the hand on the rein also has the right to give orders.","whyCN":"当握缰的手同时拥有下令的权力时，这个职位就是管理性的。"},{"no":"03","title":"The middle layer of jobs","titleCN":"介于员工与高层之间的管理层级","definition":"belonging to the tier of jobs between ordinary staff and senior executives","definitionCN":"属于普通员工与高层主管之间的那一层职位","example":"Most managerial jobs in the group sit two levels below the board.","exampleCN":"集团里多数管理职位都在董事会之下两级。","why":"Between the whole-firm hand and the single worker there is a middle grip, and the adjective marks that layer.","whyCN":"在掌控整个公司的手与单个工人之间还有一道中间的握持，形容词标出的正是这一层。"},{"no":"04","title":"Typical of a manager's manner","titleCN":"带有管理者习气的","definition":"showing the tone or habits of someone used to giving instructions","definitionCN":"显出习惯了发号施令者的口吻或做派","example":"His managerial tone made the volunteers uneasy.","exampleCN":"他那套管理者的口吻让志愿者感到不自在。","why":"Once a person gives orders all day, the manner sticks, and the adjective can describe that manner alone.","whyCN":"一个人整天发号施令，做派就会固定在身上，形容词也能单指这种做派。"},{"no":"05","title":"Of budgets and resource control","titleCN":"有关预算与资源支配的","definition":"concerned with controlling money, staff and other resources","definitionCN":"与掌控金钱、人员及其他资源有关的","example":"Managerial control of the printing budget saved a full month's cost.","exampleCN":"对印刷预算的管理性控制省下了整整一个月的开支。","why":"Controlling a budget is rationing what the hand releases, which is the resource side of the same root.","whyCN":"控制预算就是管住手放出多少，这正是同一词根里「资源」的那一面。"},{"no":"06","title":"Of management as a subject","titleCN":"作为学科的管理学的","definition":"belonging to management as a subject studied and taught","definitionCN":"属于作为一门被研究与教授的学科的管理学","example":"She chose managerial economics as her second field.","exampleCN":"她选了管理经济学作为第二专业方向。","why":"When the practice was written into textbooks, its adjective moved into the classroom.","whyCN":"当这套做法被写进教科书，它的形容词也跟着进了课堂。"},{"no":"07","title":"Of decisions about staff","titleCN":"涉及人事决定的","definition":"involving decisions about staff, such as hiring, appraisal or dismissal","definitionCN":"涉及招聘、考评或解雇等人员决定的","example":"The union objected to managerial decisions taken without notice.","exampleCN":"工会反对那些不事先通知就作出的人事决定。","why":"People are the first thing a handler handles, so hiring and dismissal are the most managerial acts of all.","whyCN":"人是最先被「打理」的对象，因此招聘与解雇是最具管理性质的行为。"},{"no":"08","title":"Showing tact in handling people","titleCN":"显出待人处事分寸的","definition":"showing skill and tact in dealing with people and awkward situations","definitionCN":"在与人和棘手局面打交道时显出技巧与分寸的","example":"It was a managerial way of saying no that left nobody humiliated.","exampleCN":"那是一种很有管理分寸的拒绝方式，谁也没有被羞辱。","why":"The oldest sense of the root is feel rather than force, and the adjective still praises exactly that feel.","whyCN":"这个词根最古老的意思是手感而非蛮力，形容词至今赞美的正是这份手感。"}],"etymology":{"intro":{"en":"Managerial is a nineteenth-century adjective built on manager, which itself goes back through Italian to Latin manus 'hand'. Its meaning widened from the manager's person to the manager's methods.","cn":"managerial 是十九世纪在 manager 之上构成的形容词，而 manager 经意大利语上溯到拉丁 manus「手」。它的意思从「经理其人」扩展到「经理的做事方法」。"},"items":[{"era":"LATIN MANUS","en":"Manus 'hand' also implied control, so anything derived from it can describe either handling or authority.","cn":"manus「手」也含掌控之意，因此由它派生的词既能指动手打理，也能指管辖权。"},{"era":"ITALIAN MANEGGIARE","en":"Maneggiare meant to handle an object and to train a horse, the practical skill behind every later manager.","cn":"maneggiare 指用手操作物件、驯马，是后来一切管理者背后的实用技艺。"},{"era":"ENGLISH MANAGE","en":"Manage reached English in the sixteenth century, and manager, the person, followed soon after.","cn":"manage 在十六世纪进入英语，指人的 manager 随后不久出现。"},{"era":"ADJECTIVE SUFFIX","en":"The ending -ial, from Latin -alis through French, means 'relating to', so managerial means relating to managers or to managing.","cn":"这个形容词词尾经法语来自拉丁语中表示「与……有关」的后缀，因此 managerial 意为与经理或管理有关。"},{"era":"NINETEENTH CENTURY","en":"Managerial is recorded from the early nineteenth century, when large firms began to separate owners from salaried managers; the first date is approximate.","cn":"managerial 的记录始于十九世纪早期，当时大企业开始把所有者与受薪经理分开；最早年代为约数。"}]},"similar":{"note":{"en":"The first group shares the manager root or a near shape; the second group holds adjectives of neighbouring authority.","cn":"第一组共享 manager 词根或形音相近；第二组是表示相邻权责关系的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"manager","ipa":"/ˈmænɪdʒə/","tag":"same root","definition":"The person; the adjective only describes that person's work or manner.","definitionCN":"指人本身；形容词只描述那个人的工作或做派。"},{"word":"management","ipa":"/məˈneɪdʒmənt/","tag":"same root","definition":"The activity or the body of managers, where the adjective describes what belongs to it.","definitionCN":"指活动或管理层，形容词描述属于它的东西。"},{"word":"manual","ipa":"/ˈmænjuəl/","tag":"same root, different sense","definition":"From Latin manualis, also built on manus 'hand', but it means work done by hand or a handbook.","definitionCN":"来自拉丁 manualis，同样由 manus「手」构成，但指用手做的活或手册。"},{"word":"manacle","ipa":"/ˈmænəkl/","tag":"same root, different sense","definition":"From Latin manica 'handcuff', again from manus, but it names a restraint.","definitionCN":"来自拉丁 manica「手铐」，同样出自 manus，但指束缚之物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"administrative","ipa":"/ədˈmɪnɪstrətɪv/","tag":"near meaning","definition":"About procedures, records and rules rather than about directing people.","definitionCN":"关于程序、记录与规章，而不是关于指挥人。"},{"word":"supervisory","ipa":"/ˌsuːpəˈvaɪzəri/","tag":"near meaning","definition":"About watching and checking staff, a narrower job than running a unit.","definitionCN":"关于看管与检查员工，比经营一个单元窄。"},{"word":"executive","ipa":"/ɪɡˈzekjətɪv/","tag":"near meaning","definition":"About the most senior level, above the managerial tier.","definitionCN":"关于最高层，位于管理层之上。"},{"word":"organizational","ipa":"/ˌɔːɡənaɪˈzeɪʃənl/","tag":"near meaning","definition":"About the structure of an organization rather than its handling.","definitionCN":"关于组织的结构，而不是它的运作打理。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real root, the real suffix and real job language.","cn":"正常联想使用真实的词根、真实的后缀与真实的职位用语。"},"normal":[{"en":"Manager plus the adjective ending -ial gives managerial, 'of a manager'.","cn":"manager 加上表「与……有关」的形容词词尾得到 managerial，意为「经理的」。"},{"en":"The family runs manage, manager, management, managerial and managerially.","cn":"同族词有 manage、manager、management 与 managerially。"},{"en":"Job language pairs it with position, staff, skills and experience.","cn":"职位用语常把它与「职位」「人员」「技能」「经验」等词搭配。"},{"en":"Manus is hand, so managerial work is work done by hand at one remove.","cn":"manus 是手，因此管理工作是隔着一层的「用手做的活」。"},{"en":"The word dates from the age when owners stopped running their own firms.","cn":"这个词诞生于所有者不再亲自经营企业的年代。"}],"abstract":[{"en":"Picture a hand that no longer touches the machine but still sets its pace.","cn":"想象一只手不再碰机器，却仍然决定它的速度。"},{"en":"Picture a table with three forms pulled to one edge, so all three start level.","cn":"想象桌上三张表格被拉到同一条边，三张都从同一处开始。"},{"en":"Picture a rider who guides by shifting weight and never jerks the rein.","cn":"想象一位只挪重心、从不猛拽缰绳的骑手。"}]},"examples":[{"en":"The firm offered him a managerial role after the merger.","cn":"合并之后，公司给了他一个管理职位。"},{"en":"Managerial mistakes are usually visible only months later.","cn":"管理上的失误通常要几个月后才看得出来。"},{"en":"Her managerial style was to ask questions before giving orders.","cn":"她的管理风格是先提问，再下命令。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「manager（经理）+ ial（……的）」——经理那一套的，就是管理的","word":"managerial"},"root":"拉丁 manus「手」→ 意大利 maneggiare「动手操作、驯马」→ manage「管理」→ manager「管理者」+ -ial（与……有关的形容词后缀）。","sensesIntro":{"en":"Eight senses move from the work itself to the post, the middle tier, the manner, the budget, the classroom, the staffing decision and finally the tact that the old root always implied.","cn":"八个义项从工作本身出发，依次指向职位、中间层级、做派、预算、课堂、人事决定，最后落到那个古老词根一直含着的分寸感。"},"semanticMap":{"core":{"en":"CORE IMAGE: three loose forms are pulled level by one hand that does not fill them in.","cn":"核心意象：三张散乱的表格被一只手拉齐，而这只手并不替它们填写。"},"chain":["HAND ON THE WORK","THE POST","THE MIDDLE TIER","THE MANNER","THE BUDGET","THE CLASSROOM"],"branches":[{"senses":"01 · 04","en":"THE ACT AND ITS TONE: running the work, and the habit that running it leaves on a person.","cn":"动作与口气：经营这项工作，以及这项工作在一个人身上留下的习惯。"},{"senses":"02 · 03","en":"THE LADDER: a post with authority, and the rung it normally occupies.","cn":"梯子：一个带权力的职位，以及它通常所在的那一级。"},{"senses":"05","en":"WHAT IS RATIONED: budgets and staff are released by the same grip.","cn":"被分配之物：预算与人员都由同一道握持放出。"},{"senses":"06","en":"THE CLASSROOM: the practice becomes a subject with textbooks.","cn":"课堂：这套做法变成有教科书的学科。"},{"senses":"07 · 08","en":"THE HUMAN SIDE: hiring or dismissing, and doing either without humiliation.","cn":"人的一面：招人或辞人，以及让两者都不带羞辱地完成。"}]},"affixes":{"intro":{"en":"Managerial is the adjective of manager, so its parts are the Latin hand, the Italian verb, the English noun and an adjective ending.","cn":"managerial 是 manager 的形容词，因此它的构件是拉丁语的手、意大利语动词、英语名词与一个形容词词尾。"},"latinIntro":{"en":"Latin manus reaches manual and manacle; the manager family reaches manage, management and managerially.","cn":"拉丁 manus 通向 manual（手册）与 manacle（手铐）；manager 词族通向 manage、management 与 managerially。"},"items":[{"word":"manus","structure":"Latin noun, fourth declension","meaning":"hand; control","meaningCN":"手；掌控","example":"The root supplies the grip behind every managerial act.","exampleCN":"这个词根提供每个管理动作背后的握持。"},{"word":"maneggiare","structure":"Italian verb, from mano","meaning":"to handle; to train a horse","meaningCN":"用手操作；驯马","example":"The stable skill became the office skill.","exampleCN":"马厩里的技艺变成了办公室里的技艺。"},{"word":"manager","structure":"manage plus -er","meaning":"the person who runs the work","meaningCN":"负责运转的人","example":"The noun is the base of this adjective.","exampleCN":"这个名词是形容词的基座。"},{"word":"managerial","structure":"manager plus -ial (relating to)","meaning":"of a manager or of managing","meaningCN":"经理的；管理的","example":"The ending adds the relation, not a new object.","exampleCN":"词尾加上的是关系，不是新对象。"},{"word":"managerially","structure":"managerial plus -ly (in a manner)","meaning":"in a managerial way","meaningCN":"以管理的方式","example":"The adverb describes how something is done.","exampleCN":"副词描述某事是以何种方式做的。"},{"word":"management","structure":"manage plus -ment","meaning":"the activity; the managers","meaningCN":"管理；管理层","example":"The abstract noun sits beside the adjective.","exampleCN":"抽象名词与这个形容词并列。"},{"word":"manageable","structure":"manage plus -able","meaning":"able to be controlled","meaningCN":"可控的","example":"The same root can say what can be held.","exampleCN":"同一词根也能说什么是握得住的。"},{"word":"mismanagement","structure":"mis- plus management","meaning":"bad running","meaningCN":"管理不善","example":"The prefix marks a grip that slipped.","exampleCN":"前缀标出一次滑手的握持。"}],"latinEntries":[{"word":"manus","structure":"manus, manus (n., fourth declension)","meaning":"hand","meaningCN":"手"},{"word":"manualis","structure":"manualis, manuale (adj.)","meaning":"of the hand","meaningCN":"手的；用手做的"},{"word":"manica","structure":"manica, manicae (n., first declension)","meaning":"sleeve; handcuff","meaningCN":"袖子；手铐"}],"derivatives":[{"word":"manager","pos":"n.","zh":"经理"},{"word":"management","pos":"n.","zh":"管理；管理层"},{"word":"managerially","pos":"adv.","zh":"以管理的方式"},{"word":"manageable","pos":"adj.","zh":"可控的"}]}},{"word":"administrator","ipa_uk":"/ədˈmɪnɪstreɪtə/","ipa_us":"/ədˈmɪnɪstreɪtər/","definition_zh":"管理者；行政人员；机构事务主管；（遗产的）管理执行人；系统管理员","definition_en":"a person who organizes the daily work of an institution, a system or an estate","core_image":"一张长桌后面的人把成摞的表格分成几路，让每一路都能按时走完","scene":"医院新开的病区没有护士长，一位文员先排班、再调物资、最后对接保险结算。An administrator kept the new ward supplied while the search continued.","sceneCN":"这里 administrator 指替机构处理日常事务与资源的人（第 1 个义项：掌管机构运转的行政负责人）；句意：在招聘继续期间，一位行政主管让新病区的物资不断供。图中可辨识物件：排班表、物资清单、结算单据、病区走廊。","pos":[{"tag":"n.","zh":"管理者；行政人员；系统管理员；（遗产）管理执行人"}],"collocations":[{"phrase":"system administrator","zh":"系统管理员"},{"phrase":"database administrator","zh":"数据库管理员"},{"phrase":"hospital administrator","zh":"医院行政主管"},{"phrase":"school administrator","zh":"学校行政负责人"},{"phrase":"estate administrator","zh":"遗产管理执行人"},{"phrase":"public administrator","zh":"公共行政人员"}],"forms":[{"label":"单数","form":"administrator"},{"label":"复数","form":"administrators"},{"label":"动词","form":"administrate"},{"label":"名词（行政；管理）","form":"administration"},{"label":"形容词","form":"administrative"},{"label":"施动名词（管理行为）","form":"administering"}],"derivatives":[{"word":"administration","pos":"n.","zh":"行政；管理；政府"},{"word":"administrative","pos":"adj.","zh":"行政的"},{"word":"administer","pos":"v.","zh":"管理；施行"},{"word":"administrate","pos":"v.","zh":"管理；经办"},{"word":"administratively","pos":"adv.","zh":"在行政上"}],"senses":[{"no":"01","title":"The person who runs an institution's daily work","titleCN":"负责机构日常运转的人","definition":"a person whose job is to organize the daily work of an institution","definitionCN":"受雇负责安排一个机构日常工作的人","example":"The administrator reorganized the front desk over one weekend.","exampleCN":"那位行政主管用一个周末重整了前台。","why":"The Latin verb meant to serve toward something, so the administrator is the one who performs the service an institution needs.","whyCN":"这个拉丁动词意为「朝着某事提供服务」，因此行政主管就是为机构提供所需服务的人。"},{"no":"02","title":"A civil servant who runs a programme","titleCN":"负责公共项目的政府行政人员","definition":"a government official who manages the practical side of a public programme","definitionCN":"掌管某个公共项目实际执行事务的政府官员","example":"A regional administrator approved the road repairs.","exampleCN":"一位地区行政官员批准了道路修缮。","why":"Public service is the oldest form of that serving, and the official carries it out on the state's behalf.","whyCN":"公共服务是这种「服务」最古老的形式，官员替国家把它办出来。"},{"no":"03","title":"A computing systems manager","titleCN":"计算机系统的管理员","definition":"a person who maintains the accounts, servers and permissions of a computer system","definitionCN":"维护计算机系统的账号、服务器与权限的人","example":"Only the administrator can install new software on those machines.","exampleCN":"只有管理员才能在那批机器上安装新软件。","why":"A system also needs someone to serve it: accounts and permissions are tended like records.","whyCN":"系统同样需要有人来「伺候」：账号与权限就像档案一样需要打理。"},{"no":"04","title":"The legal manager of an estate","titleCN":"依法管理遗产的人","definition":"a person appointed by a court to manage and settle a dead person's estate","definitionCN":"由法院指定管理并清算逝者遗产的人","example":"The court named her administrator of the estate in March.","exampleCN":"法院在三月指定她为遗产管理执行人。","why":"Settling an estate is service done for the dead and their heirs, and the court appoints the one who serves.","whyCN":"清算遗产是为逝者与继承人提供的服务，法院指定的人正是提供服务者。"},{"no":"05","title":"A university or school official","titleCN":"大学或学校里的行政负责人","definition":"a senior official who handles the paperwork and rules of a school or university","definitionCN":"处理学校规章与文书事务的高级职员","example":"The university administrator extended the deadline for appeals.","exampleCN":"大学行政负责人延长了申诉的截止期限。","why":"Rules and records are the service a school needs, so its official carries that name.","whyCN":"规章与记录是学校所需要的服务，因此负责它们的职员带着这个名号。"},{"no":"06","title":"A hospital or clinic manager","titleCN":"医院或诊所的行政主管","definition":"the manager responsible for staff, supplies and records in a hospital or clinic","definitionCN":"在医院或诊所负责人员、物资与档案的管理者","example":"The clinic administrator negotiated a cheaper supply contract.","exampleCN":"诊所行政主管谈下了一份更便宜的供货合同。","why":"A ward needs supplies and rosters more than rules, and its server keeps both moving.","whyCN":"病区更需要物资与班表而不是条文，这里的服务者让两样都不停。"},{"no":"07","title":"A database controller","titleCN":"数据库管理员","definition":"a person who controls who may read or change the data in a database","definitionCN":"掌管谁可以读取或改动数据库内容的人","example":"The administrator restored the table from a night copy.","exampleCN":"管理员用夜间备份恢复了那张表。","why":"Data is a store that needs a keeper, and the keeper serves those who ask for it.","whyCN":"数据是一座需要看守的库房，看守者为前来索取的人服务。"},{"no":"08","title":"The person who keeps an office running","titleCN":"处理办公室日常事务的人","definition":"the person in an office who handles forms, files, orders and schedules","definitionCN":"在办公室里处理表单、档案、订单与日程的人","example":"The office administrator booked the hall and printed the badges.","exampleCN":"办公室行政人员订好了礼堂，也印好了胸牌。","why":"Forms and orders are the small services that keep an office alive, and their handler takes the title.","whyCN":"表单与订单是让办公室活下去的小型服务，处理它们的人就得了这个称呼。"}],"etymology":{"intro":{"en":"Administrator comes straight from Latin administrator, the agent noun of administrare 'to serve, manage', built on minister 'servant'. The word has always meant service performed on behalf of an institution.","cn":"administrator 直接来自拉丁 administrator，即 administrare「服务、经办」的施动名词，而 administrare 由 minister「仆从」构成。这个词始终指替一个机构提供的服务。"},"items":[{"era":"LATIN MINUS","en":"Minister 'servant, attendant' is generally traced to minus 'less', which pictures a servant as the lesser member of a household; the link is widely accepted but the deeper root is reconstructed.","cn":"minister「仆从、侍者」一般认为出自 minus「较少」，把仆人设想为家中地位较低者；这一联系被广泛接受，但更早的词根属重构形式。"},{"era":"LATIN MINISTRARE","en":"Ministrare meant to serve or attend, and ad- 'to, toward' added direction: administrare is service directed at a task.","cn":"ministrare 意为服侍、照料，前缀 ad-「向」补上方向：administrare 就是朝着某项任务提供的服务。"},{"era":"LATIN ADMINISTRATOR","en":"Administrator was the Latin agent noun for the one who performs that service, and English borrowed it directly rather than through French.","cn":"administrator 是拉丁语中表示「提供这项服务者」的施动名词，英语是直接借入，而非经法语转手。"},{"era":"FIFTEENTH CENTURY","en":"The word appears in English in the fifteenth century, at first for someone entrusted with managing affairs or property for another; the first date is approximate.","cn":"这个词在十五世纪出现于英语，最初指受托替他人管理事务或产业的人；最早年代为约数。"},{"era":"MODERN SPECIALISMS","en":"Hospital, school, database and estate administration each hardened into a separate job title in the nineteenth and twentieth centuries.","cn":"医院、学校、数据库与遗产管理在十九、二十世纪各自凝固为独立的职位名称。"}]},"similar":{"note":{"en":"The first group shares the administer root; the second group names other people who keep work moving.","cn":"第一组共享 administer 词根；第二组是其他维持工作运转的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"administer","ipa":"/ədˈmɪnɪstə/","tag":"same root","definition":"The verb, meaning to manage or to give out something such as aid or a drug.","definitionCN":"动词，意为管理，或发放援助、药物等物。"},{"word":"administration","ipa":"/ədˌmɪnɪˈstreɪʃn/","tag":"same root","definition":"The activity or the government body, not the individual officer.","definitionCN":"指这项活动或政府机构，不是单个官员。"},{"word":"administrative","ipa":"/ədˈmɪnɪstrətɪv/","tag":"same root","definition":"The adjective describing procedure and paperwork.","definitionCN":"形容词，描述程序与文书工作。"},{"word":"minister","ipa":"/ˈmɪnɪstə/","tag":"same root","definition":"The Latin servant behind the whole family; in modern English it usually means a clergy member or a senior politician.","definitionCN":"整个词族的拉丁语「仆从」源头；现代英语中通常指神职人员或高级部长。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manager","ipa":"/ˈmænɪdʒə/","tag":"near meaning","definition":"Focuses on running the work and its results; the administrator focuses on procedure and records.","definitionCN":"侧重经营工作及其成果；行政主管侧重程序与记录。"},{"word":"official","ipa":"/əˈfɪʃl/","tag":"near meaning","definition":"A person holding a public office; the word says nothing about daily paperwork.","definitionCN":"担任公职的人，并不含日常文书之意。"},{"word":"executive","ipa":"/ɪɡˈzekjətɪv/","tag":"near meaning","definition":"A senior figure with power to decide, above the administrative staff.","definitionCN":"握有决策权的更高层人物，位于行政人员之上。"},{"word":"registry clerk","ipa":"/ˈredʒɪstri klɑːk/","tag":"near meaning","definition":"A clerical post that keeps records, a narrower job than an administrator.","definitionCN":"保管记录的文书职位，比行政主管窄。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin pieces and the real job titles.","cn":"正常联想使用真实的拉丁构件与真实的职位名称。"},"normal":[{"en":"The Latin pieces are ad- 'to' and ministrare 'to serve', so an administrator serves toward a task.","cn":"拉丁构件是表示「向」的前缀与 ministrare「服务」，行政人员是朝着某项任务提供服务的人。"},{"en":"The family runs administer, administration, administrative and administrator.","cn":"同族词有 administer、administration、administrative 与 administratively。"},{"en":"Titles show the split: system administrator, hospital administrator, estate administrator.","cn":"职位名称显示它的分化：系统管理员、医院行政主管、遗产管理执行人。"},{"en":"Minister is the servant inside the word, which is why service, not command, is its core.","cn":"minister 是藏在词里的「仆从」，因此它的核心是服务而非命令。"},{"en":"An administrator is judged by whether the paperwork and supplies arrive on time.","cn":"衡量行政主管的，是文书与物资能否按时到位。"}],"abstract":[{"en":"Picture a hand dividing one tall stack of forms into four short stacks, each labelled.","cn":"想象一只手把高高一摞表格分成四小摞，每摞都贴上标签。"},{"en":"Picture a servant who walks the length of a corridor with keys and a list.","cn":"想象一位仆人拿着钥匙和清单，走完整条走廊。"},{"en":"Picture a switchboard where every line is answered in the order it rang.","cn":"想象一台交换机，每条线都按响铃的先后被接通。"}]},"examples":[{"en":"The administrator moved the meeting so the night shift could attend.","cn":"行政主管改了会议时间，让夜班的人也能参加。"},{"en":"Every new account is opened by the system administrator.","cn":"每个新账号都由系统管理员开立。"},{"en":"As administrator of the estate, he had to sell the house before paying the debts.","cn":"作为遗产管理执行人，他必须先卖掉房子再清偿债务。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「admin（管理）+ istrator（人）」——做管理那件事的人，就是行政主管","word":"administrator"},"root":"拉丁 ad-「向」+ minister「仆从、侍者」→ administrare「为……办事、经办」→ administrator「经办事务的人」；minister 一般认为出自 minus「较少」，即居于下位者。","sensesIntro":{"en":"Eight senses all keep the idea of service: the institution's daily work, the public programme, the computer system, the dead person's estate, the school, the hospital, the database and the office desk.","cn":"八个义项都保留「服务」这层意思：机构的日常事务、公共项目、计算机系统、逝者的遗产、学校、医院、数据库与办公室那张桌子。"},"semanticMap":{"core":{"en":"CORE IMAGE: a servant with a list walks a corridor and keeps every door supplied.","cn":"核心意象：一位拿着清单的仆从走过走廊，让每扇门后都不缺东西。"},"chain":["SERVANT OF THE HOUSE","INSTITUTION'S DAILY WORK","PUBLIC PROGRAMME","COMPUTER SYSTEM","ESTATE OF THE DEAD","PAPER AND RECORDS"],"branches":[{"senses":"01","en":"THE HOUSE: daily service inside one institution is the plainest form.","cn":"宅内：在一个机构里做日常服务，是最朴素的形式。"},{"senses":"02","en":"THE STATE: the same service is performed for a public programme.","cn":"国家：同样的服务转为替公共项目执行。"},{"senses":"03 · 07","en":"THE MACHINE AND ITS DATA: accounts, servers and tables all need a keeper.","cn":"机器与数据：账号、服务器与数据表都需要看守者。"},{"senses":"04","en":"THE ESTATE: service continues after the owner has died, now for heirs and creditors.","cn":"遗产：主人去世后服务仍在继续，只是对象换成继承人与债主。"},{"senses":"05 · 06 · 08","en":"PAPER, WARDS AND OFFICES: rules, supplies and forms are three faces of the same desk.","cn":"文书、病区与办公室：规章、物资与表单是同一张桌子的三面。"}]},"affixes":{"intro":{"en":"Administrator is a Latin agent noun built on a servant root, and that root also builds a small English family.","cn":"administrator 是建立在「仆从」词根上的拉丁施动名词，这个词根还构成一个小型英语词族。"},"latinIntro":{"en":"Latin minister gives minister, ministry and administer; administrare gives administration and administrative.","cn":"拉丁 minister 衍生 minister、ministry 与 administer；administrare 衍生 administration 与 administrative。"},"items":[{"word":"ad-","structure":"Latin prefix","meaning":"to, toward","meaningCN":"向；朝着","example":"The prefix points the service at a task.","exampleCN":"前缀把服务指向一项任务。"},{"word":"minister","structure":"Latin noun, third declension","meaning":"servant, attendant","meaningCN":"仆从；侍者","example":"The servant is the core of the whole family.","exampleCN":"仆从是整个词族的核心。"},{"word":"ministrare","structure":"Latin verb, first conjugation","meaning":"to serve, attend, manage","meaningCN":"服侍；照料；经办","example":"Serving and managing were one act in Latin.","exampleCN":"在拉丁语里，服侍与经办是同一个动作。"},{"word":"administrare","structure":"ad- plus ministrare","meaning":"to carry out service for a task","meaningCN":"为某项事务提供服务","example":"The compound adds direction to service.","exampleCN":"复合词给服务加上方向。"},{"word":"administrator","structure":"administrare plus -tor (agent)","meaning":"one who performs the service","meaningCN":"提供这项服务的人","example":"The agent ending names the servant, not the served.","exampleCN":"施动词尾点出仆人，而不是被服务者。"},{"word":"administration","structure":"administrare plus -tio (action)","meaning":"the activity of administering","meaningCN":"行政；管理","example":"The action noun names the work itself.","exampleCN":"动作名词指这项工作本身。"},{"word":"administrative","structure":"administration plus -ive (tending to)","meaning":"of administration","meaningCN":"行政的","example":"The adjective marks what belongs to procedure.","exampleCN":"形容词标出属于程序的东西。"},{"word":"administer","structure":"administrare through French","meaning":"to manage or give out","meaningCN":"管理；发放","example":"The verb is the family's working member.","exampleCN":"动词是词族里干活的那一个。"},{"word":"-tor","structure":"Latin agent suffix","meaning":"one who does","meaningCN":"表示执行者的后缀","example":"It also builds doctor, actor and creator.","exampleCN":"它也构成「医生」「演员」与「创造者」等词。"}],"latinEntries":[{"word":"minister","structure":"minister, ministri (n., second declension)","meaning":"servant, attendant","meaningCN":"仆从；侍者"},{"word":"ministrare","structure":"ministrare, ministravi, ministratum (verb, first conjugation)","meaning":"to serve, attend","meaningCN":"服侍；照料"},{"word":"administratio","structure":"administratio, administrationis (n., third declension)","meaning":"management, administration","meaningCN":"管理；经办"}],"derivatives":[{"word":"administration","pos":"n.","zh":"行政；政府"},{"word":"administrative","pos":"adj.","zh":"行政的"},{"word":"administer","pos":"v.","zh":"管理；发放"},{"word":"administratively","pos":"adv.","zh":"在行政上"}]}},{"word":"executive","ipa_uk":"/ɪɡˈzekjətɪv/","ipa_us":"/ɪɡˈzekjətɪv/","definition_zh":"主管；高层管理者；（政府的）行政部门；执行委员会；决策层的","definition_en":"a senior manager or official with power to carry out decisions, or the branch that puts laws into effect","core_image":"一个人接过写好的命令，直接把命令变成行动，身后是整条执行链","scene":"董事会定下方案后，真正去开门店、签租约、招人的是那几位高层。The executive signed the lease the board had approved.","sceneCN":"这里 executive 指握有执行权的高层负责人（第 1 个义项：能直接把决定落地的管理者）；句意：那位高管签下了董事会已批准的租约。图中可辨识物件：租赁合同、董事会决议、签字笔、门店钥匙。","pos":[{"tag":"n.","zh":"主管；高层管理者；行政部门；执行委员会"},{"tag":"adj.","zh":"决策层的；执行的；行政的"}],"collocations":[{"phrase":"chief executive","zh":"首席执行官"},{"phrase":"executive board","zh":"执行董事会"},{"phrase":"executive committee","zh":"执行委员会"},{"phrase":"executive director","zh":"执行董事"},{"phrase":"executive branch","zh":"行政部门"},{"phrase":"executive summary","zh":"内容提要"}],"forms":[{"label":"单数（名词）","form":"executive"},{"label":"复数（名词）","form":"executives"},{"label":"作定语（同形）","form":"executive committee"},{"label":"动词","form":"execute"},{"label":"名词（执行）","form":"execution"},{"label":"名词（遗嘱执行人）","form":"executor"}],"derivatives":[{"word":"execute","pos":"v.","zh":"执行；实施"},{"word":"execution","pos":"n.","zh":"执行；实施"},{"word":"executor","pos":"n.","zh":"遗嘱执行人"},{"word":"executrix","pos":"n.","zh":"女遗嘱执行人（法律旧称）"},{"word":"executively","pos":"adv.","zh":"在以执行权的方式下（罕用）"}],"senses":[{"no":"01","title":"A senior manager with power to act","titleCN":"有实权的高层管理者","definition":"a senior manager who has the authority to put decisions into practice","definitionCN":"拥有把决定付诸实施之权的高层管理者","example":"The executive approved the new plant before the board met.","exampleCN":"那位高层在董事会开会前就批准了新厂。","why":"Executive comes from a Latin verb meaning to follow something through to the end, so the title belongs to the one who finishes what others decide.","whyCN":"executive 出自一个意为「一路跟到底」的拉丁动词，因此这个称号属于把别人决定的事做完的人。"},{"no":"02","title":"A senior government official","titleCN":"政府高层官员","definition":"a high-ranking official in a government department or agency","definitionCN":"在政府部门或机构中身居高位的官员","example":"A senior executive from the ministry opened the talks.","exampleCN":"部里的一位高级官员开启了会谈。","why":"A ministry also needs someone to follow its policies through, and that officer carries the name.","whyCN":"部门同样需要有人把政策贯彻到底，这位官员便带着这个名号。"},{"no":"03","title":"The branch that carries out laws","titleCN":"执行法律的那一支政府机构","definition":"the part of government that puts laws into effect, as opposed to the legislature","definitionCN":"政府中负责让法律生效的部分，与立法机关相对","example":"The courts check that the executive stays within the law.","exampleCN":"法院核查行政部门是否守在法律之内。","why":"The branch that follows laws through to their effect is named by the same action.","whyCN":"把法律一路落实到效果的那一支，就是用同一个动作命名的。"},{"no":"04","title":"Of top management","titleCN":"属于最高管理层的","definition":"relating to the most senior level of management","definitionCN":"与最高层管理有关的","example":"Executive pay rose faster than average wages.","exampleCN":"高管的薪酬比平均工资涨得快。","why":"As an adjective it marks the level where decisions are actually carried out.","whyCN":"作形容词时，它标出决定真正被落实的那一层。"},{"no":"05","title":"Of law enforcement and administration","titleCN":"属于执法与行政的","definition":"relating to the carrying out of laws and public administration","definitionCN":"与法律的执行及公共行政有关的","example":"Executive powers were widened during the emergency.","exampleCN":"紧急状态期间，行政权力被扩大。","why":"Powers that carry laws into effect are executive powers by definition.","whyCN":"把法律带入实效的权力，按定义就是行政权。"},{"no":"06","title":"The body that decides and acts","titleCN":"决策并执行的委员会","definition":"a committee or council within an organization that holds decision-making power","definitionCN":"组织内部握有决策权的委员会或理事会","example":"The executive met on Friday and voted to proceed.","exampleCN":"执行委员会在周五开会，表决通过继续推进。","why":"A body that follows decisions through to action is named for the doing, not the debating.","whyCN":"把决定跟到行动为止的机构，是以「做」而非「辩」来命名的。"},{"no":"07","title":"One who carries out an order","titleCN":"把命令付诸实施的人","definition":"a person whose role is to carry out a plan or an order","definitionCN":"职责是把计划或命令执行到底的人","example":"He was the executive of the plan, not its author.","exampleCN":"他是这项计划的执行者，而不是起草者。","why":"The plainest sense is the oldest: the person who executes, that is, carries out, an order.","whyCN":"最朴素的一义也最古老：执行者，也就是把命令办到底的人。"},{"no":"08","title":"A client-serving role in an agency","titleCN":"代理机构里对接客户的职位","definition":"a job title for the person who manages a client's account in an agency","definitionCN":"代理机构中负责管理客户业务的人所用职位名","example":"The account executive flew to the client's office in Osaka.","exampleCN":"客户执行飞到大阪的客户办公室。","why":"An agency's account handler follows a client's work through to completion, so the title fits.","whyCN":"代理机构的客户对接人把客户的事跟到完成为止，这个称号正好合适。"}],"etymology":{"intro":{"en":"Executive comes from Latin exsequi 'to follow out, carry out', built on sequi 'to follow'. The noun first meant the person who executes an order; the corporate and governmental senses are later widenings.","cn":"executive 出自拉丁 exsequi「一路跟出、执行」，由 sequi「跟随」构成。名词最初指把命令执行到底的人；企业义与政府义都是后来的扩展。"},"items":[{"era":"LATIN SEQUI","en":"Sequi meant 'to follow'. Its Indo-European ancestry is reconstructed, but the Latin verb itself is well recorded.","cn":"sequi 意为「跟随」。它的印欧语来源属重构形式，但这个拉丁动词本身记录充分。"},{"era":"LATIN EXSEQUI","en":"Ex- 'out' plus sequi gave exsequi, 'to follow through to the end, to carry out', especially of a duty or an order.","cn":"表示「出」的拉丁前缀加 sequi 构成 exsequi，意为「一路跟到底、执行」，尤指职责或命令。"},{"era":"LATIN EXSECUTUS","en":"Its past participle exsecutus supplied the stem execut-, from which the English adjective and noun were formed.","cn":"它的过去分词 exsecutus 提供了 execut- 这个词干，英语的形容词与名词即由此构成。"},{"era":"FIFTEENTH CENTURY","en":"The word entered English in the fifteenth century through French exécutif, first as an adjective meaning 'carrying into effect'.","cn":"这个词在十五世纪经法语 exécutif 进入英语，最初是形容词，意为「使……生效的」。"},{"era":"GOVERNMENT AND BUSINESS","en":"The sense of a branch of government is seventeenth-century; the sense of a senior salaried manager is nineteenth- and twentieth-century. Both first dates are approximate.","cn":"「政府的一支」这一义属十七世纪；「受薪高层管理者」这一义属十九、二十世纪。两个最早年代都是约数。"}]},"similar":{"note":{"en":"The first group shares the sequi root; the second group names people and posts of comparable rank.","cn":"第一组共享 sequi 词根；第二组是级别相近的人与职位。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"execute","ipa":"/ˈeksɪkjuːt/","tag":"same root","definition":"The verb meaning to carry out a plan, order or law.","definitionCN":"动词，意为把计划、命令或法律执行到底。"},{"word":"execution","ipa":"/ˌeksɪˈkjuːʃn/","tag":"same root","definition":"The act of carrying something out, or the carrying out of a death sentence.","definitionCN":"执行某事的行为，或执行死刑。"},{"word":"executor","ipa":"/ɪɡˈzekjətə/","tag":"same root","definition":"The person legally appointed to carry out the terms of a will.","definitionCN":"依法被指定执行遗嘱条款的人。"},{"word":"sequence","ipa":"/ˈsiːkwəns/","tag":"same root, different sense","definition":"From the same Latin verb for following, but it names an order of things, not a person who acts.","definitionCN":"同出那个表示跟随的拉丁动词，但指事物的先后次序，不是行动的人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manager","ipa":"/ˈmænɪdʒə/","tag":"near meaning","definition":"Runs a unit day to day; an executive sits higher and decides more.","definitionCN":"日常经营一个单元；高管位置更高，决定更多。"},{"word":"administrator","ipa":"/ədˈmɪnɪstreɪtə/","tag":"near meaning","definition":"Keeps procedures and records in order, usually below executive rank.","definitionCN":"维持程序与记录，通常在高层之下。"},{"word":"director","ipa":"/dəˈrektə/","tag":"near meaning","definition":"A board member or the head of a whole organization; the title stresses guiding.","definitionCN":"董事会成员或整个机构的负责人，称号强调引导。"},{"word":"officer","ipa":"/ˈɒfɪsə/","tag":"near meaning","definition":"A holder of office in a company or an armed force; the word stresses appointment.","definitionCN":"公司或军队中任职的人，强调受任。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin verb, the real family and real titles.","cn":"正常联想使用真实的拉丁动词、真实的词族与真实的职位名称。"},"normal":[{"en":"Sequi is to follow, and exsequi is to follow a matter out to its end.","cn":"sequi 是跟随，exsequi 是把一件事跟到尽头。"},{"en":"The family runs execute, execution, executor and executive.","cn":"同族词有 execute、execution、executor 与 executioner。"},{"en":"Titles show the reach: chief executive, executive director, account executive.","cn":"职位显示它的范围：首席执行官、执行董事、客户执行。"},{"en":"The executive branch is the part of government that follows laws into effect.","cn":"行政部门就是把法律跟进到生效的那一部分政府。"},{"en":"An executive is the one who ends a discussion by acting on it.","cn":"高管就是用一个行动给讨论收尾的人。"}],"abstract":[{"en":"Picture a hand receiving a sealed order and breaking the seal at once.","cn":"想象一只手接过封好的命令，当场拆封。"},{"en":"Picture a relay runner who takes the baton and never looks back.","cn":"想象接力跑者接过接力棒，从不回头。"},{"en":"Picture a door that opens the moment the decision is spoken.","cn":"想象决定一说出口，门就打开。"}]},"examples":[{"en":"The chief executive spent the morning on the factory floor.","cn":"首席执行官在车间里待了一上午。"},{"en":"Executive sessions are closed to junior staff.","cn":"高管会议对下级员工不开放。"},{"en":"The executive branch cannot make the budget alone.","cn":"行政部门无法独自决定预算。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「execu（执行）+ tive（的）」——负责把决定执行下去的那一层，就是高管","word":"executive"},"root":"拉丁语表示「出」的前缀 + sequi「跟随」→ exsequi「跟到底、执行」→ 过去分词 exsecutus → 法语 exécutif → 英语 executive；同根词有 execute、execution、sequence。","sensesIntro":{"en":"Eight senses follow one act of carrying something through: a corporate decision, a ministry's policy, a whole branch of government, the adjective for that level, its legal powers, a committee, a single order and an agency account.","cn":"八个义项围绕同一个「把事办到底」的动作：公司的决定、部里的政策、政府的一整支、指该层级的形容词、其法定权力、一个委员会、一道命令、一家代理机构的客户业务。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed order is opened and turned into action within the same hour.","cn":"核心意象：一道封好的命令被拆开，并在同一个时辰里变成行动。"},"chain":["FOLLOW THROUGH","CARRY OUT AN ORDER","SENIOR MANAGER","THE ACTING BODY","GOVERNMENT BRANCH","CLIENT HANDLER"],"branches":[{"senses":"01 · 04","en":"THE LEVEL: a senior manager, and the adjective that marks that level.","cn":"层级：一位高层管理者，以及标出这一层级的形容词。"},{"senses":"02 · 03 · 05","en":"THE STATE: an official, the branch, and the powers that make law effective.","cn":"国家：一位官员、那一支机构，以及让法律生效的权力。"},{"senses":"06","en":"THE BODY: a committee that ends debate by deciding and acting.","cn":"机构：以决定和行动结束辩论的委员会。"},{"senses":"07","en":"THE LITERAL DOER: the oldest sense, one who executes an order.","cn":"字面的执行者：最古老的一义，把命令办到底的人。"},{"senses":"08","en":"THE AGENCY: a client's work followed through to completion.","cn":"代理机构：把客户的事跟到完成为止。"}]},"affixes":{"intro":{"en":"Executive is a Latin participle turned English noun and adjective, and the same verb gives a small family of words about carrying things out.","cn":"executive 是由拉丁分词转成的英语名词与形容词，同一个动词还给出了一小组表示「执行」的词。"},"latinIntro":{"en":"Latin sequi gives sequence and consequent; exsequi gives execute, execution and executor.","cn":"拉丁 sequi 衍生 sequence 与 consequent；exsequi 衍生 execute、execution 与 executor。"},"items":[{"word":"sequi","structure":"Latin verb, third conjugation","meaning":"to follow","meaningCN":"跟随","example":"The root supplies the idea of going along to the end.","exampleCN":"这个词根提供「一路跟到底」的意思。"},{"word":"ex-","structure":"Latin prefix","meaning":"out, through","meaningCN":"出；贯穿","example":"The prefix turns following into finishing.","exampleCN":"前缀把跟随变成做完。"},{"word":"exsequi","structure":"ex- plus sequi","meaning":"to follow out, carry out","meaningCN":"贯彻；执行","example":"The compound is the source of the whole family.","exampleCN":"这个复合词是整个词族的源头。"},{"word":"executive","structure":"exsecutus plus -ive","meaning":"of carrying out; a senior manager","meaningCN":"执行的；高层主管","example":"The adjective became a noun for the person who acts.","exampleCN":"形容词转为指行动者的名词。"},{"word":"execute","structure":"exsecutus plus -ate (verb)","meaning":"to carry out","meaningCN":"执行；实施","example":"The verb keeps the plain action.","exampleCN":"动词保留最直白的动作。"},{"word":"execution","structure":"execute plus -ion (action)","meaning":"the carrying out","meaningCN":"执行；实施","example":"The noun names the deed, not the doer.","exampleCN":"名词指行为，不指人。"},{"word":"executor","structure":"execute plus -or (agent)","meaning":"one who carries out a will","meaningCN":"遗嘱执行人","example":"The agent noun narrowed to a legal role.","exampleCN":"施动名词收窄为法律角色。"},{"word":"executive branch","structure":"executive plus branch","meaning":"the part of government that acts","meaningCN":"行政部门","example":"The phrase fixes the governmental sense.","exampleCN":"这个短语固定了政府义。"}],"latinEntries":[{"word":"sequi","structure":"sequi, secutus sum (verb, third conjugation)","meaning":"to follow","meaningCN":"跟随"},{"word":"exsequi","structure":"exsequi, exsecutus sum (verb, third conjugation)","meaning":"to follow out, execute","meaningCN":"贯彻；执行"},{"word":"exsecutio","structure":"exsecutio, exsecutionis (n., third declension)","meaning":"a carrying out","meaningCN":"执行；实施"}],"derivatives":[{"word":"execute","pos":"v.","zh":"执行；实施"},{"word":"execution","pos":"n.","zh":"执行"},{"word":"executor","pos":"n.","zh":"遗嘱执行人"},{"word":"executrix","pos":"n.","zh":"女遗嘱执行人"}]}},{"word":"executive management","ipa_uk":"/ɪɡˈzekjətɪv ˈmænɪdʒmənt/","ipa_us":"/ɪɡˈzekjətɪv ˈmænɪdʒmənt/","definition_zh":"高层管理；执行管理层；企业的最高管理团队及其职能","definition_en":"the most senior group of managers in an organization, or the work they do","core_image":"一张长桌的最上首坐着几个人，桌下所有线缆都汇到他们面前","scene":"分公司各自为政，价格战打到亏本，最后总部把定价权、采购权和人事权都收到一张桌上。Executive management sets the rules the branches must follow.","sceneCN":"这里 executive management 指掌握最终决策权的那一层管理者（第 1 个义项：企业最高管理团队）；句意：高层管理层定下各分公司必须遵守的规则。图中可辨识物件：长桌、定价表、采购合同、人事档案。","pos":[{"tag":"n.","zh":"高层管理；执行管理层；最高管理团队"}],"collocations":[{"phrase":"executive management team","zh":"高层管理团队"},{"phrase":"senior executive management","zh":"高级执行管理层"},{"phrase":"executive management committee","zh":"高层管理委员会"},{"phrase":"executive management level","zh":"高层管理级别"},{"phrase":"executive management programme","zh":"高层管理培训项目"}],"forms":[{"label":"单数","form":"executive management"},{"label":"复数（指多家机构的高层）","form":"executive managements"},{"label":"作定语（形式不变）","form":"executive management team"},{"label":"相关形容词","form":"executive"},{"label":"相关名词（管理）","form":"management"},{"label":"相关名词（经理）","form":"manager"}],"derivatives":[{"word":"executive","pos":"n./adj.","zh":"高层管理者；执行的"},{"word":"management","pos":"n.","zh":"管理；管理层"},{"word":"manager","pos":"n.","zh":"经理"},{"word":"managerial","pos":"adj.","zh":"管理的"},{"word":"manage","pos":"v.","zh":"管理；经营"}],"senses":[{"no":"01","title":"The top group of managers","titleCN":"企业最高管理团队","definition":"the small group of most senior managers who hold final authority in an organization","definitionCN":"在一个组织里握有最终权力的少数最高层管理者","example":"Executive management approved the sale of the shipping division.","exampleCN":"高层管理层批准了出售航运部门。","why":"Executive names the level that carries decisions through, and management names the hand that runs the work; together they fix the top of the ladder.","whyCN":"executive 标出把决定落实到底的那一层，management 标出经营工作的那只手；两词合起来就钉住了梯子的顶端。"},{"no":"02","title":"The work done at the top","titleCN":"在最高层所做的那项工作","definition":"the activity of directing a whole organization rather than one part of it","definitionCN":"指挥整个组织而不是其中某一部分的活动","example":"Executive management takes most of her week, leaving little time for research.","exampleCN":"高层管理占去她一周的大部分时间，留给研究的时间很少。","why":"The same phrase can name the activity as well as the people, because the two words are a doing-word and a body-word.","whyCN":"这个短语既能指人也能指这项工作，因为前一个词偏动作，后一个词偏群体。"},{"no":"03","title":"A structural tier","titleCN":"组织结构中的最高层级","definition":"the top level of the management hierarchy, above middle managers","definitionCN":"管理层级中位于中层经理之上的最高一层","example":"Only staff at the executive management level see the full forecast.","exampleCN":"只有高层管理级别的人才能看到完整预测。","why":"A ladder needs a top rung with a name, and this phrase supplies it.","whyCN":"梯子需要给最上一级起个名字，这个短语就提供了这个名字。"},{"no":"04","title":"The formal committee","titleCN":"由高层组成的正式决策会议体","definition":"the committee in which the senior managers meet and decide together","definitionCN":"最高层管理者聚在一起作决定的委员会","example":"The executive management meets on the first Tuesday of each month.","exampleCN":"高层管理委员会每月第一个周二开会。","why":"When the top group meets on a fixed day, the phrase stops meaning a level and starts meaning a room.","whyCN":"当最高层固定在某个日子开会，这个短语就从「一层人」变成「一间会议室」。"},{"no":"05","title":"A field of study or training","titleCN":"作为研究或培训领域的高层管理","definition":"the study or teaching of how the most senior level should be run","definitionCN":"研究或教授最高层应如何运作的领域","example":"The school runs a short course in executive management for hospital chiefs.","exampleCN":"这所学校为医院负责人开设了短期高层管理课程。","why":"Practice that is written into a syllabus becomes a field, and the phrase carries that name into the classroom.","whyCN":"做法一旦写进教学大纲就成了领域，这个短语便带着名字进了课堂。"},{"no":"06","title":"Leadership of an institution","titleCN":"对一个机构整体的领导","definition":"the leadership of a public institution such as a hospital or a university","definitionCN":"对医院、大学等公共机构的整体领导","example":"Executive management at the hospital had to choose between two wards.","exampleCN":"医院的高层管理不得不在两个病区之间取舍。","why":"Public institutions use the corporate phrase because they face the same choice: which parts get resources.","whyCN":"公共机构沿用这个企业说法，因为它们面对同样的取舍：哪些部分得到资源。"},{"no":"07","title":"The top layer of a subsidiary","titleCN":"子公司或事业部自己的最高层","definition":"the senior managers of a division or subsidiary, who answer to group headquarters","definitionCN":"事业部或子公司中向集团总部汇报的高层管理者","example":"The subsidiary's executive management reports to the group every quarter.","exampleCN":"子公司的高层管理每季度向集团汇报一次。","why":"A large group repeats the same top rung one floor down, so the phrase multiplies.","whyCN":"大集团会在下一层再复制一个同样的顶端，这个短语因此可以叠加。"},{"no":"08","title":"The team that carries out board strategy","titleCN":"负责把董事会战略落地的团队","definition":"the group accountable for turning the board's strategy into actual operations","definitionCN":"负责把董事会战略变成实际运营的那一组人","example":"Executive management turned the five-year plan into twelve quarterly targets.","exampleCN":"高层管理把五年规划拆成十二个季度目标。","why":"The word executive means carrying through, so the phrase names the group that must make a plan real.","whyCN":"executive 的意思是把事办到底，因此这个短语指必须让计划成真的那一组人。"}],"etymology":{"intro":{"en":"The phrase joins two Latin-rooted words: executive, from exsequi 'to carry out', and management, from manus 'hand'. It became a fixed corporate phrase in the twentieth century.","cn":"这个短语把两个拉丁词根的词接在一起：executive 出自 exsequi「执行」，management 出自 manus「手」。它在二十世纪成为固定的企业说法。"},"items":[{"era":"LATIN SEQUI","en":"Executive rests on sequi 'to follow', so its half of the phrase means following a decision through to action.","cn":"executive 建立在 sequi「跟随」之上，因此短语的这一半意为把决定跟进到行动。"},{"era":"LATIN MANUS","en":"Management rests on manus 'hand', so its half means the hand that runs and rations the work.","cn":"management 建立在 manus「手」之上，因此这一半指经营并分配工作的那只手。"},{"era":"ENGLISH EXECUTIVE","en":"Executive entered English in the fifteenth century as an adjective meaning 'carrying into effect', and only later named a senior manager.","cn":"executive 在十五世纪作为形容词进入英语，意为「使……生效的」，后来才用来指高层管理者。"},{"era":"ENGLISH MANAGEMENT","en":"Management entered English in the sixteenth century for the handling of a household, a horse or a business, and later named the body of managers.","cn":"management 在十六世纪进入英语，指料理家务、驾驭马匹或经营生意，后来才指管理层这一群体。"},{"era":"FIXED PHRASE","en":"The two words were joined into a fixed phrase in the twentieth century, when large firms separated owners, boards and salaried top managers.","cn":"两个词在二十世纪合成固定短语，当时大企业把所有者、董事会与受薪高层分开。"},{"era":"APPROXIMATE FIRST DATES","en":"The earliest recorded use of the full phrase is not well dated; the century is reliable, the exact year is approximate.","cn":"完整短语最早见于何时缺乏确切记录；所属世纪可靠，具体年份为约数。"}]},"similar":{"note":{"en":"The first group shares one or both words of the phrase; the second group names bodies that sit at or near the top.","cn":"第一组共享短语中的一个或两个词；第二组是位于顶端或紧邻顶端的机构与群体。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"management","ipa":"/məˈneɪdʒmənt/","tag":"shares the second word","definition":"Management alone covers every level, from team leader to board.","definitionCN":"单说 management 涵盖从组长到董事会的所有层级。"},{"word":"executive","ipa":"/ɪɡˈzekjətɪv/","tag":"shares the first word","definition":"Executive alone means one senior manager or the whole branch of government.","definitionCN":"单说 executive 指一位高层，或整个政府的行政分支。"},{"word":"managerial","ipa":"/ˌmænɪˈdʒɪəriəl/","tag":"related root","definition":"The adjective for anything done by managers, at any level.","definitionCN":"指任何层级管理者所做之事的形容词。"},{"word":"executive director","ipa":"/ɪɡˈzekjətɪv dəˈrektə/","tag":"near shape, one post","definition":"A single board member with paid duties, not the whole top team.","definitionCN":"指一位受薪履职的董事，不是整个高层团队。"}]},{"heading":"NEAR MEANING","entries":[{"word":"senior management","ipa":"/ˈsiːniə ˈmænɪdʒmənt/","tag":"near meaning","definition":"Almost the same group, but senior can include levels just below the very top.","definitionCN":"几乎是同一群人，但「高级」这一限定可以包括紧挨顶端之下的一层。"},{"word":"top management","ipa":"/tɒp ˈmænɪdʒmənt/","tag":"near meaning","definition":"A plainer synonym for the highest layer, without the carrying-out emphasis.","definitionCN":"最高层的更朴素说法，不含「把事办到底」的强调。"},{"word":"board of directors","ipa":"/bɔːd əv dəˈrektəz/","tag":"near meaning","definition":"The body that appoints and checks the top managers rather than managing daily work.","definitionCN":"负责任命与监督高层、而不做日常经营的机构。"},{"word":"leadership team","ipa":"/ˈliːdəʃɪp tiːm/","tag":"near meaning","definition":"A looser phrase for those who set direction, used in any kind of organization.","definitionCN":"更松散的说法，指定方向的人，任何组织都可用。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real roots and the real corporate phrase.","cn":"正常联想使用两个真实词根与真实的企业说法。"},"normal":[{"en":"Executive is about carrying decisions through, management is about the hand on the work.","cn":"executive 讲把决定办到底，management 讲按在工作上的那只手。"},{"en":"The phrase sits at the top rung, above senior and middle management.","cn":"这个短语位于梯子顶端，在高级管理层与中层管理之上。"},{"en":"Real phrases mark it: executive management team, executive management committee.","cn":"真实说法标出它的用法：高层管理团队、高层管理委员会。"},{"en":"A group can repeat the phrase one floor down for each subsidiary.","cn":"集团可以为每家子公司往下再复制一层同样的说法。"},{"en":"Board sets strategy; executive management turns it into operations.","cn":"董事会定战略；高层管理把它变成运营。"}],"abstract":[{"en":"Picture a table where every cable in the building ends in one row of sockets.","cn":"想象一张桌子，整栋楼的线缆都终止在一排插座前。"},{"en":"Picture a hand that signs nothing itself but decides whose signature counts.","cn":"想象一只手不亲自签任何字，却决定谁签的字算数。"},{"en":"Picture a weather map where one isobar covers the whole country.","cn":"想象一张天气图，一条等压线罩住整个国家。"}]},"examples":[{"en":"Executive management rejected the merger after two months of talks.","cn":"高层管理在两个月谈判后否决了这次合并。"},{"en":"The executive management team meets every second Monday.","cn":"高层管理团队每两周的周一开一次会。"},{"en":"Costs at the executive management level are the first to be cut.","cn":"高层管理这一层的开支总是最先被削减。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「executive（执行层）+ management（管理）」——握住执行权的那一层管理者，就是高层管理","word":"executive management"},"root":"executive 出自拉丁 exsequi「执行」（ex- + sequi「跟随」）；management 出自拉丁 manus「手」加名词后缀 -ment；两词在二十世纪合成固定短语。","sensesIntro":{"en":"Eight senses keep the phrase at the top of a ladder: the group, its work, the tier, the meeting committee, the trained field, public leadership, a subsidiary's own top, and the team that makes board strategy real.","cn":"八个义项都把这个短语放在梯子顶端：那群人、他们做的活、那一层级、开会的那张桌、被教授的领域、公共机构的领导、子公司自己的顶端，以及让董事会战略成真的团队。"},"semanticMap":{"core":{"en":"CORE IMAGE: every cable in a large building ends at one row of sockets.","cn":"核心意象：一栋大楼里所有线缆都汇到一排插座前。"},"chain":["TOP OF THE LADDER","THE FINAL AUTHORITY","THE DAILY WORK","THE MEETING TABLE","THE SUBSIDIARY TOP","STRATEGY MADE REAL"],"branches":[{"senses":"01 · 02","en":"THE GROUP AND ITS WORK: the people, and the directing they do all week.","cn":"人与活：那群人，以及他们整周在做的指挥。"},{"senses":"03 · 07","en":"TWO HEIGHTS: the corporate tier, and the same tier repeated inside a subsidiary.","cn":"两个高度：集团的最高层，以及子公司内部复制出的同一层。"},{"senses":"04 · 05","en":"THE TABLE AND THE CLASSROOM: a fixed meeting day, and a syllabus that teaches it.","cn":"桌子与课堂：固定的开会日，以及把它编成课程的教学大纲。"},{"senses":"06","en":"PUBLIC LEADERSHIP: hospitals and universities borrow the corporate phrase.","cn":"公共领导：医院与大学借用这套企业说法。"},{"senses":"08","en":"STRATEGY MADE REAL: the board writes a plan, this group turns it into targets.","cn":"战略成真：董事会写下计划，这组人把它拆成目标。"}]},"affixes":{"intro":{"en":"The phrase is made of two Latin-rooted English words, each with its own prefix and root, and both roots support further English families.","cn":"这个短语由两个拉丁词根的英语词构成，各自带前缀与词根，两个词根还各支撑起进一步的英语词族。"},"latinIntro":{"en":"Latin sequi gives executive, execute and sequence; Latin manus gives management, manual and manage.","cn":"拉丁 sequi 衍生 executive、execute 与 sequence；拉丁 manus 衍生 management、manual 与 manage。"},"items":[{"word":"ex-","structure":"Latin prefix","meaning":"out, through","meaningCN":"出；贯穿","example":"The prefix turns following into finishing.","exampleCN":"前缀把跟随变成做完。"},{"word":"sequi","structure":"Latin verb, third conjugation","meaning":"to follow","meaningCN":"跟随","example":"This root gives the first half of the phrase.","exampleCN":"这个词根给出短语的前一半。"},{"word":"executive","structure":"exsequi plus -ive","meaning":"carrying out; a senior manager","meaningCN":"执行的；高层管理者","example":"The first half names the level that acts.","exampleCN":"前一半点出行动的那一层。"},{"word":"manus","structure":"Latin noun, fourth declension","meaning":"hand; control","meaningCN":"手；掌控","example":"This root gives the second half of the phrase.","exampleCN":"这个词根给出短语的后一半。"},{"word":"management","structure":"manage plus -ment","meaning":"the activity; the managers","meaningCN":"经营；管理层","example":"The second half names the running of work.","exampleCN":"后一半点出对工作的经营。"},{"word":"manager","structure":"manage plus -er","meaning":"one who runs the work","meaningCN":"负责运转的人","example":"The person inside the second half.","exampleCN":"后一半里所指的那个人。"},{"word":"managerial","structure":"manager plus -ial","meaning":"of managers","meaningCN":"管理者的","example":"The adjective that describes that person's work.","exampleCN":"描述那个人所做工作的形容词。"},{"word":"manage","structure":"maneggiare through French","meaning":"to handle, run","meaningCN":"经营；应付","example":"The verb beneath management.","exampleCN":"它是 management 背后那个表示「经营」的动词。"}],"latinEntries":[{"word":"exsequi","structure":"exsequi, exsecutus sum (verb, third conjugation)","meaning":"to carry out","meaningCN":"执行；贯彻"},{"word":"manus","structure":"manus, manus (n., fourth declension)","meaning":"hand","meaningCN":"手"},{"word":"administrare","structure":"administrare, administravi, administratum (verb, first conjugation)","meaning":"to manage, serve","meaningCN":"管理；经办"}],"derivatives":[{"word":"executive","pos":"n./adj.","zh":"高层管理者；执行的"},{"word":"management","pos":"n.","zh":"管理；管理层"},{"word":"managerial","pos":"adj.","zh":"管理的"},{"word":"manager","pos":"n.","zh":"经理"}]}},{"word":"supervise","ipa_uk":"/ˈsuːpəvaɪz/","ipa_us":"/ˈsuːpərvaɪz/","definition_zh":"监督；管理；指导；看管（工作、活动或人）","definition_en":"to watch over people or work and make sure it is done properly","core_image":"一个人站在高处的平台边，低头看着下面每一道工序","scene":"实验室新来的学生要做一组危险反应，导师没有替他动手，只站在旁边看每一步，出错就叫停。A senior researcher supervises every first attempt in the fume hood.","sceneCN":"这里 supervise 指在旁边看管、确保别人把事做对（第 1 个义项：监督他人的工作）；句意：一位资深研究员在通风柜旁监督每一次初次操作。图中可辨识物件：通风柜、实验记录、护目镜、警示标牌。","pos":[{"tag":"v.","zh":"监督；管理；指导；看管"},{"tag":"v.","zh":"监考；监视（流程或设备）"}],"collocations":[{"phrase":"supervise work","zh":"监督工作"},{"phrase":"supervise staff","zh":"管理员工"},{"phrase":"supervise a project","zh":"监管项目"},{"phrase":"supervise an exam","zh":"监考"},{"phrase":"supervise a thesis","zh":"指导学位论文"},{"phrase":"supervise construction","zh":"监督施工"}],"forms":[{"label":"三单（第三人称单数）","form":"supervises"},{"label":"过去式","form":"supervised"},{"label":"过去分词","form":"supervised"},{"label":"现在分词","form":"supervising"},{"label":"名词（监督）","form":"supervision"},{"label":"施动者名词","form":"supervisor"}],"derivatives":[{"word":"supervision","pos":"n.","zh":"监督；指导"},{"word":"supervisor","pos":"n.","zh":"监督者；主管"},{"word":"supervisory","pos":"adj.","zh":"监督的"},{"word":"supervised","pos":"adj.","zh":"有监督的；受指导的"}],"senses":[{"no":"01","title":"Watch over other people's work","titleCN":"在旁边看管别人干活","definition":"to watch workers and check that their work is done correctly","definitionCN":"看住正在做事的人，核查其工作是否正确完成","example":"A foreman supervises the welding on the upper deck.","exampleCN":"一名工头在上层甲板上监督焊接。","why":"Super- means over and videre means to see, so the word is literally looking down on the work.","whyCN":"super 意为「在上」，videre 意为「看」，因此这个词字面上就是从上方看着工作。"},{"no":"02","title":"Be in charge of a whole activity","titleCN":"对整个活动负全责","definition":"to be the person responsible for an activity or a place and how it is run","definitionCN":"对一项活动或一个场所及其运作负总责","example":"She supervises the whole summer programme at the camp.","exampleCN":"她负责夏令营整个暑期项目的监管。","why":"Responsibility grows out of looking: whoever watches over everything must answer for it.","whyCN":"责任由「看」长出来：看住全局的人，就得为全局负责。"},{"no":"03","title":"Invigilate an examination","titleCN":"在考场里监考","definition":"to watch candidates during an examination so that the rules are kept","definitionCN":"考试期间看住考生，使规则得到遵守","example":"Two teachers supervise the hall during the written paper.","exampleCN":"笔试期间有两位老师在考场监考。","why":"An exam is a small closed world, and someone must stand above it and see that nothing passes unseen.","whyCN":"考场是一个封闭的小世界，必须有人站在高处看着，不让任何事在无人察觉中发生。"},{"no":"04","title":"Guide a research student","titleCN":"指导一名研究生的论文","definition":"to advise a student and check the progress of their research over months","definitionCN":"在数月间指导学生并检查其研究进展","example":"He supervises three doctoral students in the same lab.","exampleCN":"他在同一个实验室指导三名博士生。","why":"Research is slow work with no visible product, so its supervision is periodic looking rather than standing guard.","whyCN":"研究是缓慢且没有可见产出的工作，因此对它的「看」是定期巡视，而不是站岗。"},{"no":"05","title":"Oversee a building site","titleCN":"在工地上监管施工","definition":"to watch a construction site to ensure the work matches the drawings and the safety rules","definitionCN":"在施工现场看管，确保施工符合图纸与安全规定","example":"An engineer supervises the pouring of the foundation.","exampleCN":"一位工程师监督地基浇筑。","why":"On a site the drawing is the truth, and the supervisor's eye compares stone with paper.","whyCN":"在工地上，图纸就是准绳，监督者的眼睛把石头与纸上的线对照起来。"},{"no":"06","title":"Monitor a process or machine","titleCN":"监视流程或设备的运行","definition":"to keep a continuous check on a machine or process, often through instruments","definitionCN":"对机器或流程作持续检查，常借助仪表","example":"Software supervises the temperature of the kiln all night.","exampleCN":"软件整夜监视窑炉的温度。","why":"When no person can stand beside the machine, instruments take over the looking.","whyCN":"没人能整夜守在机器旁时，仪表就替人承担了「看」。"},{"no":"07","title":"Keep watch over people for safety","titleCN":"为安全看管儿童或病人","definition":"to stay with children or patients in order to prevent harm","definitionCN":"陪伴儿童或病人，以防他们受到伤害","example":"Two adults supervise the children in the shallow end.","exampleCN":"两位成年人在浅水区看管孩子。","why":"Here the object watched is a person rather than a task, and the eye is guarding, not judging.","whyCN":"这里被看的是人而不是活，眼睛起的是守护作用，而不是评判。"},{"no":"08","title":"Check work remotely through reports","titleCN":"通过报告远程核查工作","definition":"to direct work from a distance by reading reports and approving results","definitionCN":"通过阅读报告与批准结果，在远处指挥工作","example":"The regional office supervises twelve branches by monthly report.","exampleCN":"区域办事处靠月度报告监管十二家分店。","why":"Looking over need not mean standing next to; a report is the eye at a distance.","whyCN":"「在上方看」不必站到旁边；一份报告就是远处的眼睛。"}],"etymology":{"intro":{"en":"Supervise comes from Medieval Latin supervisus, the past participle of supervidere 'to look over', built on super 'over' and videre 'to see'. The English verb entered through the same learned channel as survey.","cn":"supervise 来自中世纪拉丁 supervisus，即 supervidere「从上方看」的过去分词，由 super「在上」与 videre「看」构成。这个英语动词与 survey 经由同一条学术渠道进入英语。"},"items":[{"era":"LATIN VIDERE","en":"Videre meant 'to see'. Its perfect stem vis- supplies the vis- inside supervise, supervision and vision.","cn":"videre 意为「看见」。它的完成时词干 vis- 提供了 supervise、supervision 与 vision 里的 vis-。"},{"era":"LATIN SUPER","en":"Super meant 'above, over'. It is the same prefix that gives superstructure and superimpose, and it keeps the picture of a higher eye.","cn":"super 意为「在上、越过」。它与「上部结构」「叠加」两个词用的是同一个前缀，保留「更高处的一只眼」的画面。"},{"era":"MEDIEVAL LATIN SUPERVISUS","en":"Supervidere 'to look over, inspect' produced the participle supervisus, which became the source of the English verb and noun.","cn":"supervidere「巡视、检查」产生分词 supervisus，后者成为英语动词与名词的来源。"},{"era":"FIFTEENTH CENTURY","en":"Supervise is recorded in English from the fifteenth century in the sense of inspecting or having charge of work; the date is approximate.","cn":"supervise 在十五世纪见于英语记录，意为检查或掌管工作；年代为约数。"},{"era":"SHARED SOURCE WITH SURVEY","en":"Survey came through Old French surveeir from the same Latin verb, so the two English words are cousins rather than strangers.","cn":"survey 经古法语 surveeir 来自同一个拉丁动词，因此这两个英语词是表亲而非陌路。"},{"era":"MODERN EXTENSIONS","en":"The academic, construction and machine senses are nineteenth- and twentieth-century specialisations of the same act of looking over.","cn":"学术、施工与机器方面的义项，是同一个「巡视」动作在十九、二十世纪的专业化。"}]},"similar":{"note":{"en":"The first group shares the vis- root or a near shape; the second group holds verbs of watching and checking.","cn":"第一组共享 vis- 词根或形音相近；第二组是表示看管与核查的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"supervision","ipa":"/ˌsuːpəˈvɪʒn/","tag":"same root","definition":"The noun of the activity, not the act performed on a particular day.","definitionCN":"指这项活动的名词，不是某一天的具体动作。"},{"word":"supervisor","ipa":"/ˈsuːpəvaɪzə/","tag":"same root","definition":"The person who does the watching.","definitionCN":"负责看管的那个人。"},{"word":"survey","ipa":"/ˈsɜːveɪ/","tag":"same root, different sense","definition":"From the same Latin verb, but it means to examine a whole area or to ask a sample of people.","definitionCN":"同出那个拉丁动词，但指勘察整片区域或调查一批人。"},{"word":"supervene","ipa":"/ˌsuːpəˈviːn/","tag":"different root","definition":"Built on super plus venire 'to come', so it means to come on top of something, not to watch it.","definitionCN":"由 super 加 venire「来」构成，意为随后附加而来，不是看管。"}]},{"heading":"NEAR MEANING","entries":[{"word":"oversee","ipa":"/ˌəʊvəˈsiː/","tag":"near meaning","definition":"The English twin of supervise, slightly more general and often used of projects.","definitionCN":"supervise 的英语对应词，含义稍泛，常用于项目。"},{"word":"monitor","ipa":"/ˈmɒnɪtə/","tag":"near meaning","definition":"Watch continuously, usually by instrument, without necessarily having authority.","definitionCN":"持续观察，通常借助仪表，未必拥有管辖权。"},{"word":"superintend","ipa":"/ˌsuːpərɪnˈtend/","tag":"near meaning","definition":"A formal word for being in charge of an operation from above.","definitionCN":"较正式的「在上面掌管一项运作」的说法。"},{"word":"invigilate","ipa":"/ɪnˈvɪdʒɪleɪt/","tag":"near meaning","definition":"The narrow British verb for watching an examination.","definitionCN":"英式英语中专门指监考的动词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real Latin pieces and the real word family.","cn":"正常联想使用两个真实的拉丁构件与真实的同族词。"},"normal":[{"en":"Super is over and videre is to see, so supervise is to see over the work.","cn":"super 是「在上」，videre 是「看」，supervise 就是在上面看着工作。"},{"en":"The family runs supervise, supervision, supervisor and supervisory.","cn":"同族词有 supervision、supervisor、supervisory 与 supervisorship。"},{"en":"Real objects of the verb are work, staff, an exam, a thesis and a site.","cn":"这个动词的真实宾语是工作、员工、考试、论文与工地。"},{"en":"Vision belongs to the same root, because watching and seeing are one act.","cn":"vision 同出这个词根，因为看管与看见本是一个动作。"},{"en":"Survey is a cousin: it looks over a whole area rather than over people.","cn":"survey 是表亲：它巡视的是一整片区域，而不是人。"}],"abstract":[{"en":"Picture an eye at the top of a shaft, following a bucket all the way down.","cn":"想象竖井顶端的一只眼，跟着吊桶一路下到底。"},{"en":"Picture a hand that corrects a line only after the pen has stopped.","cn":"想象一只手只在笔停下之后才去改那一行。"},{"en":"Picture a lamp that moves along the bench, always lighting the next cut.","cn":"想象一盏灯沿工作台移动，总照着下一刀。"}]},"examples":[{"en":"A nurse supervises the trainees during their first injection.","cn":"护士在实习生第一次注射时在旁监督。"},{"en":"The committee was set up to supervise the spending of the grant.","cn":"这个委员会是为监督这笔拨款的使用而设的。"},{"en":"No one supervised the loading, and two crates were crushed.","cn":"装车时没人监管，两只板条箱被压坏了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「super（在上）+ vise（看）」——站在上面看，就是监督","word":"supervise"},"root":"中世纪拉丁 supervisus（supervidere 的过去分词）= super「在上」+ videre「看见」；同根词有 supervision、supervisor、vision，survey 亦同出一源。","sensesIntro":{"en":"Eight senses keep one eye above the work: it watches a crew, takes charge of a programme, guards an exam, follows a student for months, compares a site with its drawings, reads instruments, watches children and reads distant reports.","cn":"八个义项都保持「一只眼在工作上方」：看住工班、负责一个项目、守住考场、跟上学生数月、把工地与图纸对照、读仪表、看住孩子，以及读远方送来的报告。"},"semanticMap":{"core":{"en":"CORE IMAGE: an eye above the work, following each step without touching it.","cn":"核心意象：一只眼在工作上方，跟着每一步，却不伸手。"},"chain":["EYE ABOVE THE WORK","RESPONSIBLE FOR THE WHOLE","THE CLOSED ROOM","THE LONG PROJECT","THE INSTRUMENT'S EYE","THE DISTANT REPORT"],"branches":[{"senses":"01 · 02","en":"THE CREW AND THE PROGRAMME: watching hands, and answering for everything.","cn":"工班与项目：看着一双手，也为全局负责。"},{"senses":"03","en":"THE CLOSED ROOM: an examination is watched so nothing passes unseen.","cn":"封闭的房间：考场被看着，不让任何事漏过。"},{"senses":"04 · 05","en":"SLOW WORK AND HARD STONE: months of research, and drawings checked against concrete.","cn":"慢工与硬石：数月的研究，以及把图纸与混凝土对照。"},{"senses":"06","en":"THE INSTRUMENT'S EYE: when no person can stay, a gauge does the looking.","cn":"仪表之眼：没人守得住时，由表盘来看。"},{"senses":"07 · 08","en":"FROM GUARDING TO REPORTING: watching a child for safety, and reading a branch's monthly sheet.","cn":"从守护到汇报：为安全看着孩子，以及读分店的月报。"}]},"affixes":{"intro":{"en":"Supervise is a Latin preposition plus a seeing root, and the same two pieces build a number of English words.","cn":"supervise 是一个拉丁介词加上一个「看见」词根，同样的两个构件还构成若干英语词。"},"latinIntro":{"en":"Latin super gives supervise, superstructure and superimpose; Latin videre gives vision, visual and evident.","cn":"拉丁 super 衍生 supervise（监督）、superstructure（上部结构）与 superimpose（叠加）；拉丁 videre 衍生 vision（视觉）、visual（视觉的）与 evident（明显的）。"},"items":[{"word":"super-","structure":"Latin prefix","meaning":"above, over","meaningCN":"在上；越过","example":"The prefix places the eye higher than the work.","exampleCN":"前缀把眼睛放在比工作更高的位置。"},{"word":"videre","structure":"Latin verb, second conjugation","meaning":"to see","meaningCN":"看见","example":"The root supplies the watching.","exampleCN":"这个词根提供「看」这个动作。"},{"word":"supervidere","structure":"super- plus videre","meaning":"to look over, inspect","meaningCN":"巡视；检查","example":"The compound is the direct source of the English verb.","exampleCN":"这个复合词是英语动词的直接来源。"},{"word":"supervise","structure":"supervisus to English","meaning":"to watch over work","meaningCN":"监督；管理","example":"The verb keeps the plain act of looking over.","exampleCN":"动词保留「在上方看」的直白动作。"},{"word":"supervision","structure":"supervise plus -ion (action)","meaning":"the act of watching over","meaningCN":"监督；指导","example":"The noun names the activity rather than one occasion.","exampleCN":"名词指这项活动，而非某一次。"},{"word":"supervisor","structure":"supervise plus -or (agent)","meaning":"one who watches over","meaningCN":"监督者；主管","example":"The agent noun names the eye.","exampleCN":"施动名词点出那只眼。"},{"word":"supervisory","structure":"supervisor plus -y (relating to)","meaning":"of a supervisor","meaningCN":"监督的","example":"The adjective describes the role.","exampleCN":"形容词描述这种角色。"},{"word":"survey","structure":"supervidere through Old French","meaning":"to look over an area","meaningCN":"勘察；调查","example":"The cousin looks over land, not people.","exampleCN":"这位表亲巡视的是土地，不是人。"},{"word":"vision","structure":"videre plus -ion","meaning":"the power of seeing","meaningCN":"视力；远见","example":"The root also names seeing itself.","exampleCN":"这个词根也命名「看」本身。"}],"latinEntries":[{"word":"videre","structure":"videre, vidi, visum (verb, second conjugation)","meaning":"to see","meaningCN":"看见"},{"word":"supervidere","structure":"supervidere, supervidi, supervisum (verb, second conjugation)","meaning":"to look over, inspect","meaningCN":"巡视；检查"},{"word":"visio","structure":"visio, visionis (n., third declension)","meaning":"a seeing, vision","meaningCN":"看见；异象"}],"derivatives":[{"word":"supervision","pos":"n.","zh":"监督；指导"},{"word":"supervisor","pos":"n.","zh":"监督者"},{"word":"supervisory","pos":"adj.","zh":"监督的"},{"word":"supervised","pos":"adj.","zh":"受监督的"}]}},{"word":"supervisor","ipa_uk":"/ˈsuːpəvaɪzə/","ipa_us":"/ˈsuːpərvaɪzər/","definition_zh":"监督者；主管；导师；（美国部分地区的）县政委员；监考人","definition_en":"a person who watches over other workers or a process and is responsible for it","core_image":"一个站在工序尽头的人，手里拿着清单，逐项核对刚做完的东西","scene":"流水线末端的检查台上，每件成品都要经过同一个人复核，合格才盖章。A supervisor checks the last item before the line stops for the night.","sceneCN":"这里 supervisor 指对他人工作或流程负监督之责的人（第 1 个义项：直接看管工人的人）；句意：产线夜里停工前，主管检查最后一件产品。图中可辨识物件：检查台、成品、印章、交接记录。","pos":[{"tag":"n.","zh":"监督者；主管；导师；监考人；（美国）县政委员"}],"collocations":[{"phrase":"shift supervisor","zh":"值班主管"},{"phrase":"production supervisor","zh":"生产主管"},{"phrase":"research supervisor","zh":"研究导师"},{"phrase":"site supervisor","zh":"现场主管"},{"phrase":"call centre supervisor","zh":"呼叫中心主管"},{"phrase":"county supervisor","zh":"县政委员"}],"forms":[{"label":"单数","form":"supervisor"},{"label":"复数","form":"supervisors"},{"label":"动词","form":"supervise"},{"label":"名词（监督）","form":"supervision"},{"label":"形容词","form":"supervisory"},{"label":"职位名词","form":"supervisorship"}],"derivatives":[{"word":"supervise","pos":"v.","zh":"监督"},{"word":"supervision","pos":"n.","zh":"监督；指导"},{"word":"supervisory","pos":"adj.","zh":"监督的"},{"word":"supervisorship","pos":"n.","zh":"主管职位"}],"senses":[{"no":"01","title":"The one who watches the workers","titleCN":"直接看管工人的人","definition":"a person whose job is to watch other workers and see that the work is done properly","definitionCN":"受雇看住其他工人并确保工作做好的那个人","example":"The supervisor stopped the line when she saw the wrong label.","exampleCN":"主管看到标签贴错，就叫停了产线。","why":"The word is the agent form of supervise, so it names the eye that sits above the work.","whyCN":"这个词是 supervise 的施动形式，命名的是悬在工作上方的那只眼。"},{"no":"02","title":"Head of a shift or unit","titleCN":"一个班次或单元的主管","definition":"the person in charge of one shift, counter or small unit during working hours","definitionCN":"在工作时段内负责一个班次、柜台或小单元的人","example":"The night-shift supervisor counts the keys before handing over.","exampleCN":"夜班主管在交接前清点钥匙。","why":"A shift is a closed block of time, and one person must answer for that block.","whyCN":"一个班次是一段封闭的时间，必须有人为这一段负责。"},{"no":"03","title":"Academic research adviser","titleCN":"研究生的论文导师","definition":"a teacher who guides a student's research and approves its progress","definitionCN":"指导学生研究并核可其进度的一位教师","example":"Her supervisor asked for a shorter literature review.","exampleCN":"她的导师要求把文献综述写短一些。","why":"Research has no shift and no counter, so the same eye is lent to one student for years.","whyCN":"研究没有班次也没有柜台，于是同一只眼借给一个学生好几年。"},{"no":"04","title":"An elected county official","titleCN":"民选的县政委员","definition":"in some American states, an elected member of a county's governing board","definitionCN":"在美国某些州，县管理委员会的民选成员","example":"The county supervisor voted against the new landfill.","exampleCN":"那位县政委员投票反对新建填埋场。","why":"Local government borrowed the title for an officer who watches over county business.","whyCN":"地方政府借用了这个称号，指看管县务的官员。"},{"no":"05","title":"An examination invigilator","titleCN":"考场里的监考人","definition":"the person who watches candidates during an examination","definitionCN":"考试期间看住考生的人","example":"The supervisor read the rules before opening the envelopes.","exampleCN":"监考人在拆封前宣读了考场规则。","why":"An exam is a guarded room, and the guard is called by the watching word.","whyCN":"考场是一个被守住的房间，守门人就用那个表示「看」的词来称呼。"},{"no":"06","title":"A program that controls other programs","titleCN":"控制其他程序的程序","definition":"a controlling program that starts, stops and watches other processes","definitionCN":"负责启动、停止并监视其他进程的控制程序","example":"The supervisor restarts any worker that crashes.","exampleCN":"监控程序会重启任何崩溃的工作进程。","why":"When software took over the watching, the name of the person passed to the program.","whyCN":"当软件接手「看管」，人的名称就传给了程序。"},{"no":"07","title":"The hospital officer who allocates beds","titleCN":"在医院调度床位与人员的主管","definition":"the nursing officer who coordinates beds and staffing across a hospital at night","definitionCN":"夜间统筹全院床位与护理人力的护理主管","example":"The house supervisor found a bed for the second ambulance.","exampleCN":"值班主管为第二辆救护车找到了床位。","why":"A whole hospital at night is one closed block, and one watching officer keeps it balanced.","whyCN":"夜里的整座医院是一个封闭单元，由一位值班主管让它保持平衡。"},{"no":"08","title":"A visit monitor in social services","titleCN":"社会福利中监督探视的人","definition":"a person who watches a court-ordered family visit to keep everyone safe","definitionCN":"在法院指定的家庭探视中在场监督、保障各方安全的人","example":"A supervisor sat in the corner during the two-hour visit.","exampleCN":"两小时的探视中，一位监督员坐在角落。","why":"Here the eye protects rather than judges, which is the guarding side of the same word.","whyCN":"这里的眼睛是保护而非评判，这正是同一个词里「守护」的那一面。"}],"etymology":{"intro":{"en":"Supervisor is the agent noun of supervise, from Medieval Latin supervisus 'looked over'. Its many job senses all keep one picture: an eye placed above a piece of work.","cn":"supervisor 是 supervise 的施动名词，源自中世纪拉丁 supervisus「被巡视过的」。它的众多职位义都保留同一个画面：一只眼悬在一项工作的上方。"},"items":[{"era":"LATIN VIDERE","en":"Videre 'to see' gives the vis- of supervisor, and also vision and visible.","cn":"videre「看见」提供了 supervisor 里的 vis-，也提供 vision 与 visible。"},{"era":"LATIN SUPER","en":"Super 'above' places the watcher higher than the watched, which is why the title carries authority.","cn":"super「在上」把看的人放在被看者之上，因此这个称号带有权力。"},{"era":"MEDIEVAL LATIN","en":"Supervidere 'to inspect' produced the participle supervisus and the agent form supervisor in medieval Latin.","cn":"supervidere「检查」在中世纪拉丁产生分词 supervisus 与施动形式 supervisor。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"Supervisor appears in English in the sixteenth century, at first for an inspector of work; the earliest date is approximate.","cn":"supervisor 在十六世纪出现于英语，最初指工作的检查者；最早年代为约数。"},{"era":"NEW OFFICES","en":"County boards, hospitals and computing gave the title new offices in the nineteenth and twentieth centuries.","cn":"县政委员会、医院与计算机在十九、二十世纪赋予这个称号新的职位。"}]},"similar":{"note":{"en":"The first group shares the supervise root or a near shape; the second group names other people who check work.","cn":"第一组共享 supervise 词根或形音相近；第二组是其他核查工作的人。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"supervise","ipa":"/ˈsuːpəvaɪz/","tag":"same root","definition":"The verb, naming the activity rather than the person.","definitionCN":"动词，指活动而不是人。"},{"word":"supervision","ipa":"/ˌsuːpəˈvɪʒn/","tag":"same root","definition":"The activity or the state of being watched over.","definitionCN":"指监督活动或被监督的状态。"},{"word":"supervisory","ipa":"/ˌsuːpəˈvaɪzəri/","tag":"same root","definition":"The adjective describing the role or its powers.","definitionCN":"描述该角色或其权力的形容词。"},{"word":"surveyor","ipa":"/səˈveɪə/","tag":"same root, different sense","definition":"From the same Latin verb, but the person measures land rather than staff.","definitionCN":"同出那个拉丁动词，但此人是丈量土地，不是看人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"manager","ipa":"/ˈmænɪdʒə/","tag":"near meaning","definition":"Runs a unit and its results; a supervisor may only check that rules are kept.","definitionCN":"经营一个单元及其成果；主管可能只核查规则是否遵守。"},{"word":"overseer","ipa":"/ˈəʊvəsiːə/","tag":"near meaning","definition":"The English-rooted word for the same role, often on plantations or worksites.","definitionCN":"同一角色的英语本族词，常用于种植园或工地。"},{"word":"foreman","ipa":"/ˈfɔːmən/","tag":"near meaning","definition":"The working leader of a gang of manual workers.","definitionCN":"一组体力工人中带班的领头人。"},{"word":"invigilator","ipa":"/ɪnˈvɪdʒɪleɪtə/","tag":"near meaning","definition":"The British title for the person who watches an examination.","definitionCN":"英式英语中监考人的称号。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real agent suffix, the real family and real job titles.","cn":"正常联想使用真实的施动后缀、真实的同族词与真实的职位名称。"},"normal":[{"en":"Supervise plus -or gives supervisor, literally the one who looks over.","cn":"supervise 加施动后缀得到 supervisor，字面上就是「在上方看的那一个」。"},{"en":"The family runs supervise, supervision, supervisory and supervisorship.","cn":"同族词有 supervise、supervision、supervisory 与 supervisorship。"},{"en":"Titles show the range: shift supervisor, site supervisor, research supervisor.","cn":"职位显示它的范围：值班主管、现场主管、研究导师。"},{"en":"The vis- inside means seeing, which is why a supervisor is first an eye.","cn":"其中的 vis- 意为看见，因此主管首先是一只眼。"},{"en":"In computing the same name passed from the person to a program.","cn":"在计算机里，同一个名称从人传给了程序。"}],"abstract":[{"en":"Picture a hand that touches nothing but marks each finished piece with a stamp.","cn":"想象一只手什么也不碰，只给每件成品盖一个章。"},{"en":"Picture a lamp at the end of a tunnel that lights each worker as they pass.","cn":"想象隧道尽头的一盏灯，照着每个经过的工人。"},{"en":"Picture a list where every line is already ticked before the shift ends.","cn":"想象一张清单，班次结束前每行都已画了勾。"}]},"examples":[{"en":"Her supervisor signed off the report after one revision.","cn":"她的导师在改过一稿后签批了报告。"},{"en":"The shift supervisor sent two workers home early.","cn":"值班主管让两名工人提前回家。"},{"en":"A floor supervisor walks the aisles before the store opens.","cn":"开店前，卖场主管会走一遍货架通道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「super（在上）+ visor（看的人）」——在上面看着的人，就是主管","word":"supervisor"},"root":"中世纪拉丁 supervisus（supervidere「巡视」的过去分词）+ 施动后缀；同根词有 supervise、supervision、vision。","sensesIntro":{"en":"Eight senses keep one eye at work: it watches a crew, holds one shift, guides one student, sits on a county board, guards an exam, controls other programs, balances a hospital at night and protects a family visit.","cn":"八个义项都让一只眼留在工作现场：看住工班、守住一个班次、带一个学生、坐在县政委员会、守住考场、控制其他程序、夜里平衡整座医院、保护一次家庭探视。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person at the end of the line with a list, ticking each finished item.","cn":"核心意象：一个人拿着清单站在产线末端，逐项打勾。"},"chain":["THE EYE ABOVE","THE SHIFT","THE STUDENT","THE COUNTY BOARD","THE GUARDED ROOM","THE PROTECTIVE EYE"],"branches":[{"senses":"01 · 02","en":"THE CREW AND THE SHIFT: the same eye, once on the work and once on the clock.","cn":"工班与班次：同一只眼，一次看活，一次看钟。"},{"senses":"03","en":"THE STUDENT: the eye is lent to one person for years.","cn":"学生：这只眼借给一个人好几年。"},{"senses":"04","en":"THE COUNTY BOARD: local government borrows the title.","cn":"县政委员会：地方政府借用了这个称号。"},{"senses":"05 · 08","en":"THE GUARDED AND THE PROTECTED: an exam is watched to keep rules, a visit to keep people safe.","cn":"看守与保护：监考为守规则，探视为保安全。"},{"senses":"06 · 07","en":"THE MACHINE AND THE WARD: a program and a night officer both keep many parts in balance.","cn":"机器与病区：一个程序与一位夜班主管都在让众多部分保持平衡。"}]},"affixes":{"intro":{"en":"Supervisor is supervise plus an agent ending, and the seeing root behind it also builds words about sight and inspection.","cn":"supervisor 是 supervise 加上施动词尾，其背后的「看见」词根还构成与视觉、检查有关的词。"},"latinIntro":{"en":"Latin videre gives vision, visible and evident; supervidere gives supervise, supervision and survey.","cn":"拉丁 videre 衍生 vision、visible 与 evident；supervidere 衍生 supervise、supervision 与 survey。"},"items":[{"word":"super-","structure":"Latin prefix","meaning":"above, over","meaningCN":"在上；越过","example":"The prefix places the eye above the work.","exampleCN":"前缀把眼放在工作上方。"},{"word":"videre","structure":"Latin verb, second conjugation","meaning":"to see","meaningCN":"看见","example":"The root supplies the watching.","exampleCN":"这个词根提供看管。"},{"word":"supervidere","structure":"super- plus videre","meaning":"to inspect, look over","meaningCN":"巡视；检查","example":"The compound is the medieval source.","exampleCN":"这个复合词是中世纪以来的源头。"},{"word":"supervise","structure":"supervisus to English","meaning":"to watch over work","meaningCN":"监督","example":"The verb is the base of this noun.","exampleCN":"动词是这个名词的基座。"},{"word":"supervisor","structure":"supervise plus -or (agent)","meaning":"one who watches over","meaningCN":"监督者；主管","example":"The ending marks the person.","exampleCN":"词尾标出人。"},{"word":"supervision","structure":"supervise plus -ion","meaning":"the act of watching over","meaningCN":"监督；指导","example":"The action noun sits beside the person noun.","exampleCN":"动作名词与人名词并列。"},{"word":"supervisory","structure":"supervisor plus -y","meaning":"of a supervisor","meaningCN":"监督的","example":"The adjective describes the office.","exampleCN":"形容词描述这个职位。"},{"word":"supervisorship","structure":"supervisor plus -ship (office)","meaning":"the post of supervisor","meaningCN":"主管职位","example":"The suffix names the office, not the person.","exampleCN":"后缀指职位，不指人。"},{"word":"survey","structure":"supervidere through Old French","meaning":"to look over land","meaningCN":"勘察；调查","example":"The cousin word keeps the same eye.","exampleCN":"这位表亲保留同一只眼。"}],"latinEntries":[{"word":"videre","structure":"videre, vidi, visum (verb, second conjugation)","meaning":"to see","meaningCN":"看见"},{"word":"supervidere","structure":"supervidere, supervidi, supervisum (verb, second conjugation)","meaning":"to look over","meaningCN":"巡视"},{"word":"supervisor","structure":"supervisor, supervisoria (n., third declension, medieval)","meaning":"an inspector","meaningCN":"检查者"}],"derivatives":[{"word":"supervise","pos":"v.","zh":"监督"},{"word":"supervision","pos":"n.","zh":"监督"},{"word":"supervisory","pos":"adj.","zh":"监督的"},{"word":"supervisorship","pos":"n.","zh":"主管职位"}]}},{"word":"supervision","ipa_uk":"/ˌsuːpəˈvɪʒn/","ipa_us":"/ˌsuːpərˈvɪʒn/","definition_zh":"监督；指导；（对行业或机构的）监管；监考","definition_en":"the act of watching over work or people and being responsible for them","core_image":"一盏悬在工序上方的灯，把每一道动作照在同一片光里","scene":"新药上市前，每一批记录都要经过同一个人签字，签字人要对记录里的每个数字负责。Good supervision catches mistakes while they are still small.","sceneCN":"这里 supervision 指对工作过程持续的查看与担责（第 1 个义项：对他人工作的监督）；句意：好的监督能在错误还小的时候就发现它。图中可辨识物件：批记录、签字栏、批号标签、台灯。","pos":[{"tag":"n.","zh":"监督；指导；监管；监考"}],"collocations":[{"phrase":"under supervision","zh":"在监督之下"},{"phrase":"close supervision","zh":"严密监督"},{"phrase":"clinical supervision","zh":"临床督导"},{"phrase":"supervision of work","zh":"对工作的监督"},{"phrase":"supervision order","zh":"监管令"},{"phrase":"research supervision","zh":"研究指导"}],"forms":[{"label":"单数（不可数）","form":"supervision"},{"label":"复数（指多种监督安排，罕用）","form":"supervisions"},{"label":"动词","form":"supervise"},{"label":"施动者名词","form":"supervisor"},{"label":"形容词","form":"supervisory"}],"derivatives":[{"word":"supervise","pos":"v.","zh":"监督；指导"},{"word":"supervisor","pos":"n.","zh":"监督者；主管"},{"word":"supervisory","pos":"adj.","zh":"监督的"},{"word":"supervised","pos":"adj.","zh":"受监督的"}],"senses":[{"no":"01","title":"Watching over other people's work","titleCN":"对他人工作的监督","definition":"the act of watching other people work and being answerable for what they do","definitionCN":"看住别人做事，并对他们所做之事承担责任","example":"Supervision of the night shift is shared between two nurses.","exampleCN":"夜班的监督由两名护士分担。","why":"The noun is built on supervise, so it names the state of an eye being kept above the work.","whyCN":"这个名词由 supervise 构成，命名的是「有一只眼留在工作上方」的状态。"},{"no":"02","title":"The state of being watched over","titleCN":"处于被看管的状态","definition":"the condition of having one's work checked by someone with authority","definitionCN":"工作被有权限的人核查的状态","example":"Trainees may not handle the solvent without supervision.","exampleCN":"实习生不得在无人监督的情况下接触这种溶剂。","why":"The same noun can shift from the watcher's side to the watched side, because both share one situation.","whyCN":"同一个名词可以从看的人这一边转到被看的那一边，因为两边共处同一情形。"},{"no":"03","title":"Guidance of a research student","titleCN":"对研究生研究的指导","definition":"the regular advising and checking of a student's long research project","definitionCN":"对一名学生长期研究项目的定期指导与核查","example":"Her supervision included a short meeting every second week.","exampleCN":"她的指导包括每两周一次短会。","why":"Research unfolds over months, so this supervision is a rhythm of meetings rather than a single inspection.","whyCN":"研究要展开数月，因此这种指导是一串定期会面，而不是一次检查。"},{"no":"04","title":"Official regulation of an industry","titleCN":"对行业或机构的官方监管","definition":"the control exercised by an authority over an industry or institution","definitionCN":"主管机关对某个行业或机构施加的控制","example":"Banking supervision tightened after the crisis.","exampleCN":"危机之后，银行业监管收紧了。","why":"When the eye belongs to the state rather than to an employer, watching becomes rule-making.","whyCN":"当这只眼属于国家而不是雇主，看管就变成了制定规则。"},{"no":"05","title":"Invigilation of an examination","titleCN":"考试期间的监考","definition":"the watching of candidates during an examination","definitionCN":"考试期间对考生的看管","example":"Supervision of the hall was handed to two outside teachers.","exampleCN":"考场的监考交给了两位外校老师。","why":"A closed room with fixed rules is the simplest place to put one eye in charge.","whyCN":"一个有固定规则的封闭房间，是安置一只眼最单纯的地方。"},{"no":"06","title":"Clinical supervision of practitioners","titleCN":"对从业者的临床督导","definition":"the regular review of a counsellor's or social worker's cases by a senior colleague","definitionCN":"资深同行对咨询师或社工个案的定期复盘","example":"Clinical supervision is built into every counsellor's timetable.","exampleCN":"临床督导被排进每位咨询师的日程。","why":"Here the watched person is also a professional, so the eye advises rather than polices.","whyCN":"这里被看的人本身也是专业人士，因此这只眼是在建议，而不是在纠察。"},{"no":"07","title":"Checking of an installation or site","titleCN":"对施工或安装的核查","definition":"the checking of building or installation work against plans and safety rules","definitionCN":"对照图纸与安全规定核查施工或安装工作","example":"Supervision of the gas connection took three separate visits.","exampleCN":"燃气接管的监督分三次上门完成。","why":"Where work is fixed into a building, the eye must come back more than once.","whyCN":"当工作被固定进一栋建筑，这只眼就必须不止来一次。"},{"no":"08","title":"Watching over children or dependants","titleCN":"对儿童或无自理能力者的看护","definition":"the keeping of a dependent person under someone's watchful care","definitionCN":"把受抚养者置于某人看护之下的状态","example":"The children played in the yard under their grandmother's supervision.","exampleCN":"孩子们在祖母的看护下在院子里玩。","why":"The oldest sense of the root is simply seeing, and here seeing is extended into care.","whyCN":"这个词根最古老的意思只是「看见」，这里看见被延伸成了照料。"}],"etymology":{"intro":{"en":"Supervision is the noun of supervise, from Medieval Latin supervidere 'to look over'. The word has moved from a single act of inspection to a standing arrangement in offices and industries.","cn":"supervision 是 supervise 的名词，源自中世纪拉丁 supervidere「巡视」。这个词从一次性的检查动作，发展为机构和行业里常设的安排。"},"items":[{"era":"LATIN VIDERE","en":"Videre 'to see' gives the vis- of supervision; its perfect stem visus also gives vision and visible.","cn":"videre「看见」给出 supervision 里的 vis-；其完成时词干 visus 也给出 vision 与 visible。"},{"era":"LATIN SUPER","en":"Super 'above' fixes the direction of the gaze: the watcher stands higher than the work.","cn":"super「在上」固定了目光的方向：看的人站在比工作更高的位置。"},{"era":"MEDIEVAL LATIN SUPERVISUS","en":"The participle supervisus, from supervidere, is the form English took over for both the verb and the noun.","cn":"由 supervidere 来的分词 supervisus，就是英语借去构成动词与名词的形式。"},{"era":"ACTION NOUN","en":"The Latin action ending -io, -ionis, through French -ion, turns the act of watching into the name of the arrangement, supervision.","cn":"拉丁语的动作名词词尾经法语进入英语，把「看」这个动作变成这套安排的名称 supervision。"},{"era":"FIFTEENTH CENTURY","en":"Supervision appears in English in the fifteenth century alongside supervise, at first for inspection of work; the date is approximate.","cn":"supervision 与 supervise 同在十五世纪出现于英语，最初指对工作的检查；年代为约数。"},{"era":"PROFESSIONAL FORMS","en":"Clinical, banking and building supervision are nineteenth- and twentieth-century professional arrangements rather than new senses of the root.","cn":"临床、银行与工程的监督是十九、二十世纪的专业安排，而不是词根新增的含义。"}]},"similar":{"note":{"en":"The first group shares the supervise root or a near shape; the second group names neighbouring systems of watching.","cn":"第一组共享 supervise 词根或形音相近；第二组是相邻的看管制度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"supervise","ipa":"/ˈsuːpəvaɪz/","tag":"same root","definition":"The verb, naming the act rather than the standing arrangement.","definitionCN":"动词，指动作而不是常设安排。"},{"word":"supervisor","ipa":"/ˈsuːpəvaɪzə/","tag":"same root","definition":"The person who holds the watching role.","definitionCN":"担任看管角色的那个人。"},{"word":"supervisory","ipa":"/ˌsuːpəˈvaɪzəri/","tag":"same root","definition":"The adjective describing that role or its powers.","definitionCN":"描述该角色或其权力的形容词。"},{"word":"survey","ipa":"/ˈsɜːveɪ/","tag":"same root, different sense","definition":"From the same Latin verb, but it looks over land or a sample of people, not staff at work.","definitionCN":"同出那个拉丁动词，但巡视的是土地或一批受访者，不是上班的员工。"}]},{"heading":"NEAR MEANING","entries":[{"word":"oversight","ipa":"/ˈəʊvəsaɪt/","tag":"near meaning","definition":"The English-rooted twin; it also carries the opposite sense of a missed detail.","definitionCN":"英语本族的对应词，同时带有「漏看」这层相反的意思。"},{"word":"monitoring","ipa":"/ˈmɒnɪtərɪŋ/","tag":"near meaning","definition":"Continuous measurement, often by instruments, without necessarily commanding anyone.","definitionCN":"持续测量，常靠仪表，未必对人有指挥权。"},{"word":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","tag":"near meaning","definition":"The rules an authority imposes, rather than the watching that enforces them.","definitionCN":"主管机关施加的规则，而不是执行规则的看管。"},{"word":"guidance","ipa":"/ˈɡaɪdəns/","tag":"near meaning","definition":"Advice offered to someone learning; it lacks the authority to check.","definitionCN":"给学习者提供的建议，缺少核查的权力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin pieces, the real suffix and the real professional phrases.","cn":"正常联想使用真实的拉丁构件、真实的后缀与真实的专业说法。"},"normal":[{"en":"Super is over, visio is seeing, so supervision is the state of being seen over.","cn":"super 是在上，visio 是看见，supervision 就是被从上面看着的状态。"},{"en":"The family runs supervise, supervisor, supervisory and supervision.","cn":"同族词有 supervise、supervisor、supervisory 与 supervisorship。"},{"en":"Professional phrases mark it: clinical supervision, close supervision, under supervision.","cn":"专业说法标出它的用法：临床督导、严密监督、在监督之下。"},{"en":"The action ending -ion turns the act of watching into an arrangement.","cn":"这个动作名词词尾把「看」的动作变成一种安排。"},{"en":"Where an authority does the watching, supervision becomes regulation.","cn":"当看管者换成主管机关，监督就变成监管。"}],"abstract":[{"en":"Picture a lamp that lights every bench at once, so no corner is dark.","cn":"想象一盏灯同时照亮每张工作台，没有角落是暗的。"},{"en":"Picture a signature line that cannot be skipped, no matter how late it is.","cn":"想象一道不能跳过的签字栏，无论多晚。"},{"en":"Picture a second pair of eyes that arrives exactly when the first pair tires.","cn":"想象第二双眼恰好在第一双眼疲倦时到来。"}]},"examples":[{"en":"The lab works under the supervision of a senior researcher.","cn":"实验室在一位资深研究员的监督下运作。"},{"en":"Supervision of the site was split between two engineers.","cn":"工地的监督由两名工程师分担。"},{"en":"After the audit, supervision of all payments moved to the finance office.","cn":"审计之后，所有付款的监督移交给了财务办公室。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「super（在上）+ vision（看）」——从上面看着，就是监督","word":"supervision"},"root":"中世纪拉丁 supervisus（supervidere「巡视」的分词）+ -ion（动作名词后缀）；同根词有 supervise、supervisor、vision、survey。","sensesIntro":{"en":"Eight senses follow one watching arrangement: the act of watching, the state of being watched, a student's long project, an industry's rules, an exam room, a counsellor's cases, a building site and a child at play.","cn":"八个义项围绕同一套看管安排：看这个动作、被看的状态、学生的长期研究、行业的规则、考场、咨询师的个案、工地，以及在院子里玩的孩子。"},"semanticMap":{"core":{"en":"CORE IMAGE: one lamp above every bench, so no corner of the work stays dark.","cn":"核心意象：一盏灯照着每张工作台，工作的任何角落都不留在暗处。"},"chain":["THE WATCHING ACT","THE WATCHED STATE","LONG RESEARCH","THE INDUSTRY'S RULES","THE GUARDED ROOM","CARE OF A PERSON"],"branches":[{"senses":"01 · 02","en":"ACT AND STATE: watching, and being watched, are the two sides of one arrangement.","cn":"动作与状态：看与被看，是同一套安排的两面。"},{"senses":"03","en":"LONG RESEARCH: months of work are watched through regular meetings.","cn":"长期研究：数月的工作靠定期会面来照看。"},{"senses":"04","en":"THE INDUSTRY'S RULES: when the state holds the eye, watching becomes regulation.","cn":"行业规则：当国家握着这只眼，看管就变成监管。"},{"senses":"05 · 07","en":"PLACES WITH FIXED RULES: an exam hall and a gas connection both need more than one visit.","cn":"有固定规则的地点：考场与燃气接管都需要不止一次到场。"},{"senses":"06 · 08","en":"CARE RATHER THAN POLICING: a counsellor and a child are watched in order to help.","cn":"照料而非纠察：咨询师与孩子被看着，是为了帮他们。"}]},"affixes":{"intro":{"en":"Supervision is the noun of a Latin verb of looking over, and its endings and roots both appear across English.","cn":"supervision 是一个表示「从上方看」的拉丁动词的名词，其词尾与词根在英语中都有多处出现。"},"latinIntro":{"en":"Latin super gives superstructure and superimpose; videre gives vision, visible and evident.","cn":"拉丁 super 衍生 superstructure（上部结构）与 superimpose（叠加）；videre 衍生 vision（视觉）、visible（可见的）与 evident（明显的）。"},"items":[{"word":"super-","structure":"Latin prefix","meaning":"above, over","meaningCN":"在上；越过","example":"The prefix sets the eye above the work.","exampleCN":"前缀把眼置于工作之上。"},{"word":"videre","structure":"Latin verb, second conjugation","meaning":"to see","meaningCN":"看见","example":"The root supplies the seeing.","exampleCN":"这个词根提供「看」。"},{"word":"supervidere","structure":"super- plus videre","meaning":"to look over","meaningCN":"巡视","example":"The compound is the medieval source.","exampleCN":"这个复合词是中世纪的源头。"},{"word":"supervise","structure":"supervisus to English","meaning":"to watch over","meaningCN":"监督","example":"The verb is the base of the noun.","exampleCN":"动词是这个名词的基座。"},{"word":"supervision","structure":"supervise plus -ion","meaning":"the act or arrangement of watching","meaningCN":"监督；督导","example":"The ending turns the act into an institution.","exampleCN":"词尾把动作变成制度。"},{"word":"supervisor","structure":"supervise plus -or","meaning":"the one who watches","meaningCN":"监督者","example":"The agent noun names the eye.","exampleCN":"施动名词点出那只眼。"},{"word":"supervisory","structure":"supervisor plus -y","meaning":"of watching","meaningCN":"监督的","example":"The adjective marks the role.","exampleCN":"形容词标出这种角色。"},{"word":"vision","structure":"videre plus -ion","meaning":"the power of seeing","meaningCN":"视力；远见","example":"The same root also names sight itself.","exampleCN":"同一词根也命名「看见」本身。"},{"word":"survey","structure":"supervidere through Old French","meaning":"to look over an area","meaningCN":"勘察","example":"The cousin looks over land instead of staff.","exampleCN":"这位表亲巡视的是土地而不是员工。"}],"latinEntries":[{"word":"videre","structure":"videre, vidi, visum (verb, second conjugation)","meaning":"to see","meaningCN":"看见"},{"word":"supervidere","structure":"supervidere, supervidi, supervisum (verb, second conjugation)","meaning":"to look over","meaningCN":"巡视"},{"word":"visio","structure":"visio, visionis (n., third declension)","meaning":"a seeing","meaningCN":"看见"}],"derivatives":[{"word":"supervise","pos":"v.","zh":"监督"},{"word":"supervisor","pos":"n.","zh":"监督者"},{"word":"supervisory","pos":"adj.","zh":"监督的"},{"word":"supervised","pos":"adj.","zh":"受监督的"}]}},{"word":"oversee","ipa_uk":"/ˌəʊvəˈsiː/","ipa_us":"/ˌoʊvərˈsiː/","definition_zh":"监督；监管；照管；负责（工作、项目或场所）","definition_en":"to be in charge of work or an activity and watch that it is done properly","core_image":"一个人站在脚手架的高处，俯看整片工地","scene":"老屋翻修时，房主每周去看一次，检查砖缝、木料与工期是否按图纸走。A retired engineer oversees the restoration of the old house.","sceneCN":"这里 oversee 指对一项工作负总责并持续查看（第 1 个义项：看管他人的工作）；句意：一位退休工程师监督这座老屋的修复。图中可辨识物件：脚手架、图纸、砖缝、木料堆。","pos":[{"tag":"v.","zh":"监督；监管；照管；负责"}],"collocations":[{"phrase":"oversee a project","zh":"监管项目"},{"phrase":"oversee construction","zh":"监督施工"},{"phrase":"oversee the process","zh":"监管流程"},{"phrase":"oversee an election","zh":"监督选举"},{"phrase":"oversee the transfer","zh":"监督交接"},{"phrase":"oversee a property","zh":"照管房产"}],"forms":[{"label":"三单（第三人称单数）","form":"oversees"},{"label":"过去式","form":"oversaw"},{"label":"过去分词","form":"overseen"},{"label":"现在分词","form":"overseeing"},{"label":"施动者名词","form":"overseer"},{"label":"相关名词（监督；疏忽）","form":"oversight"}],"derivatives":[{"word":"overseer","pos":"n.","zh":"监工；监督者"},{"word":"oversight","pos":"n.","zh":"监督；疏忽"},{"word":"overseen","pos":"adj.","zh":"受监督的"},{"word":"overseeing","pos":"n.","zh":"监督工作"}],"senses":[{"no":"01","title":"Watch over the work of others","titleCN":"看管他人的工作","definition":"to watch people at work and see that they do it correctly","definitionCN":"看着别人做事，确保他们做得正确","example":"She oversees the packing line every morning.","exampleCN":"她每天早上看管包装线。","why":"Over and see say exactly what the word does: an eye placed above the hands.","whyCN":"「在上」与「看见」两个构件把词义说得直白：一只眼放在一双手的上方。"},{"no":"02","title":"Be in charge of a whole operation","titleCN":"对一个整体运作负责","definition":"to hold responsibility for how an operation as a whole is run","definitionCN":"对一个整体运作如何运转承担责任","example":"He oversees the whole depot, from deliveries to repairs.","exampleCN":"他从送货到维修，负责整个仓库。","why":"Responsibility follows the wider view: whoever sees the whole must answer for the whole.","whyCN":"责任跟着视野走：看得见整体的人，就要为整体负责。"},{"no":"03","title":"Check production quality","titleCN":"核查生产质量","definition":"to watch a production process and check that output meets the standard","definitionCN":"看住生产过程，核查产出是否达标","example":"A technician oversees the coating so no panel leaves too thin.","exampleCN":"一名技术员监督涂层，不让任何面板过薄出厂。","why":"Overseeing a process means watching the rule being applied, not watching a person.","whyCN":"监督一个流程，是看着规则被执行，而不是看着某个人。"},{"no":"04","title":"Manage a project or event","titleCN":"把一个项目或活动管到底","definition":"to carry responsibility for a project or event from its start to its finish","definitionCN":"对一个项目或活动从开始到结束负责","example":"Two volunteers oversee the summer fair from the first letter to the last bill.","exampleCN":"两名志愿者从第一封信到最后一张账单，把夏季集市管到底。","why":"A project has a beginning and an end, and the word covers the whole span between them.","whyCN":"项目有起点也有终点，这个词覆盖了两者之间的整段时间。"},{"no":"05","title":"Look after a property","titleCN":"照看一处房产","definition":"to keep an eye on a house or piece of land for its owner","definitionCN":"替业主看住一栋房子或一块土地","example":"A neighbour oversees the flat while the family is abroad.","exampleCN":"这家人出国期间，一位邻居照看那套公寓。","why":"The same eye can be lent to a place rather than to people, and then it means keeping it safe.","whyCN":"同一只眼也能借给一处地方而不是人，那时它的意思就是让它保持安好。"},{"no":"06","title":"Watch a vote or count for fairness","titleCN":"为保证公正而监督投票或计票","definition":"to watch a vote or a count so that the result is honest","definitionCN":"看住投票或计票过程，使结果诚实可信","example":"Independent observers oversaw the recount.","exampleCN":"独立观察员监督了重新计票。","why":"Where trust is thin, the eye is invited in from outside to stand above the process.","whyCN":"在信任薄弱之处，会从外面请一只眼来站到流程上方。"},{"no":"07","title":"Supervise a long piece of research","titleCN":"指导一项长期研究","definition":"to guide and check a student's or colleague's extended research","definitionCN":"指导并核查学生或同事长期进行的研究","example":"The professor oversees four doctoral projects at once.","exampleCN":"这位教授同时指导四个博士项目。","why":"Slow work needs an eye that returns again and again rather than one that stays.","whyCN":"缓慢的工作需要一只反复回来的眼，而不是一直守着的眼。"},{"no":"08","title":"Watch a building site","titleCN":"看管一处工地","definition":"to watch construction work so that it follows the drawings and the safety rules","definitionCN":"看管施工，使工程依图纸与安全规定进行","example":"The clerk of works oversees every pour of concrete.","exampleCN":"工程监督员监督每一次混凝土浇筑。","why":"On a site the drawings and the rules are both visible, so the eye compares two things at once.","whyCN":"工地上图纸与规定都看得见，因此这只眼同时比对两样东西。"}],"etymology":{"intro":{"en":"Oversee is a plain English compound of over and see, modelled on the Latin verb supervidere. It has always meant to look over work, and it keeps a clean distance from the double sense of overlook.","cn":"oversee 是由 over 与 see 构成的英语本族复合词，模仿拉丁 supervidere 而造。它始终表示「从上方看着工作」，并与 overlook 的双重含义保持了清楚的距离。"},"items":[{"era":"OLD ENGLISH OFER","en":"Ofer meant 'over, above', and English kept the physical picture of a gaze coming from a higher place.","cn":"ofer 意为「在上、越过」，英语保留了目光来自较高处的具体画面。"},{"era":"OLD ENGLISH SEON","en":"Seon 'to see' became our see; its past forms gave sight and the modern seen.","cn":"seon「看见」演变为今天的 see；它的过去形式衍生出 sight 与现代的 seen。"},{"era":"MIDDLE ENGLISH COMPOUND","en":"Over and see were joined in Middle English, generally thought to be a loan translation of Latin supervidere rather than a borrowed word.","cn":"over 与 see 在中古英语合成一词，一般认为是对拉丁 supervidere 的仿译，而不是借用词。"},{"era":"SUPERINTENDENCE","en":"The compound first meant to look over a place or a body of workers, and that supervisory sense has stayed central.","cn":"这个复合词最初指从上方看一处地方或一群工人，这一监督义一直是核心。"},{"era":"CLEANER THAN OVERLOOK","en":"Overlook also means to fail to notice, while oversee never does; the two compounds divided the work of the Latin model between them.","cn":"overlook 还兼指漏看，而 oversee 从不这样用；两个复合词把拉丁原型的工作分掉了。"},{"era":"APPROXIMATE FIRST DATES","en":"The first recorded uses are not precisely dated; the word is attested from the late Middle Ages, and the date is approximate.","cn":"最早记录的使用年代并不精确；这个词自中古后期已有记录，年代为约数。"}]},"similar":{"note":{"en":"The first group shares the two English pieces or a near shape; the second group holds verbs of watching and running.","cn":"第一组共享两个英语构件或形音相近；第二组是表示看管与经营的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"overseer","ipa":"/ˈəʊvəsiːə/","tag":"same root","definition":"The person who oversees, especially on a plantation or a worksite.","definitionCN":"负责监督的人，尤指种植园或工地上的监工。"},{"word":"oversight","ipa":"/ˈəʊvəsaɪt/","tag":"same root","definition":"The noun of the role, and also a failure to notice something.","definitionCN":"指这一角色的名词，同时也指漏看。"},{"word":"sight","ipa":"/saɪt/","tag":"same root","definition":"The noun of seeing, from the same verb that gives the second half of oversee.","definitionCN":"表示「看见」的名词，与 oversee 的后半同出那个动词。"},{"word":"overlook","ipa":"/ˌəʊvəˈlʊk/","tag":"same pieces, different word","definition":"Built from over and look; it means both to have a view over and to fail to notice, which oversee never means.","definitionCN":"由表示「在上」与表示「看」的构件构成；既指俯瞰，也指漏看，而 oversee 没有后一义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"supervise","ipa":"/ˈsuːpəvaɪz/","tag":"near meaning","definition":"The Latin-derived twin, often a little more formal.","definitionCN":"拉丁来源的对应词，通常稍正式。"},{"word":"superintend","ipa":"/ˌsuːpərɪnˈtend/","tag":"near meaning","definition":"A formal verb for holding charge of an operation.","definitionCN":"正式用语，指掌管一项运作。"},{"word":"monitor","ipa":"/ˈmɒnɪtə/","tag":"near meaning","definition":"Watch continuously, usually for signs of change, without necessarily having authority.","definitionCN":"持续观察，通常留意变化迹象，未必拥有权力。"},{"word":"manage","ipa":"/ˈmænɪdʒ/","tag":"near meaning","definition":"Run the work and its people; oversee stresses the watching more than the running.","definitionCN":"经营工作及其人员；oversee 更强调看而不是经营。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real English pieces and the real word family.","cn":"正常联想使用两个真实的英语构件与真实的同族词。"},"normal":[{"en":"Over plus see is the whole word: an eye above the hands.","cn":"「在上」加「看见」就是整个词：一双眼在一双手上方。"},{"en":"The family runs overseer, oversight, oversaw and overseen.","cn":"同族词有 overseer、oversight、oversaw 与 overseen。"},{"en":"It is the English twin of supervise, built from native pieces instead of Latin ones.","cn":"它是 supervise 的英语对应词，用本族构件而不是拉丁构件造成。"},{"en":"Real objects are a project, a site, a count, a property and a process.","cn":"它的真实宾语是项目、工地、计票、房产与流程。"},{"en":"Overlook took the 'fail to notice' sense, leaving oversee to mean only watching.","cn":"overlook 拿走了「漏看」那一义，把 oversee 留作纯粹的看着。"}],"abstract":[{"en":"Picture a figure on scaffolding who sees the whole roof at one glance.","cn":"想象脚手架上的人一眼看见整个屋顶。"},{"en":"Picture a hand that never holds a tool but always points to the next joint.","cn":"想象一只手从不拿工具，却总指向下一个接缝。"},{"en":"Picture a lamp on a pole that lights the whole yard and no single bench.","cn":"想象杆上的一盏灯照亮整个院子，却不专照某一张台。"}]},"examples":[{"en":"A committee of three oversees the rebuilding of the bridge.","cn":"一个三人委员会监督这座桥的重建。"},{"en":"She oversees the training of every new mechanic.","cn":"她负责监督每名新技工的培训。"},{"en":"The bank asked an outside firm to oversee the transfer.","cn":"银行请了一家外部公司监督这次交接。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「over（在上）+ see（看）」——在上方看着，就是监督","word":"oversee"},"root":"英语本族复合词：表示「在上」的构件 + 表示「看」的构件，一般认为是对拉丁 supervidere「巡视」的仿译；同族词有 overseer、oversight、overseen。","sensesIntro":{"en":"Eight senses keep the eye above: it watches hands, answers for a whole depot, checks a process, carries a project, guards a flat, attends a recount, follows a doctorate and compares concrete with drawings.","cn":"八个义项都让眼留在上方：看住一双手、为整个仓库负责、核查一个流程、把一个项目管到底、照看一套公寓、到场监督重新计票、跟上博士研究、把混凝土与图纸对照。"},"semanticMap":{"core":{"en":"CORE IMAGE: a figure on the scaffolding who sees the whole site at one glance.","cn":"核心意象：脚手架上的一个人，一眼看见整片工地。"},"chain":["EYE ABOVE THE HANDS","THE WHOLE DEPOT","THE PROCESS","THE PROJECT SPAN","THE EMPTY FLAT","THE HONEST COUNT"],"branches":[{"senses":"01 · 03","en":"HANDS AND PROCESS: watching people work, and watching a rule being applied.","cn":"人与流程：看着人干活，也看着规则被执行。"},{"senses":"02","en":"THE WHOLE: responsibility grows with the width of the view.","cn":"整体：视野有多宽，责任就有多大。"},{"senses":"04 · 08","en":"FROM START TO FINISH: a project's whole span, and a site checked pour by pour.","cn":"从头到尾：项目的整段时间，以及逐次浇筑核查的工地。"},{"senses":"05","en":"THE EMPTY FLAT: the eye lent to a place instead of to people.","cn":"空置的公寓：这只眼借给地方，而不是借给人。"},{"senses":"06 · 07","en":"OUTSIDE EYES: a recount and a doctorate both need an eye from beyond the work.","cn":"外来的眼：重新计票与博士研究都需要一只来自工作之外的眼。"}]},"affixes":{"intro":{"en":"Oversee is built only from English pieces, so it has no Latin ancestors; the Latin verb it copies is given as a model, not as a source.","cn":"oversee 完全由英语构件构成，因此没有拉丁祖先；它模仿的那个拉丁动词只作为样板列出，不是来源。"},"latinIntro":{"en":"The two pieces are over and see; the Latin model supervidere is shown for comparison, not as an origin.","cn":"两个构件是 over 与 see；拉丁样板 supervidere 仅作对照，并非来源。"},"items":[{"word":"over-","structure":"Old English prefix","meaning":"above, across","meaningCN":"在上；越过","example":"The prefix puts the eye higher than the hands.","exampleCN":"前缀把眼放在比手更高的位置。"},{"word":"see","structure":"Old English verb","meaning":"to perceive with the eyes","meaningCN":"看见","example":"The second half supplies the watching.","exampleCN":"后半提供「看」这个动作。"},{"word":"oversee","structure":"over- plus see","meaning":"to watch over work","meaningCN":"监督；照管","example":"The compound is native English, not a borrowing.","exampleCN":"这个复合词是英语本族造词，不是借词。"},{"word":"overseer","structure":"oversee plus -er (one who acts)","meaning":"one who watches over workers","meaningCN":"监工；监督者","example":"The agent ending names the person.","exampleCN":"施动词尾点出人。"},{"word":"oversight","structure":"over- plus sight","meaning":"watching; also a missed detail","meaningCN":"监督；漏看","example":"The noun picked up the negative sense as well.","exampleCN":"这个名词也承接了否定的一面。"},{"word":"sight","structure":"see plus -t (noun)","meaning":"the act or power of seeing","meaningCN":"视觉；看见","example":"The noun of seeing stands behind both halves.","exampleCN":"表示「看见」的名词支撑着前后两半。"},{"word":"overseen","structure":"oversee plus -en (past participle)","meaning":"having been watched over","meaningCN":"受到监督的","example":"The participle marks the work that has been checked.","exampleCN":"分词标出已被核查的工作。"},{"word":"overseeing","structure":"oversee plus -ing","meaning":"the act of watching over","meaningCN":"监督工作","example":"The form names the ongoing activity.","exampleCN":"这一形式指正在进行的工作。"}],"latinEntries":[],"derivatives":[{"word":"overseer","pos":"n.","zh":"监工；监督者"},{"word":"oversight","pos":"n.","zh":"监督；疏忽"},{"word":"overseen","pos":"adj.","zh":"受监督的"},{"word":"overseeing","pos":"n.","zh":"监督工作"}]}},{"word":"oversight","ipa_uk":"/ˈəʊvəsaɪt/","ipa_us":"/ˈoʊvərsaɪt/","definition_zh":"监督；监管；疏忽；漏看；照管的责任","definition_en":"the act of watching over something, or a failure to notice something","core_image":"一只眼越过桌面看向远处，近处的一行字反而没看见","scene":"审计发现付款环节漏了一道复核，随后建议把看管的责任提到更高一层。The audit found an oversight in the payment process.","sceneCN":"这里 oversight 指因疏忽而漏看的一处（第 2 个义项：无意的遗漏）；句意：审计发现付款流程中有一处漏看。图中可辨识物件：审计报告、付款单、复核签栏、红色标记。","pos":[{"tag":"n.","zh":"监督；监管；疏忽；漏看；照管责任"}],"collocations":[{"phrase":"congressional oversight","zh":"国会监督"},{"phrase":"regulatory oversight","zh":"监管"},{"phrase":"financial oversight","zh":"财务监管"},{"phrase":"by oversight","zh":"由于疏忽"},{"phrase":"under the oversight of","zh":"在……的监督之下"},{"phrase":"oversight board","zh":"监督委员会"}],"forms":[{"label":"单数（不可数，监督义）","form":"oversight"},{"label":"复数（指多起疏忽）","form":"oversights"},{"label":"动词","form":"oversee"},{"label":"施动者名词","form":"overseer"},{"label":"过去分词","form":"overseen"}],"derivatives":[{"word":"oversee","pos":"v.","zh":"监督；照管"},{"word":"overseer","pos":"n.","zh":"监工；监督者"},{"word":"overseeing","pos":"n.","zh":"监督工作"},{"word":"overseen","pos":"adj.","zh":"受监督的"}],"senses":[{"no":"01","title":"The act of watching over work","titleCN":"对工作的监督","definition":"the act of watching over work or people and being responsible for them","definitionCN":"看住工作或人员并为之负责的行为","example":"Oversight of the laboratory was given to a new committee.","exampleCN":"实验室的监督权交给了一个新委员会。","why":"Over and sight make the word a plain English picture of an eye kept above something.","whyCN":"「在上」与「看见」两个构件让这个词成为一幅直白的图画：一只眼留在某物上方。"},{"no":"02","title":"An accidental omission","titleCN":"无意的遗漏","definition":"a failure to notice or do something that should have been noticed or done","definitionCN":"该注意到或该做的事没有被注意到或做到","example":"By an oversight, her name was left off the list.","exampleCN":"由于疏忽，她的名字被漏在名单之外。","why":"If the eye is fixed on the far view, the near line escapes it; that is how watching turns into missing.","whyCN":"眼睛盯着远处时，近处那一行就逃过去了；看管正是这样变成漏看。"},{"no":"03","title":"Official supervision by a body","titleCN":"机构对某领域的正式监管","definition":"the supervision exercised by a public body over an industry or service","definitionCN":"公共机构对某个行业或服务施加的监督","example":"Banking oversight moved to a single agency.","exampleCN":"银行业监管移交给了单一机构。","why":"When the eye belongs to a public body, the word names an institution rather than a glance.","whyCN":"当这只眼属于公共机构，这个词命名的就是一个机构，而不是一瞥。"},{"no":"04","title":"A careless mistake","titleCN":"因疏忽而造成的错误","definition":"a mistake made because something was not checked","definitionCN":"因某项事情未被核查而产生的错误","example":"Two oversights in the invoice cost the firm a week.","exampleCN":"发票上的两处疏漏让公司损失了一周时间。","why":"The omission is the missing look; the mistake is what the missing look let through.","whyCN":"疏漏是少看了那一眼；错误是少看那一眼放进来的东西。"},{"no":"05","title":"The duty of watching","titleCN":"看管的职责","definition":"the responsibility for checking that something is done properly","definitionCN":"核查某事是否被妥善完成的职责","example":"The safety of the archive is under his oversight.","exampleCN":"档案的安全由他负责照管。","why":"Here the word is not the act or the failure but the charge laid on a person.","whyCN":"这里这个词既不是动作也不是失误，而是压在某人身上的职责。"},{"no":"06","title":"Legislative supervision of government","titleCN":"立法机关对政府的监督","definition":"the checking of a government's actions by a legislature or a court","definitionCN":"立法机关或法院对政府行为的核查","example":"Congressional oversight delayed the appointment for months.","exampleCN":"国会监督让这项任命拖了几个月。","why":"The eye of one branch is deliberately placed above another, so oversight becomes a constitutional device.","whyCN":"一支机构的眼被有意放在另一支上方，监督于是成了宪制设计。"},{"no":"07","title":"Guardianship of a dependent person","titleCN":"对受抚养者的照管","definition":"the watching care given to someone who cannot look after themselves","definitionCN":"对无法自理者给予的看护","example":"The child remained under her aunt's oversight.","exampleCN":"孩子仍由姑母照管。","why":"The same word can mean protective care when the watched person cannot answer back.","whyCN":"当被看者无法回应时，同一个词可以指保护性的照料。"},{"no":"08","title":"The state of being checked","titleCN":"处于被核查的状态","definition":"the condition of having one's work or conduct checked by another","definitionCN":"工作或行为受到他人核查的状态","example":"Every transfer now takes place under independent oversight.","exampleCN":"现在每笔划转都在独立监督之下进行。","why":"The noun can stand on the watched side as well, naming the situation rather than the watcher.","whyCN":"这个名词也能站在被看的那一边，命名情形而不是看的人。"}],"etymology":{"intro":{"en":"Oversight joins over and sight, both native English words. It first meant supervision, and later, by the logic of looking past a thing, also came to mean a failure to notice.","cn":"oversight 由 over 与 sight 两个英语本族词接成。它最初指监督，后来顺着「目光越过某物」的逻辑，也指漏看。"},"items":[{"era":"OLD ENGLISH OFER","en":"Ofer 'over, above' gives the first half and keeps the picture of a gaze from a higher place.","cn":"ofer「在上、越过」给出前半，并保留目光来自高处的画面。"},{"era":"OLD ENGLISH SIHTH","en":"The noun sihth 'a seeing' became sight, and it supplies the second half of the compound.","cn":"名词 sihth「看见」演变为 sight，提供这个复合词的后半。"},{"era":"MIDDLE ENGLISH NOUN","en":"Over and sight were joined to name the act of looking over something, at first with no hint of failure.","cn":"over 与 sight 合成一体，命名「从上方看某物」的行为，最初毫无失误之意。"},{"era":"THE NEGATIVE SHIFT","en":"The sense of a missed detail is generally dated to the seventeenth century, when looking over a thing could also mean looking past it.","cn":"「漏掉的细节」这一义一般被定在十七世纪，当时「看过某物」也能表示「目光越过它」。"},{"era":"INSTITUTIONAL USE","en":"Legislatures and regulators made oversight a standing arrangement in the eighteenth and nineteenth centuries.","cn":"立法机关与监管机构在十八、十九世纪把监督变成常设安排。"},{"era":"APPROXIMATE FIRST DATES","en":"The first dates for the noun and for its negative sense are approximate; the order of the two senses is reliable.","cn":"这个名词及其否定义的最早年代都是约数；两义的先后顺序可靠。"}]},"similar":{"note":{"en":"The first group shares the over or sight pieces; the second group names neighbouring systems of checking and missing.","cn":"第一组共享 over 或 sight 构件；第二组是相邻的核查与遗漏说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"oversee","ipa":"/ˌəʊvəˈsiː/","tag":"same root","definition":"The verb, which never means to miss something.","definitionCN":"动词，从不表示漏看。"},{"word":"overseer","ipa":"/ˈəʊvəsiːə/","tag":"same root","definition":"The person who holds the watching role.","definitionCN":"担任看管角色的人。"},{"word":"sight","ipa":"/saɪt/","tag":"same root","definition":"The noun of seeing that supplies the second half of the word.","definitionCN":"表示「看见」的名词，提供这个词的后半。"},{"word":"overlook","ipa":"/ˌəʊvəˈlʊk/","tag":"near shape, parallel word","definition":"Also built from over, and it carries both the viewing and the missing sense, much as oversight does.","definitionCN":"同样由表示「在上」的构件构成，也兼有俯瞰与漏看两义，与 oversight 颇为平行。"}]},{"heading":"NEAR MEANING","entries":[{"word":"supervision","ipa":"/ˌsuːpəˈvɪʒn/","tag":"near meaning","definition":"The Latin-derived word for the same watching, usually without the negative sense.","definitionCN":"同义的拉丁来源词，通常不含否定义。"},{"word":"surveillance","ipa":"/səˈveɪləns/","tag":"near meaning","definition":"Close, often covert watching of a person or place.","definitionCN":"对人或者地方进行密切、常为隐蔽的观察。"},{"word":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","tag":"near meaning","definition":"The rules imposed by an authority rather than the watching itself.","definitionCN":"主管机关施加的规则，而不是看管本身。"},{"word":"omission","ipa":"/əˈmɪʃn/","tag":"near meaning","definition":"The act of leaving something out, which is exactly what an oversight is.","definitionCN":"把某物遗漏掉的行为，正是 oversight 所指。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real English pieces and the real institutional phrases.","cn":"正常联想使用两个真实的英语构件与真实的制度用语。"},"normal":[{"en":"Over plus sight is the whole picture: a gaze from above.","cn":"「在上」加「看见」就是整幅画面：从上而下的目光。"},{"en":"The family runs oversee, overseer, oversight and overseen.","cn":"同族词有 oversee、overseer、oversaw 与 overseen。"},{"en":"Institutional phrases mark it: congressional oversight, regulatory oversight, oversight board.","cn":"制度用语标出它的用法：国会监督、监管、监督委员会。"},{"en":"The negative sense comes from looking past a thing rather than at it.","cn":"否定义来自目光越过某物，而不是落在它上面。"},{"en":"Overlook shows the same double life, which helps explain why oversight carries both meanings.","cn":"overlook 也有同样的两面，这有助于解释 oversight 为何兼有褒贬。"}],"abstract":[{"en":"Picture a watchman scanning the horizon while a gate stands open behind him.","cn":"想象一名看守扫视远方，身后的门却敞着。"},{"en":"Picture a signature line that nobody read because everyone trusted the page.","cn":"想象一行签字谁也没读，因为人人都信那张纸。"},{"en":"Picture a hand that checks the far corner and forgets the one under the lamp.","cn":"想象一只手去查远处的角落，却忘了灯下那一个。"}]},"examples":[{"en":"Oversight of the project passed to a committee of five.","cn":"项目的监督移交给了五人委员会。"},{"en":"A single oversight in the labelling kept the shipment at the border.","cn":"标签上的一处疏漏让这批货卡在边境。"},{"en":"The agency was created to provide independent oversight.","cn":"设立这个机构是为了提供独立监督。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「over（在上）+ sight（看）」——在上面看是监督，看漏了就是疏忽","word":"oversight"},"root":"英语本族复合词：表示「在上」的构件 + 表示「看见」的构件；先指监督，十七世纪起引申出「漏看、疏忽」义。","sensesIntro":{"en":"Eight senses hold both halves of the word: the act of watching, an accidental omission, official regulation, the mistake that follows, the duty of watching, legislative checking, care of a dependent and the state of being checked.","cn":"八个义项握住这个词的两面：看管这个动作、无意的遗漏、正式监管、随之而来的错误、看管的职责、立法监督、对受抚养者的照管，以及被核查的状态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gaze fixed on the horizon while the line under the lamp goes unread.","cn":"核心意象：目光盯着远方，灯下那一行却没被读到。"},"chain":["THE WATCHING","THE DUTY","THE INSTITUTION","THE MISSED LINE","THE RESULTING MISTAKE","PROTECTIVE CARE"],"branches":[{"senses":"01 · 05","en":"ACT AND DUTY: watching something, and being charged with watching it.","cn":"动作与职责：看住某物，以及被交付看住它的责任。"},{"senses":"03 · 06","en":"THE INSTITUTION: a public body, and a legislature placed above a government.","cn":"制度：一个公共机构，以及被置于政府之上的立法机关。"},{"senses":"02 · 04","en":"THE MISSED LINE: first the omission, then the error it lets through.","cn":"漏掉的一行：先是遗漏，再是它放进来的错误。"},{"senses":"07","en":"PROTECTIVE CARE: when the watched person cannot answer back, watching becomes guardianship.","cn":"保护性照料：当被看者无法回应，看管就变成监护。"},{"senses":"08","en":"THE WATCHED SIDE: the same noun names the state of being checked.","cn":"被看的一面：同一个名词也命名被核查的状态。"}]},"affixes":{"intro":{"en":"Oversight is a native English compound, so it has no Latin ancestors; its two pieces come from Old English and still work separately.","cn":"oversight 是英语本族复合词，因此没有拉丁祖先；两个构件来自古英语，至今仍能独立使用。"},"latinIntro":{"en":"The pieces are over and sight, and both remain common English words; no Latin source is involved.","cn":"两个构件是 over 与 sight，两者至今都是常用英语词；不涉及拉丁来源。"},"items":[{"word":"over-","structure":"Old English prefix","meaning":"above, across","meaningCN":"在上；越过","example":"The prefix keeps the gaze at a height.","exampleCN":"前缀让目光保持在高度上。"},{"word":"sight","structure":"Old English noun, from the verb to see","meaning":"the act or power of seeing","meaningCN":"视觉；看见","example":"The second half is the eye itself.","exampleCN":"后半就是那只眼本身。"},{"word":"oversight","structure":"over- plus sight","meaning":"watching; a missed detail","meaningCN":"监督；疏忽","example":"The compound holds both a virtue and a failure.","exampleCN":"这个复合词同时含着美德与失误。"},{"word":"oversee","structure":"over- plus see","meaning":"to watch over work","meaningCN":"监督","example":"The verb is the working half of the pair.","exampleCN":"动词是这一对里干活的那一半。"},{"word":"overseer","structure":"oversee plus -er","meaning":"one who watches over","meaningCN":"监工","example":"The person who holds the eye.","exampleCN":"握着那只眼的人。"},{"word":"oversight board","structure":"oversight plus board","meaning":"a body that supervises","meaningCN":"监督委员会","example":"The phrase fixes the institutional sense.","exampleCN":"这个短语固定了制度义。"},{"word":"by oversight","structure":"oversight in its missing sense","meaning":"through a failure to notice","meaningCN":"由于疏忽","example":"The fixed phrase marks the negative sense.","exampleCN":"这个固定说法标出否定义。"},{"word":"oversight hearing","structure":"oversight plus hearing","meaning":"a session that checks a government","meaningCN":"监督听证会","example":"The phrase belongs to legislative practice.","exampleCN":"这个短语属立法实践。"}],"latinEntries":[],"derivatives":[{"word":"oversee","pos":"v.","zh":"监督；照管"},{"word":"overseer","pos":"n.","zh":"监工"},{"word":"overseen","pos":"adj.","zh":"受监督的"},{"word":"overseeing","pos":"n.","zh":"监督工作"}]}},{"word":"coordination","ipa_uk":"/kəʊˌɔːdɪˈneɪʃn/","ipa_us":"/koʊˌɔːrdɪˈneɪʃn/","definition_zh":"协调；配合；（身体动作的）协调性；（语法）并列；（化学）配位","definition_en":"the organizing of different parts or people so that they work together","core_image":"四只手同时拉动同一组滑轮的四条绳，让重物平稳上升","scene":"救援现场有消防、医疗、道路三路人马，各自的指挥员不能直接命令别人，只能先对时间、对路线、对通讯频道。Clear coordination kept the three teams from blocking one another.","sceneCN":"这里 coordination 指让不同人马按同一节拍行动（第 1 个义项：使各方协作的安排）；句意：清晰的协调让三支队伍没有互相堵住。图中可辨识物件：三色袖标、无线电、路线图、计时器。","pos":[{"tag":"n.","zh":"协调；配合；协调性；（语法）并列；（化学）配位"}],"collocations":[{"phrase":"coordination between teams","zh":"团队之间的协调"},{"phrase":"coordination of efforts","zh":"各方努力的协调"},{"phrase":"hand-eye coordination","zh":"手眼协调"},{"phrase":"coordination meeting","zh":"协调会"},{"phrase":"coordination number","zh":"配位数"},{"phrase":"coordination compound","zh":"配位化合物"}],"forms":[{"label":"单数（不可数）","form":"coordination"},{"label":"复数（指多种协调机制，罕用）","form":"coordinations"},{"label":"动词","form":"coordinate"},{"label":"施动者名词","form":"coordinator"},{"label":"形容词","form":"coordinated"},{"label":"相关名词（次序）","form":"order"}],"derivatives":[{"word":"coordinate","pos":"v./n.","zh":"协调；坐标"},{"word":"coordinator","pos":"n.","zh":"协调人"},{"word":"coordinated","pos":"adj.","zh":"协调一致的"},{"word":"coordinate","pos":"adj.","zh":"同等的；并列的"}],"senses":[{"no":"01","title":"Making different parts work together","titleCN":"让不同部分协同运转","definition":"the organizing of separate people or units so that their actions fit together","definitionCN":"把分开的人或单元组织起来，使其行动彼此吻合","example":"Coordination between the two labs shortened the trials by a year.","exampleCN":"两个实验室之间的协调让试验缩短了一年。","why":"Co- means together and ordinare means to set in order, so the word pictures separate rows being brought into one line.","whyCN":"co- 意为「共同」，ordinare 意为「排成次序」，因此这个词画的是把分开的几排并成一行。"},{"no":"02","title":"Smooth control of body movement","titleCN":"身体动作的顺畅配合","definition":"the ability to move different parts of the body together smoothly","definitionCN":"让身体各部位平稳配合运动的能力","example":"Hand-eye coordination improves with practice.","exampleCN":"手眼协调会随练习而改善。","why":"A body is many moving parts, and the same ordering power is needed to keep them in one rhythm.","whyCN":"身体是许多运动的部件，要让它们保持同一节拍，同样需要这种排定次序的能力。"},{"no":"03","title":"Matching of colours and clothes","titleCN":"色彩与衣着的搭配","definition":"the choosing of colours or clothes so that they look right together","definitionCN":"挑选彼此相配的颜色或衣着","example":"The coordination of grey and pale blue made the room restful.","exampleCN":"灰色与浅蓝的搭配让这个房间显得安静。","why":"Here the things being ordered are colours, and the harmony is the same fitting together on a smaller scale.","whyCN":"这里被排定的是颜色，和谐仍是同一种「彼此相合」，只是尺度更小。"},{"no":"04","title":"Joining equal elements in grammar","titleCN":"语法上并列同级成分","definition":"the linking of words or clauses of equal rank with conjunctions","definitionCN":"用连词把级别相同的词或从句连接起来","example":"Coordination with 'and' keeps both clauses at the same level.","exampleCN":"用表示并列的连词时，两个从句保持在同一层级。","why":"If two parts are equal, ordering them means placing them side by side rather than one under the other.","whyCN":"如果两个部分同等，排定它们就是把它们并排放，而不是让一个压在另一个下面。"},{"no":"05","title":"Bonding around a central atom","titleCN":"化学中围绕中心原子的配位","definition":"the binding of several atoms or groups around one central atom","definitionCN":"若干原子或基团围绕一个中心原子结合","example":"The coordination of four ligands gives the ion its shape.","exampleCN":"四个配体的配位决定了这个离子的形状。","why":"Chemistry borrowed the word for parts arranged around one centre, which is ordering in its most literal sense.","whyCN":"化学借来这个词指围绕一个中心排列的各个部分，这是「排次序」最字面的用法。"},{"no":"06","title":"Alignment of agencies in an emergency","titleCN":"紧急事件中各机构的联动","definition":"the arranging of separate agencies so that their response fits one timetable","definitionCN":"把分立的机构安排到同一张时间表上","example":"A single coordination desk handled the flood response.","exampleCN":"一张协调台统筹了洪水应对。","why":"When many hands act at once, someone must set the beat, or they cancel one another out.","whyCN":"许多双手同时动作时，必须有人定拍子，否则彼此抵消。"},{"no":"07","title":"Mutual support between units","titleCN":"各单位之间的相互配合关系","definition":"the relation in which separate units support one another's work","definitionCN":"各个分开的单元彼此支持对方工作的关系","example":"There is close coordination between the port and the railway.","exampleCN":"港口与铁路之间配合紧密。","why":"The noun can name the relation itself, not only the act of arranging it.","whyCN":"这个名词也能命名关系本身，而不只是安排的动作。"},{"no":"08","title":"Fitting schedules together","titleCN":"把日程排到不冲突","definition":"the arranging of timetables so that they do not clash","definitionCN":"安排时间表使其不相冲突","example":"Coordination of the two exam timetables avoided a clash.","exampleCN":"两张考试时间表经过协调，避免了撞期。","why":"Two rows of dates become one usable row, which is the original picture made practical.","whyCN":"两排日期并成一排可用的日期，这是最初画面落到实用处。"}],"etymology":{"intro":{"en":"Coordination comes from Latin coordinare, 'to arrange together', built on co- 'together' and ordinare 'to set in order' from ordo 'row'. English took it in the seventeenth century for the arranging of parts into one working whole.","cn":"coordination 来自拉丁 coordinare「一同安排」，由 co-「共同」与 ordinare「排定次序」构成，而 ordinare 出自 ordo「行列」。英语在十七世纪借入，指把各部分安排成一个运作整体。"},"items":[{"era":"LATIN ORDO","en":"Ordo meant a row, a line or an order, and it is the root of order, ordinal and ordinance.","cn":"ordo 意为行列、次序，是 order、ordinal 与 ordinance 的词根。"},{"era":"LATIN ORDINARE","en":"Ordinare meant to set in rows or to appoint, so the root already contains both arranging and assigning.","cn":"ordinare 意为排成行列或任命，这个词根已同时含「排列」与「指派」。"},{"era":"LATIN CO-","en":"Co- is the form of com- used before vowels, meaning 'together, with', and it supplies the jointness of the word.","cn":"co- 是 com- 在元音前的形式，意为「共同、一起」，提供这个词的「合」义。"},{"era":"LATIN COORDINARE","en":"Coordinare meant to arrange several things into one order, which is the exact sense English borrowed.","cn":"coordinare 意为把若干事物排进同一秩序，这正是英语借入的意思。"},{"era":"SEVENTEENTH CENTURY","en":"Coordination entered English in the seventeenth century, first for parts arranged into one order and soon after for bodily movement.","cn":"coordination 在十七世纪进入英语，先指排成一个秩序的各部分，不久也指身体动作。"},{"era":"LATER SPECIALISMS","en":"Grammar, chemistry and emergency management each borrowed the word in the nineteenth and twentieth centuries; those dates are approximate.","cn":"语法、化学与应急管理在十九、二十世纪各自借用了这个词；这些年代都是约数。"}]},"similar":{"note":{"en":"The first group shares the ordin- root or a near shape; the second group names other ways of working together.","cn":"第一组共享 ordin- 词根或形音相近；第二组是其他「一起做事」的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"coordinate","ipa":"/ˌkəʊˈɔːdɪneɪt/","tag":"same root","definition":"The verb, and also a noun for a position on a map or a matching garment.","definitionCN":"动词，也可作名词指地图上的坐标或成套衣饰。"},{"word":"coordinator","ipa":"/kəʊˈɔːdɪneɪtə/","tag":"same root","definition":"The person who does the arranging.","definitionCN":"负责安排的那个人。"},{"word":"order","ipa":"/ˈɔːdə/","tag":"same root, different sense","definition":"From the same Latin row, but it means sequence or a command rather than joint arrangement.","definitionCN":"同出那个表示行列的拉丁词，但指次序或命令，不是联合安排。"},{"word":"ordain","ipa":"/ɔːˈdeɪn/","tag":"same root, different sense","definition":"Also from ordinare, but it means to appoint solemnly, especially to the clergy.","definitionCN":"同样出自 ordinare，但指庄严任命，尤指授予神职。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cooperation","ipa":"/kəʊˌɒpəˈreɪʃn/","tag":"near meaning","definition":"Working together willingly; it stresses attitude rather than timetable.","definitionCN":"自愿一起工作，强调态度而不是时间表。"},{"word":"collaboration","ipa":"/kəˌlæbəˈreɪʃn/","tag":"near meaning","definition":"Working jointly on one piece of work, often with shared authorship.","definitionCN":"在一项工作上共同出力，常含共同署名之意。"},{"word":"synchronization","ipa":"/ˌsɪŋkrənaɪˈzeɪʃn/","tag":"near meaning","definition":"Making things happen at the same moment, a narrower mechanical idea.","definitionCN":"让事物在同一时刻发生，是更窄的机械概念。"},{"word":"alignment","ipa":"/əˈlaɪnmənt/","tag":"near meaning","definition":"Bringing aims or positions into line, often used of policy or strategy.","definitionCN":"让目标或立场对齐，常用于政策或战略。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin pieces, the real suffix and the real technical phrases.","cn":"正常联想使用真实的拉丁构件、真实的后缀与真实的专业说法。"},"normal":[{"en":"Co- is together and ordo is a row, so coordination is putting separate rows into one.","cn":"co- 是共同，ordo 是行列，coordination 就是把分开的几排并成一排。"},{"en":"The family runs coordinate, coordinator, coordinated and coordination.","cn":"同族词有 coordinate、coordinator、coordinated 与 coordinative。"},{"en":"Technical phrases mark it: hand-eye coordination, coordination number, coordination compound.","cn":"专业说法标出它的用法：手眼协调、配位数、配位化合物。"},{"en":"Where the parts are equal, ordering means placing them side by side.","cn":"当各部分同等，排定就意味着并排放置。"},{"en":"An emergency desk exists because many hands need one beat.","cn":"应急协调台之所以存在，是因为许多双手需要一个拍子。"}],"abstract":[{"en":"Picture four hands on four ropes, lifting one weight without a tilt.","cn":"想象四只手拉四根绳，抬起同一件重物而不倾斜。"},{"en":"Picture a conductor's baton that never touches an instrument.","cn":"想象一根从不碰乐器的指挥棒。"},{"en":"Picture two clocks set to the same second before a door opens.","cn":"想象两座钟在开门前被拨到同一秒。"}]},"examples":[{"en":"Coordination between the two hospitals freed a dozen beds.","cn":"两家医院之间的协调腾出了十几张床位。"},{"en":"The dance requires fine coordination of breath and step.","cn":"这支舞需要呼吸与步子的精细配合。"},{"en":"Poor coordination between the agencies delayed the rescue.","cn":"各机构之间协调不力，耽误了救援。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「co（共同）+ ordination（排次序）」——把各自的次序排到一起，就是协调","word":"coordination"},"root":"拉丁 co-「共同」+ ordinare「排定次序」（出自 ordo「行列」）→ coordinare「一同安排」→ 英语 coordination。","sensesIntro":{"en":"Eight senses all place separate parts into one order: agencies at a rescue, limbs in movement, colours in a room, clauses in a sentence, atoms around a centre, an emergency desk, two units in support and two timetables that must not clash.","cn":"八个义项都把分开的部分排进同一个次序：救援中的各机构、运动中的肢体、房间里的颜色、句子里的从句、围绕中心的原子、应急协调台、互相支持的两个单元，以及两张不能撞期的时间表。"},"semanticMap":{"core":{"en":"CORE IMAGE: four hands pull four ropes at one beat so the weight rises level.","cn":"核心意象：四只手按同一个拍子拉四根绳，重物平稳升起。"},"chain":["SEPARATE ROWS","ONE BEAT","THE BODY'S RHYTHM","EQUAL PARTS","AROUND A CENTRE","SHARED TIMETABLE"],"branches":[{"senses":"01 · 06","en":"MANY UNITS, ONE BEAT: agencies and laboratories are kept from cancelling one another.","cn":"多单元，一拍：机构与实验室被安排得不互相抵消。"},{"senses":"02 · 03","en":"THE SMALLER SCALES: limbs and colours are ordered by the same fitting together.","cn":"更小的尺度：肢体与颜色靠同一种「彼此相合」被排定。"},{"senses":"04","en":"EQUAL PARTS: grammar places equal clauses side by side.","cn":"同等部分：语法把同级的从句并排放置。"},{"senses":"05","en":"AROUND A CENTRE: chemistry orders groups around one atom.","cn":"围绕中心：化学把基团排在一个原子周围。"},{"senses":"07 · 08","en":"THE RELATION AND THE CLOCK: mutual support, and two timetables made into one.","cn":"关系与时钟：相互支持，以及两张时间表并成一张。"}]},"affixes":{"intro":{"en":"Coordination is a Latin verb of ordering with a joining prefix, and the ordering root reaches several common English words.","cn":"coordination 是一个带「共同」前缀的拉丁「排序」动词的名词，这个排序词根通向若干常用英语词。"},"latinIntro":{"en":"Latin ordo gives order, ordinal and ordinance; coordinare gives coordinate and coordinator.","cn":"拉丁 ordo 衍生 order（次序）、ordinal（序数词）与 ordinance（法令）；coordinare 衍生 coordinate 与 coordinator。"},"items":[{"word":"co-","structure":"Latin prefix, form of com-","meaning":"together, with","meaningCN":"共同；一起","example":"The prefix supplies the joining of separate parts.","exampleCN":"前缀提供各部分的联合。"},{"word":"ordo","structure":"Latin noun, third declension","meaning":"row, line, order","meaningCN":"行列；次序","example":"The root supplies the picture of rows.","exampleCN":"这个词根提供「行列」的画面。"},{"word":"ordinare","structure":"Latin verb, first conjugation","meaning":"to set in order, appoint","meaningCN":"排定次序；任命","example":"The verb turns the row into an act.","exampleCN":"动词把「行列」变成一个动作。"},{"word":"coordinare","structure":"co- plus ordinare","meaning":"to arrange together","meaningCN":"一同安排","example":"The compound is the direct source.","exampleCN":"这个复合词是直接来源。"},{"word":"coordination","structure":"coordinare plus -tio (action)","meaning":"the arranging of parts into one order","meaningCN":"协调；配合","example":"The action noun names the arranging.","exampleCN":"动作名词指这种安排。"},{"word":"coordinate","structure":"coordinare plus -atus","meaning":"to bring into one order; a position","meaningCN":"协调；坐标","example":"The verb is the working member of the family.","exampleCN":"动词是词族里干活的一员。"},{"word":"coordinator","structure":"coordinate plus -or (agent)","meaning":"one who arranges","meaningCN":"协调人","example":"The agent noun names the hand that sets the beat.","exampleCN":"施动名词点出定拍子的那只手。"},{"word":"order","structure":"ordo to English","meaning":"sequence; a command","meaningCN":"次序；命令","example":"The plain noun keeps the row at its simplest.","exampleCN":"朴素的这个名词把「行列」保留得最单纯。"},{"word":"ordinal","structure":"ordo plus -inal (suffix of position)","meaning":"a number showing position","meaningCN":"序数词","example":"The suffix turns a row into a rank.","exampleCN":"后缀把行列变成名次。"}],"latinEntries":[{"word":"ordo","structure":"ordo, ordinis (n., third declension)","meaning":"row, order","meaningCN":"行列；次序"},{"word":"ordinare","structure":"ordinare, ordinavi, ordinatum (verb, first conjugation)","meaning":"to set in order","meaningCN":"排定次序"},{"word":"coordinatio","structure":"coordinatio, coordinationis (n., third declension)","meaning":"a arranging together","meaningCN":"共同安排"}],"derivatives":[{"word":"coordinate","pos":"v./n.","zh":"协调；坐标"},{"word":"coordinator","pos":"n.","zh":"协调人"},{"word":"coordinated","pos":"adj.","zh":"协调一致的"},{"word":"ordination","pos":"n.","zh":"按手礼；任命"}]}},{"word":"strategic","ipa_uk":"/strəˈtiːdʒɪk/","ipa_us":"/strəˈtiːdʒɪk/","definition_zh":"战略的；着眼于全局长期的；关键的；有战略意义的","definition_en":"relating to long-term planning for an overall aim, or important for gaining an advantage","core_image":"棋盘上的一只手没有动任何一枚子，而是先把视线从一角移到整盘","scene":"一家小厂把三年的钱都投在一条别人还没做的产线上，短期利润下降，却占住了未来的位置。The board called the investment strategic rather than merely profitable.","sceneCN":"这里 strategic 指着眼于长期全局、为取得优势而作的（第 1 个义项：关乎长期全局谋划的）；句意：董事会称这笔投资是战略性的一步，而不只是能赚钱。图中可辨识物件：棋盘、产线布局图、三年预算、竞品清单。","pos":[{"tag":"adj.","zh":"战略的；全局长期的；关键的；有战略意义的"}],"collocations":[{"phrase":"strategic plan","zh":"战略规划"},{"phrase":"strategic position","zh":"战略位置"},{"phrase":"strategic decision","zh":"战略决策"},{"phrase":"strategic resource","zh":"战略资源"},{"phrase":"strategic partnership","zh":"战略伙伴关系"},{"phrase":"strategic thinking","zh":"战略思维"}],"forms":[{"label":"原级","form":"strategic"},{"label":"比较级","form":"more strategic"},{"label":"最高级","form":"most strategic"},{"label":"副词","form":"strategically"},{"label":"名词（战略）","form":"strategy"},{"label":"名词（战略家）","form":"strategist"}],"derivatives":[{"word":"strategy","pos":"n.","zh":"战略；策略"},{"word":"strategist","pos":"n.","zh":"战略家"},{"word":"strategically","pos":"adv.","zh":"在战略上"},{"word":"stratagem","pos":"n.","zh":"计谋；策略手段"}],"senses":[{"no":"01","title":"Of long-term overall aims","titleCN":"关乎长期全局目标的","definition":"relating to the overall aim that guides many smaller decisions over time","definitionCN":"与在长时间里统领许多较小决定的总体目标有关","example":"A strategic decision is one that changes the next five years.","exampleCN":"战略决策就是会改变未来五年的那种决定。","why":"Greek strategia named the general's art, which is planning a whole campaign rather than winning one clash.","whyCN":"希腊 strategia 指将军的技艺，即筹划整场战事，而不是赢下一次交锋。"},{"no":"02","title":"Of military strategy","titleCN":"与军事战略有关的","definition":"relating to the planning of a whole war or campaign","definitionCN":"与整场战争或战役的筹划有关","example":"The ridge is valuable for strategic reasons, not for its soil.","exampleCN":"那道山脊的价值在战略上，而不在土质。","why":"The word was military before it was anything else, and that sense remains the pattern for all the others.","whyCN":"这个词最早只用于军事，其他用法都以这一义为范本。"},{"no":"03","title":"Planned to gain an advantage","titleCN":"为取得优势而精心安排的","definition":"carefully arranged to produce an advantage rather than an immediate result","definitionCN":"精心安排以取得优势，而不是为了眼前结果","example":"Her strategic silence made the other side speak first.","exampleCN":"她那次有策略的沉默让对方先开了口。","why":"A general wins by placing pieces well, and the same idea covers a well-placed silence in a negotiation.","whyCN":"将军靠布好棋子取胜，同样的道理也涵盖谈判中布得恰到好处的一次沉默。"},{"no":"04","title":"Vital in position","titleCN":"位置上有战略价值的","definition":"important because of where something is, especially for transport or defence","definitionCN":"因所处位置而在运输或防务上重要的","example":"The strait is strategic for every ship that carries grain.","exampleCN":"这道海峡对所有运粮船都具有战略意义。","why":"Some ground matters because of what it overlooks, which is geography turned into advantage.","whyCN":"有些地面之所以重要，是因为它俯瞰着什么，这是把地理变成优势。"},{"no":"05","title":"Of business strategy","titleCN":"与商业战略有关的","definition":"relating to a firm's long-term choices about markets and resources","definitionCN":"与企业对市场和资源的长期选择有关","example":"The firm hired a strategic adviser before entering the region.","exampleCN":"这家公司在进入该地区前请了一位战略顾问。","why":"A company fights for customers the way an army fights for ground, so it borrowed the general's word.","whyCN":"公司争夺客户如同军队争夺地盘，于是借用了将军的词。"},{"no":"06","title":"Essential to a goal","titleCN":"对某个目标不可或缺的","definition":"so important to an aim that losing it would change the outcome","definitionCN":"对某个目标重要到失去它就会改变结果","example":"Fresh water became a strategic resource in the dry province.","exampleCN":"在干旱的省份，淡水成了战略资源。","why":"What a campaign cannot do without becomes strategic, even when it is only water.","whyCN":"一场战事离不开的东西就成了战略性的，即便那只是水。"},{"no":"07","title":"Thinking about position in a game","titleCN":"棋局中着眼于局面而非眼前得失","definition":"in games, thinking about long-term position rather than the next capture","definitionCN":"在棋类中考虑长期局面而不是下一步吃子","example":"A strategic player gives up a pawn to control the centre.","exampleCN":"有战略眼光的棋手会弃掉一个兵去控制中心。","why":"The board is the clearest place to see that a small loss can buy a larger position.","whyCN":"棋盘最能看清：小的损失可以换来更大的局面。"},{"no":"08","title":"Deliberate and calculated","titleCN":"有意为之、经过盘算的","definition":"done on purpose after calculation, often to create a particular impression","definitionCN":"经盘算后有意做出，常为造成某种印象","example":"The delay was strategic: it let the price fall before the offer.","exampleCN":"那次拖延是有意为之：让价格在报价前先跌下来。","why":"When even a pause is placed like a piece on a board, the word has moved from war to timing.","whyCN":"当连一次停顿都像棋子一样被摆放，这个词就从战争走到了时机。"}],"etymology":{"intro":{"en":"Strategic comes from Greek stratēgikos, 'of a general', from stratēgos 'general', built on stratos 'army' and agein 'to lead'. English borrowed it through French in the nineteenth century.","cn":"strategic 来自希腊 stratēgikos「将军的」，而 stratēgos「将军」由 stratos「军队」与 agein「引领」构成。英语在十九世纪经法语借入。"},"items":[{"era":"GREEK STRATOS","en":"Stratos meant 'army, host'. It is generally thought to come from a root meaning 'to spread out', but that ancestry is a reconstruction.","cn":"stratos 意为「军队、队伍」。一般认为它出自一个意为「铺展开」的词根，但这一上源属重构形式。"},{"era":"GREEK AGEIN","en":"Agein meant 'to lead, drive', and it is the second half of stratēgos, the one who leads the host.","cn":"agein 意为「引领、驱赶」，它是 stratēgos 的后半，指引领队伍的人。"},{"era":"GREEK STRATEGOS","en":"Stratēgos was the elected general of an Athenian tribe, a commander with wide powers.","cn":"stratēgos 是雅典部族选出的将军，一位权力很广的指挥官。"},{"era":"GREEK STRATEGIA","en":"Strategia meant generalship or the art of command, from which the modern noun strategy descends.","cn":"strategia 指将军之职或指挥之术，现代名词 strategy 由此而来。"},{"era":"FRENCH AND ENGLISH","en":"French stratégique and stratégie brought the family into English in the late eighteenth and early nineteenth centuries; the dates are approximate.","cn":"法语 stratégique 与 stratégie 在十八世纪末、十九世纪初把这组词带入英语；年代为约数。"},{"era":"WIDENING","en":"Business, games and everyday timing borrowed the adjective in the twentieth century, keeping the picture of pieces placed for advantage.","cn":"商业、棋类与日常时机在二十世纪借用了这个形容词，保留了「为取优势而布子」的画面。"}]},"similar":{"note":{"en":"The first group shares the Greek general root or a near shape; the second group names words about aims and advantage.","cn":"第一组共享希腊语「将军」词根或形音相近；第二组是与目标和优势有关的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"strategy","ipa":"/ˈstrætədʒi/","tag":"same root","definition":"The noun for the whole art or plan, where strategic is the adjective.","definitionCN":"指整套谋划或计划的名词，strategic 是其形容词。"},{"word":"strategist","ipa":"/ˈstrætədʒɪst/","tag":"same root","definition":"The person who makes such plans.","definitionCN":"制定这类计划的人。"},{"word":"stratagem","ipa":"/ˈstrætədʒəm/","tag":"same root","definition":"A trick or device, from the Greek word for a general's move; narrower and often sly.","definitionCN":"指计谋手段，出自表示将军一招的希腊词，范围更窄且常含狡黠。"},{"word":"stratosphere","ipa":"/ˈstrætəsfɪə/","tag":"different root","definition":"From Latin stratum 'layer' plus sphere; the shared opening is accidental and has nothing to do with armies.","definitionCN":"由拉丁 stratum「层」加表示「球层」的希腊词构成；相同的开头只是巧合，与军队无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"tactical","ipa":"/tækˈtɪkəl/","tag":"near meaning","definition":"About winning the next engagement rather than the whole campaign.","definitionCN":"关于赢下眼前一仗，而不是整场战事。"},{"word":"long-term","ipa":"/ˌlɒŋ ˈtɜːm/","tag":"near meaning","definition":"A plain adjective for what reaches far ahead, without the idea of advantage.","definitionCN":"朴素的「长期」形容词，不含取得优势之意。"},{"word":"calculated","ipa":"/ˈkælkjuleɪtɪd/","tag":"near meaning","definition":"Done on purpose after weighing the effect, close to the adjective's last sense.","definitionCN":"权衡效果后有意为之，接近其最后一个义项。"},{"word":"key","ipa":"/keɪ/","tag":"near meaning","definition":"Essential to an outcome, without the military picture.","definitionCN":"对结果不可或缺，但不含军事画面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the Greek pieces and the real word family.","cn":"正常联想使用希腊语构件与真实的同族词。"},"normal":[{"en":"Stratos is army and agein is to lead, so a strategist leads the host.","cn":"stratos 是军队，agein 是引领，因此战略家是引领队伍的人。"},{"en":"The family runs strategy, strategist, strategic and strategically.","cn":"同族词有 strategy、strategist、strategize 与 strategically。"},{"en":"Business phrases mark it: strategic plan, strategic position, strategic resource.","cn":"商业说法标出它的用法：战略规划、战略位置、战略资源。"},{"en":"A strategic move is one that changes the shape of the board, not just the count.","cn":"战略一步改变的是棋盘形状，而不只是子数。"},{"en":"The word still carries the general's habit: place pieces before the fighting starts.","cn":"这个词仍带着将军的习惯：在开打之前先布好子。"}],"abstract":[{"en":"Picture a hand hovering over a board without touching a piece.","cn":"想象一只手在棋盘上方悬着，却不碰任何棋子。"},{"en":"Picture a road drawn on a map before any vehicle uses it.","cn":"想象一条在尚无车辆使用时已画在地图上的路。"},{"en":"Picture a pause in a conversation that is timed like a move.","cn":"想象对话中的一次停顿，被安排得像一步棋。"}]},"examples":[{"en":"The company made a strategic retreat from the low-price market.","cn":"这家公司从低价市场做了战略性撤退。"},{"en":"Control of the harbour was strategic for the whole region.","cn":"控制这座港口对整个地区具有战略意义。"},{"en":"She asked a strategic question and let the room answer it.","cn":"她提了一个有策略的问题，让在场的人自己回答。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「strategy（战略）+ ic（……的）」——像将军布阵那样看全局，就是战略的","word":"strategic"},"root":"希腊 stratos「军队」+ agein「引领」→ stratēgos「将军」→ stratēgia「将略」→ 法语 stratégique → 英语 strategic。","sensesIntro":{"en":"Eight senses follow one general's habit: plan the whole campaign, fight the war, place a move for advantage, hold vital ground, compete for markets, secure what a goal cannot do without, play for position and time a pause like a piece.","cn":"八个义项都跟随将军的习惯：筹划整场战事、打整场战争、为取优势而布一着、占据要地、争夺市场、护住目标离不开的东西、为局面而下棋，以及把一次停顿像棋子那样安排。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand over a board that moves the eye across the whole position before moving a piece.","cn":"核心意象：一只手停在棋盘上方，先把视线扫过整个局面，才动一子。"},"chain":["THE WHOLE BOARD","THE ARMY","THE PLACED MOVE","VITAL GROUND","THE MARKET","THE TIMED PAUSE"],"branches":[{"senses":"01 · 02","en":"THE WHOLE CAMPAIGN: the general's art, first in war and then in any long aim.","cn":"整场战事：将军的技艺，先用于战争，再用于任何长期目标。"},{"senses":"03 · 08","en":"THE PLACED MOVE: a calculated advantage, even when the move is only silence.","cn":"布下的一着：经盘算的优势，即便这一着只是沉默。"},{"senses":"04 · 06","en":"WHAT CANNOT BE LOST: ground that overlooks, and water a campaign cannot do without.","cn":"不可失去之物：能俯瞰的地面，以及战事离不开的水。"},{"senses":"05","en":"THE MARKET: firms fight for customers with the general's word.","cn":"市场：企业用将军的词争夺客户。"},{"senses":"07","en":"THE BOARD ITSELF: the clearest place to see a small loss buy a larger position.","cn":"棋盘本身：最能看清小损失如何换来大局面。"}]},"affixes":{"intro":{"en":"Strategic is a Greek noun of command turned into an English adjective, and the same root supports strategy, strategist and stratagem.","cn":"strategic 是由希腊语「指挥」名词转成的英语形容词，同一词根还支撑 strategy、strategist 与 stratagem。"},"latinIntro":{"en":"Greek stratos gives stratagem and stratocracy; agein gives stratēgos and, through it, strategy.","cn":"希腊 stratos 衍生 stratagem（计谋）与 stratocracy（军政）；agein 构成 stratēgos，并经由它给出 strategy。"},"items":[{"word":"stratos","structure":"Greek noun","meaning":"army, host","meaningCN":"军队；队伍","example":"The root supplies the host that is led.","exampleCN":"这个词根提供被引领的队伍。"},{"word":"agein","structure":"Greek verb","meaning":"to lead, drive","meaningCN":"引领；驱赶","example":"The root supplies the leading.","exampleCN":"这个词根提供「引领」。"},{"word":"stratēgos","structure":"stratos plus agein","meaning":"general, commander","meaningCN":"将军；统帅","example":"The compound names the one who leads the host.","exampleCN":"这个复合词命名引领队伍的人。"},{"word":"strategia","structure":"stratēgos plus -ia (abstract noun)","meaning":"generalship, command","meaningCN":"将略；指挥术","example":"The abstract noun becomes our strategy.","exampleCN":"这个抽象名词后来成为英语中表示战略的词。"},{"word":"strategic","structure":"stratēgikos to English through French","meaning":"of a general or of strategy","meaningCN":"战略的","example":"The adjective describes the general's kind of thinking.","exampleCN":"形容词描述将军那一类思考。"},{"word":"strategy","structure":"strategia through French and Latin","meaning":"the art of planning a campaign","meaningCN":"战略；策略","example":"The noun names the art itself.","exampleCN":"名词命名这门技艺本身。"},{"word":"strategist","structure":"strategy plus -ist (one who practises)","meaning":"one skilled in strategy","meaningCN":"战略家","example":"The suffix marks the practitioner.","exampleCN":"后缀标出实践者。"},{"word":"stratagem","structure":"stratēgēma, a general's device","meaning":"a trick or plan","meaningCN":"计谋；策略手段","example":"The word narrowed to a single clever move.","exampleCN":"这个词收窄为巧妙的一着。"},{"word":"strategically","structure":"strategic plus -ly","meaning":"in a strategic way","meaningCN":"在战略上","example":"The adverb marks the point of view.","exampleCN":"副词标出着眼的角度。"}],"latinEntries":[{"word":"stratos","structure":"stratos, stratou (n., second declension, Greek)","meaning":"army, host","meaningCN":"军队；队伍"},{"word":"stratēgos","structure":"stratēgos, stratēgou (n., second declension, Greek)","meaning":"general","meaningCN":"将军"},{"word":"strategia","structure":"strategia, strategias (n., first declension, Greek)","meaning":"generalship","meaningCN":"将略；指挥术"}],"derivatives":[{"word":"strategy","pos":"n.","zh":"战略；策略"},{"word":"strategist","pos":"n.","zh":"战略家"},{"word":"strategically","pos":"adv.","zh":"在战略上"},{"word":"stratagem","pos":"n.","zh":"计谋"}]}},{"word":"strategic planning","ipa_uk":"/strəˈtiːdʒɪk ˈplænɪŋ/","ipa_us":"/strəˈtiːdʒɪk ˈplænɪŋ/","definition_zh":"战略规划；长期总体谋划；制定长期目标与路径的过程","definition_en":"the process of setting long-term goals and deciding how to reach them","core_image":"一张铺开的大纸，上面画着三年的路线，起点与终点之间标着几个必经的关口","scene":"一家医院在年初把未来三年的扩建、招聘与预算一次排定，之后再按季度调整细节。Strategic planning saved the hospital from building wards it could not staff.","sceneCN":"这里 strategic planning 指先定长期目标再排路径的过程（第 1 个义项：制定长期目标与路径）；句意：战略规划让这家医院免于建起无人可值班的病区。图中可辨识物件：三年路线图、预算册、招聘计划、季度表。","pos":[{"tag":"n.","zh":"战略规划；长期总体谋划；制定长期目标与路径的工作"}],"collocations":[{"phrase":"strategic planning process","zh":"战略规划流程"},{"phrase":"corporate strategic planning","zh":"企业战略规划"},{"phrase":"strategic planning committee","zh":"战略规划委员会"},{"phrase":"strategic planning cycle","zh":"战略规划周期"},{"phrase":"strategic planning document","zh":"战略规划文件"}],"forms":[{"label":"单数（指过程）","form":"strategic planning"},{"label":"复数（指多家机构的规划）","form":"strategic plannings"},{"label":"作定语（形式不变）","form":"strategic planning committee"},{"label":"相关动词","form":"plan"},{"label":"相关名词（规划者）","form":"planner"},{"label":"相关形容词（战略的）","form":"strategic"}],"derivatives":[{"word":"strategic","pos":"adj.","zh":"战略的；全局长期的"},{"word":"planning","pos":"n.","zh":"规划；计划工作"},{"word":"plan","pos":"v./n.","zh":"计划；方案"},{"word":"planner","pos":"n.","zh":"规划者；规划师"},{"word":"strategy","pos":"n.","zh":"战略"}],"senses":[{"no":"01","title":"The process of setting long-term goals","titleCN":"制定长期目标的过程","definition":"the work of deciding what an organization should achieve over several years and how to get there","definitionCN":"决定一个组织在数年内应达成什么、以及如何达成的过程","example":"Strategic planning began with a single question: what must this city look like in ten years?","exampleCN":"战略规划从一个问题开始：十年后这座城市该是什么样子？","why":"Strategic comes from the general's art and planning from a flat drawn map, so the phrase is a campaign laid out on paper.","whyCN":"strategic 出自将军的技艺，planning 出自画在平面上的图，因此这个短语就是画在纸上的整场战事。"},{"no":"02","title":"The corporate planning cycle","titleCN":"企业里的规划周期","definition":"the regular yearly or multi-year exercise in which a firm sets its direction","definitionCN":"企业按年或跨年定期确定方向的那套工作","example":"The firm's strategic planning runs from September to December every year.","exampleCN":"这家公司的战略规划每年从九月做到十二月。","why":"A firm repeats the exercise on a calendar, and repetition turns an art into a cycle.","whyCN":"企业按日历重复这项工作，重复就把一门技艺变成了周期。"},{"no":"03","title":"Planning of a military campaign","titleCN":"对一场战事的筹划","definition":"the arranging of a whole campaign before any force is committed","definitionCN":"在投入兵力之前对整场战役的布置","example":"Strategic planning had already fixed the supply line before the first unit moved.","exampleCN":"在第一支部队开动之前，战略规划就已定好了补给线。","why":"This is the phrase's oldest home: the general draws the campaign before the columns march.","whyCN":"这是这个短语最古老的家：将军在队伍开拔前就画好了战事。"},{"no":"04","title":"Long-range public planning","titleCN":"政府的长期规划","definition":"the long-horizon planning of a government or public body","definitionCN":"政府或公共机构对长远未来的规划","example":"Strategic planning for the water system looked thirty years ahead.","exampleCN":"供水系统的战略规划向前看了三十年。","why":"Public bodies borrow the phrase when a single budget year cannot answer the question.","whyCN":"当一个预算年度回答不了问题时，公共机构就借用这个短语。"},{"no":"05","title":"The office that does the planning","titleCN":"负责规划的部门或职能","definition":"the department or function whose job is to prepare the long-term plan","definitionCN":"负责编制长期计划的部门或职能","example":"Strategic planning sits two doors down from the finance office.","exampleCN":"战略规划部门就在财务办公室过去两间。","why":"Once the exercise is permanent, it needs a room and a staff, and the phrase names them.","whyCN":"当这项工作常设下来，就需要一间办公室和一套人马，这个短语也用来指他们。"},{"no":"06","title":"The plan document itself","titleCN":"规划文件本身","definition":"the written plan produced by the process, with goals, stages and measures","definitionCN":"由这一过程产出的书面计划，含目标、阶段与衡量指标","example":"The board asked for a shorter strategic planning document.","exampleCN":"董事会要求把战略规划文件写短一些。","why":"A drawing on paper can be handed round, and the phrase shifts from the drawing to the sheet.","whyCN":"画在纸上的图可以传阅，于是这个短语从「画」转到「那张纸」。"},{"no":"07","title":"The academic field","titleCN":"作为学科的战略规划","definition":"the study and teaching of how long-term plans are made and judged","definitionCN":"研究并教授长期计划如何制定与评判的学问","example":"She teaches strategic planning to students who have never run a budget.","exampleCN":"她给从未管过预算的学生讲授战略规划。","why":"Practice written into a syllabus becomes a subject, and the phrase enters the classroom.","whyCN":"做法写进教学大纲就成了学科，这个短语便进了课堂。"},{"no":"08","title":"Long-horizon community planning","titleCN":"社区或城市的长远规划","definition":"the long-term planning of a town, region or community's growth","definitionCN":"对城镇、区域或社区发展的长期规划","example":"Strategic planning for the district kept the new school site open for ten years.","exampleCN":"这个学区的战略规划把新校址留了十年。","why":"A community grows slower than a firm, so its planning must look further ahead.","whyCN":"社区比企业成长得慢，因此它的规划要看得更远。"}],"etymology":{"intro":{"en":"The phrase joins strategic, from Greek stratos 'army' and agein 'to lead', with planning, from Latin planum 'flat surface'. It became a fixed term of management and government in the twentieth century.","cn":"这个短语把 strategic 与 planning 接在一起：前者出自希腊 stratos「军队」与 agein「引领」，后者出自拉丁 planum「平面」。它在二十世纪成为管理与政府的固定术语。"},"items":[{"era":"GREEK STRATOS","en":"Stratos 'army' supplies the military half of the phrase; its deeper root is a reconstruction.","cn":"stratos「军队」提供短语中军事的那一半；其更早词根属重构形式。"},{"era":"GREEK AGEIN","en":"Agein 'to lead' completes stratēgos, the general whose art gives us strategic.","cn":"agein「引领」补成 stratēgos，即那位将军，其技艺给出 strategic。"},{"era":"LATIN PLANUM","en":"Planum meant a flat surface, and a plan was first a drawing of a building seen from above.","cn":"planum 意为平面，而 plan 最初指从上方看建筑的图样。"},{"era":"ENGLISH PLAN","en":"Plan entered English in the sixteenth century as a ground plan or map, and only later meant a scheme of action.","cn":"plan 在十六世纪进入英语，指平面图或地图，后来才指行动方案。"},{"era":"PLANNING AS A NOUN","en":"Planning became a working noun in the nineteenth century, when industry needed schedules made in advance.","cn":"planning 在十九世纪成为常用的名词，当时工业需要提前排定日程。"},{"era":"FIXED PHRASE","en":"The two words were joined as a fixed term in the twentieth century; the exact first date is approximate.","cn":"两个词在二十世纪合成固定术语；确切的最早年代为约数。"}]},"similar":{"note":{"en":"The first group shares one word of the phrase or a near shape; the second group names neighbouring kinds of forward work.","cn":"第一组共享短语中的一个词或形音相近；第二组是相邻的「向前安排」工作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"strategic","ipa":"/strəˈtiːdʒɪk/","tag":"shares the first word","definition":"The adjective alone can describe any long-term or advantage-seeking choice.","definitionCN":"这个形容词单独使用可描述任何长期或求取优势的选择。"},{"word":"planning","ipa":"/ˈplænɪŋ/","tag":"shares the second word","definition":"Planning alone covers next week's rota as well as the next decade.","definitionCN":"单说 planning 既涵盖下周的班表，也涵盖未来十年。"},{"word":"strategy","ipa":"/ˈstrætədʒi/","tag":"related root","definition":"The plan or art itself, which strategic planning is meant to produce.","definitionCN":"指计划或谋划本身，战略规划正是要产出它。"},{"word":"master plan","ipa":"/ˈmɑːstə plæn/","tag":"near shape, one document","definition":"A single overall plan, often for a site; it names the paper, not the process.","definitionCN":"指一份总体方案，常用于地块；命名的是文件，不是过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"business planning","ipa":"/ˈbɪznəs ˈplænɪŋ/","tag":"near meaning","definition":"Shorter-range planning of sales, costs and staffing.","definitionCN":"对销售、成本与人手的较短程规划。"},{"word":"forecasting","ipa":"/ˈfɔːkɑːstɪŋ/","tag":"near meaning","definition":"Estimating what will happen rather than deciding what to do.","definitionCN":"估计将会发生什么，而不是决定要做什么。"},{"word":"policy planning","ipa":"/ˈpɒləsi ˈplænɪŋ/","tag":"near meaning","definition":"The same long horizon inside government, usually with less numeric targets.","definitionCN":"政府内部同样的长远谋划，通常数字指标更少。"},{"word":"vision setting","ipa":"/ˈvɪʒn ˈsetɪŋ/","tag":"near meaning","definition":"Agreeing on the desired future before any route is chosen.","definitionCN":"在选定路线之前先就想要的未来达成一致。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the two real roots and the real management phrases.","cn":"正常联想使用两个真实词根与真实的管理说法。"},"normal":[{"en":"Strategic is the general's art, planning is a flat map, so the phrase is a campaign on paper.","cn":"strategic 是将军的技艺，planning 是平面地图，因此这个短语是纸上的战事。"},{"en":"The family runs strategy, strategic, plan, planner and planning.","cn":"同族词有 strategy、strategic、plan、planner 与 planning。"},{"en":"Management phrases mark it: strategic planning cycle, strategic planning committee.","cn":"管理说法标出它的用法：战略规划周期、战略规划委员会。"},{"en":"A plan on paper can be handed round, which is how the phrase came to name a document.","cn":"纸上的计划可以传阅，这个短语因此也能指文件。"},{"en":"Every cycle repeats the same three moves: aim, route, measure.","cn":"每个周期重复同样三步：定目标、定路线、定衡量。"}],"abstract":[{"en":"Picture a long sheet where the start and the end are fixed and the gates between are numbered.","cn":"想象一张长纸，起点与终点已定，中间的关口都被编了号。"},{"en":"Picture a map drawn before a single traveller sets out.","cn":"想象在尚无旅人出发时就画好的地图。"},{"en":"Picture a hand that moves a marker one gate forward each quarter.","cn":"想象一只手每季度把标记往前挪一个关口。"}]},"examples":[{"en":"Strategic planning for the group now covers five countries.","cn":"集团的战略规划现在覆盖五个国家。"},{"en":"Without strategic planning, each department bought its own software.","cn":"没有战略规划时，每个部门各买各的软件。"},{"en":"The council published its strategic planning document in June.","cn":"市议会在六月公布了战略规划文件。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「strategic（战略的）+ planning（规划）」——先画全局再排路径，就是战略规划","word":"strategic planning"},"root":"strategic 出自希腊 stratos「军队」+ agein「引领」（经 stratēgos「将军」）；planning 出自拉丁 planum「平面」经法语 plan；两词在二十世纪合成固定术语。","sensesIntro":{"en":"Eight senses keep the phrase on paper and ahead of time: the process, the yearly cycle, a campaign, a government's long view, the office, the document, the classroom and a town's growth.","cn":"八个义项都把这个短语留在纸上、留在时间前方：制定过程、年度周期、一场战事、政府的远望、那个部门、那份文件、课堂，以及一座城镇的成长。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long sheet with a fixed start, a fixed end and numbered gates between.","cn":"核心意象：一张长纸，起点与终点固定，中间是编了号的关口。"},"chain":["THE LONG SHEET","THE YEARLY CYCLE","THE CAMPAIGN","THE PUBLIC HORIZON","THE OFFICE","THE DOCUMENT"],"branches":[{"senses":"01 · 07","en":"THE ART BECOMES A SUBJECT: the process, and the classroom that teaches it.","cn":"技艺变成学科：制定过程，以及教授它的课堂。"},{"senses":"02 · 05","en":"THE CYCLE AND THE ROOM: a yearly exercise needs an office to run it.","cn":"周期与房间：年度工作需要一个部门来运转。"},{"senses":"03","en":"THE CAMPAIGN: the oldest home, where supply lines are fixed before troops move.","cn":"战事：最古老的家，在部队开动前就定好补给线。"},{"senses":"04 · 08","en":"THE PUBLIC HORIZON: governments and towns must look past one budget year.","cn":"公共的远方：政府与城镇必须看过一个预算年度之外。"},{"senses":"06","en":"THE SHEET: the plan on paper can be handed round and argued over.","cn":"那张纸：纸上的计划可以传阅、可以争论。"}]},"affixes":{"intro":{"en":"The phrase is two Latin- and Greek-rooted words, each with its own history, and both halves still build English families.","cn":"这个短语由两个分别来自拉丁与希腊词根的词构成，各有一段历史，两半至今都还构成英语词族。"},"latinIntro":{"en":"Greek stratos and agein give strategic and strategy; Latin planum gives plan, plane and planning.","cn":"希腊 stratos 与 agein 给出 strategic 与 strategy；拉丁 planum 给出 plan、plane 与 planning。"},"items":[{"word":"stratos","structure":"Greek noun","meaning":"army","meaningCN":"军队","example":"The first half begins with the host.","exampleCN":"前半从「队伍」开始。"},{"word":"agein","structure":"Greek verb","meaning":"to lead","meaningCN":"引领","example":"The first half ends with leading.","exampleCN":"前半以「引领」收束。"},{"word":"strategic","structure":"stratēgikos to English","meaning":"of a general or of strategy","meaningCN":"战略的","example":"The adjective supplies the long view.","exampleCN":"形容词提供长远的眼光。"},{"word":"planum","structure":"Latin noun","meaning":"flat surface","meaningCN":"平面","example":"The second half begins with a flat sheet.","exampleCN":"后半从一张平面开始。"},{"word":"plan","structure":"planum through French","meaning":"a drawing; a scheme","meaningCN":"图纸；方案","example":"The noun moved from paper to intention.","exampleCN":"这个名词从纸面移到意图。"},{"word":"planning","structure":"plan plus -ing (action noun)","meaning":"the making of plans","meaningCN":"规划；计划工作","example":"The ending turns the scheme into an ongoing exercise.","exampleCN":"词尾把方案变成持续的工作。"},{"word":"planner","structure":"plan plus -er (agent)","meaning":"one who makes plans","meaningCN":"规划者","example":"The agent noun names the hand at the sheet.","exampleCN":"施动名词点出伏在纸上的那只手。"},{"word":"strategy","structure":"strategia through French","meaning":"the art of the long aim","meaningCN":"战略","example":"The sister noun names what the planning serves.","exampleCN":"姊妹名词命名规划所服务的东西。"}],"latinEntries":[{"word":"stratos","structure":"stratos, stratou (n., second declension, Greek)","meaning":"army","meaningCN":"军队"},{"word":"planum","structure":"planum, plani (n., second declension)","meaning":"flat surface","meaningCN":"平面"},{"word":"strategia","structure":"strategia, strategias (n., first declension, Greek)","meaning":"generalship","meaningCN":"将略"}],"derivatives":[{"word":"strategic","pos":"adj.","zh":"战略的"},{"word":"planning","pos":"n.","zh":"规划"},{"word":"planner","pos":"n.","zh":"规划者"},{"word":"strategy","pos":"n.","zh":"战略"}]}},{"word":"mission","ipa_uk":"/ˈmɪʃn/","ipa_us":"/ˈmɪʃn/","definition_zh":"使命；任务；（派往国外的）代表团；传教工作；飞行或军事任务","definition_en":"a task that a person or group is sent to carry out, or the purpose an organization sets for itself","core_image":"一个人把封好的信交到另一个人手里，那人转身就上路","scene":"山里的诊所缺药，一支小队带着箱子走了两天，把药送到村口就返回。The team's mission was to reach the village before the rains.","sceneCN":"这里 mission 指被派出去要完成的一项具体任务（第 1 个义项：受派执行的任务）；句意：这支小队的任务是赶在雨季前抵达那个村子。图中可辨识物件：药箱、山路、封好的指令、雨云。","pos":[{"tag":"n.","zh":"使命；任务；代表团；传教；飞行任务"}],"collocations":[{"phrase":"mission statement","zh":"使命宣言"},{"phrase":"space mission","zh":"太空飞行任务"},{"phrase":"diplomatic mission","zh":"外交代表团"},{"phrase":"rescue mission","zh":"救援任务"},{"phrase":"on a mission","zh":"执行任务中"},{"phrase":"mission control","zh":"任务控制中心"}],"forms":[{"label":"单数","form":"mission"},{"label":"复数","form":"missions"},{"label":"动词（派遣）","form":"mission"},{"label":"施动者名词（传教士）","form":"missionary"},{"label":"形容词（传教的）","form":"missionary"},{"label":"相关动词（发送）","form":"send"}],"derivatives":[{"word":"missionary","pos":"n./adj.","zh":"传教士；传教的"},{"word":"mission statement","pos":"n.","zh":"使命宣言"},{"word":"mission control","pos":"n.","zh":"任务控制中心"},{"word":"commission","pos":"n./v.","zh":"委员会；委托"},{"word":"dismiss","pos":"v.","zh":"解散；解雇"}],"senses":[{"no":"01","title":"An organization's declared purpose","titleCN":"一个组织公开宣告的宗旨","definition":"the purpose that an organization states as its reason for existing","definitionCN":"一个组织声明为其存在理由的宗旨","example":"The mission on the clinic wall is one sentence long.","exampleCN":"诊所墙上的宗旨只有一句话。","why":"A body that is sent must know what it was sent for, so the word came to mean a declared purpose.","whyCN":"被派出去的团体必须知道自己为何被派，这个词于是也指公开宣告的宗旨。"},{"no":"02","title":"A journey with a set purpose","titleCN":"带有明确目的的一次出行","definition":"a journey or trip undertaken to carry out a particular task","definitionCN":"为完成某项特定任务而进行的行程","example":"The supply mission took two days over the pass.","exampleCN":"那次补给任务翻过山口用了两天。","why":"The oldest sense is a sending: someone is dispatched, and the going is the task.","whyCN":"最古老的意思是「被派出」：有人被派遣出去，走这一趟就是任务。"},{"no":"03","title":"A group sent abroad","titleCN":"派往国外的代表团","definition":"a group of officials sent to another country to represent their government","definitionCN":"被派往他国代表本国政府的官员团体","example":"The trade mission met three buyers in one week.","exampleCN":"贸易代表团一周内见了三位买家。","why":"When the sending is diplomatic, the word names the people who were sent rather than the errand.","whyCN":"当派遣是外交性质时，这个词指被派出去的人，而不是那件差事。"},{"no":"04","title":"Religious work or a station","titleCN":"传教工作或传教站","definition":"the work of spreading a faith, or the settlement where that work is based","definitionCN":"传播信仰的工作，或这项工作所在的驻地","example":"The mission ran a school and a small hospital.","exampleCN":"那个传教站办了一所学校和一间小医院。","why":"Missionaries were sent, so their posting took the name of the sending.","whyCN":"传教士是被派出去的，因此他们的驻地沿用了「派遣」这个名字。"},{"no":"05","title":"A military operation with an objective","titleCN":"有明确目标的军事行动","definition":"a single operation with a stated objective, often by aircraft","definitionCN":"一次有既定目标的行动，常指飞机出动","example":"The squadron flew nine missions in a month.","exampleCN":"这个中队一个月里飞了九次任务。","why":"An aircrew is sent out with an objective, and the flight becomes the mission.","whyCN":"机组带着目标被派出，这次飞行就成了 mission。"},{"no":"06","title":"A personal calling","titleCN":"个人感到的天职","definition":"the duty that a person feels bound to fulfil in life","definitionCN":"一个人觉得自己一生必须完成的职责","example":"Her mission was to teach girls in villages to read.","exampleCN":"她的使命是教村里的女孩识字。","why":"A sending can come from inside rather than from a sender, and the word then means a calling.","whyCN":"派遣也可以来自内心而不是来自派遣者，这个词于是指一种召唤。"},{"no":"07","title":"An embassy or delegation office","titleCN":"使馆或代表处的办公机构","definition":"the office or building of a country's representative abroad","definitionCN":"一国驻外代表所在的办公机构或馆舍","example":"The visa section is on the second floor of the mission.","exampleCN":"签证处在代表处的二楼。","why":"The people sent need a place to work, and the building takes the name of the group.","whyCN":"被派出去的人需要一个办公的地方，馆舍便沿用了这群人的名称。"},{"no":"08","title":"A task given to one person","titleCN":"交给某一个人的具体差事","definition":"a particular errand or job assigned to an individual","definitionCN":"分配给某一个人的具体差事","example":"His mission for the afternoon was to find the missing file.","exampleCN":"他下午的差事是把那份不见的档案找出来。","why":"The word scales down to one person and one errand, keeping the same shape of being sent.","whyCN":"这个词能缩小到一个人、一件差事，仍然保持「被派出」的形状。"}],"etymology":{"intro":{"en":"Mission comes from Latin missio 'a sending', built on mittere 'to send'. English first used it for the sending of envoys and missionaries, and later for any task someone is sent to do.","cn":"mission 来自拉丁 missio「派遣」，由 mittere「发送」构成。英语最初用它指派遣使节与传教士，后来才指任何被派去完成的任务。"},"items":[{"era":"SOURCE UNCERTAIN","en":"Latin mittere 'to send, let go' is well recorded, but its deeper origin is uncertain and no older root can be stated with confidence.","cn":"拉丁 mittere「发送、放出」记录充分，但其更早来源不确定，无法有把握地给出更古老的词根。"},{"era":"LATIN MISSUS","en":"The past participle missus 'sent' supplies the miss- inside mission, missionary and missile.","cn":"过去分词 missus「被送出的」提供了 mission、missionary 与 missile 里的 miss-。"},{"era":"LATIN MISSIO","en":"Missio meant a sending or a letting go; in military Latin it could also mean a discharge from service.","cn":"missio 意为派遣或放行；在军事拉丁语里也可指解除兵役。"},{"era":"SIXTEENTH CENTURY","en":"English took mission in the sixteenth century, first for the sending of envoys, then for the sending of missionaries.","cn":"英语在十六世纪借入 mission，先指派遣使节，再指派遣传教士。"},{"era":"RELIGIOUS AND DIPLOMATIC","en":"By the seventeenth century a mission could be the station itself, and by the eighteenth a permanent embassy.","cn":"到十七世纪，mission 可指传教站本身；到十八世纪，又可指常设使馆。"},{"era":"MODERN EXTENSIONS","en":"Aviation, space flight and management gave the word its operation and purpose senses in the twentieth century.","cn":"航空、航天与管理在二十世纪赋予这个词「行动」与「宗旨」两义。"}]},"similar":{"note":{"en":"The first group shares the miss- root; the second group names other tasks and purposes.","cn":"第一组共享 miss- 词根；第二组是其他任务与宗旨的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"missile","ipa":"/ˈmɪsaɪl/","tag":"same root, different sense","definition":"From missus 'sent', but it names a weapon that is thrown or fired, not a task.","definitionCN":"出自 missus「被送出的」，但指被投出或发射的武器，不是任务。"},{"word":"dismiss","ipa":"/dɪˈmɪs/","tag":"same root, different sense","definition":"From dis- 'away' plus mittere 'send', meaning to send away or let go.","definitionCN":"由 dis-「离开」加 mittere「发送」构成，意为打发走、解散。"},{"word":"transmit","ipa":"/trænzˈmɪt/","tag":"same root","definition":"From trans- 'across' plus mittere, meaning to send across.","definitionCN":"由 trans-「越过」加 mittere 构成，意为发送过去。"},{"word":"commission","ipa":"/kəˈmɪʃn/","tag":"same root, different sense","definition":"From com- 'together' plus mittere, meaning to entrust a task or the body entrusted with it.","definitionCN":"由 com-「共同」加 mittere 构成，意为委托任务，或指受托的机构。"}]},{"heading":"NEAR MEANING","entries":[{"word":"task","ipa":"/tɑːsk/","tag":"near meaning","definition":"A piece of work to be done, with no idea of being sent.","definitionCN":"一件要做的工作，不含「被派出」之意。"},{"word":"assignment","ipa":"/əˈsaɪnmənt/","tag":"near meaning","definition":"Work given to a person by someone in authority; it stresses the giving.","definitionCN":"由有权者交给某人的工作，强调交付。"},{"word":"purpose","ipa":"/ˈpɜːpəs/","tag":"near meaning","definition":"The aim behind an action, which is the first sense of mission within an organization.","definitionCN":"行动背后的目标，正是 mission 在组织内部的第一义。"},{"word":"delegation","ipa":"/ˌdelɪˈɡeɪʃn/","tag":"near meaning","definition":"A group sent with authority to represent others, close to the diplomatic sense.","definitionCN":"受权代表他人而被派出的团体，接近外交义。"},{"word":"vocation","ipa":"/vəʊˈkeɪʃn/","tag":"near meaning","definition":"A strong sense of being called to a kind of work, close to the personal sense.","definitionCN":"强烈感到被召唤去做某类工作，接近个人天职义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin verb, the real family and the real fixed phrases.","cn":"正常联想使用真实的拉丁动词、真实的同族词与真实的固定说法。"},"normal":[{"en":"Mittere is to send, and missio is a sending, so a mission is literally something sent.","cn":"mittere 是发送，missio 是派遣，因此 mission 字面上就是「被派出的事」。"},{"en":"The family runs mission, missionary, missile, dismiss and transmit.","cn":"同族词有 missionary、missile、dismiss 与 transmit。"},{"en":"Fixed phrases mark it: mission statement, rescue mission, space mission.","cn":"固定说法标出它的用法：使命宣言、救援任务、太空飞行任务。"},{"en":"The same word scales from a whole organisation's purpose down to one afternoon errand.","cn":"同一个词能从整个组织的宗旨缩小到一个下午的差事。"},{"en":"A sending needs a sender, a message and a road, which is the whole picture.","cn":"一次派遣需要派遣者、消息与一条路，这就是整幅画面。"}],"abstract":[{"en":"Picture a sealed letter handed over and a traveller turning at once.","cn":"想象一封封好的信被交出，旅人当场转身。"},{"en":"Picture a box carried two days over a pass, never set down.","cn":"想象一只箱子翻过山口走了两天，始终没有放下。"},{"en":"Picture a lamp left burning at a station for those still on the road.","cn":"想象传教站里为还在路上的人留着一盏灯。"}]},"examples":[{"en":"The agency rewrote its mission after the flood.","cn":"洪水之后，这个机构重写了它的宗旨。"},{"en":"A medical mission reached the island on the third day.","cn":"一支医疗队第三天抵达了这座岛。"},{"en":"Her mission for the morning was to find the missing key.","cn":"她上午的差事是找到那把不见了的钥匙。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「miss（送出）+ ion（名词）」——被送出去要做的事，就是任务","word":"mission"},"root":"拉丁 mittere「发送」→ 过去分词 missus「被送出的」→ missio「派遣」→ 英语 mission。","sensesIntro":{"en":"Eight senses all begin with a sending: an organization's declared purpose, a purposeful journey, a group sent abroad, a mission station, a military sortie, a personal calling, an embassy office and one person's errand.","cn":"八个义项都从一次派遣开始：组织宣告的宗旨、有目的的出行、派往国外的团体、传教站、军事出动、个人天职、使馆馆舍，以及一个人的差事。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed letter handed over, and a traveller who turns and leaves at once.","cn":"核心意象：一封封好的信被交出，旅人转身立刻出发。"},"chain":["THE SENDING","THE PURPOSE DECLARED","THE JOURNEY","THE GROUP SENT","THE STATION","THE PERSONAL CALL"],"branches":[{"senses":"01 · 06","en":"WHY AND BY WHOM: a declared purpose, and a calling that feels like a sender inside.","cn":"为何与由谁：公开宣告的宗旨，以及像内心派遣者一样的召唤。"},{"senses":"02 · 05","en":"THE GOING ITSELF: a purposeful trip, and a sortie with a stated objective.","cn":"出行本身：一趟有目的的行程，以及一次有既定目标的出动。"},{"senses":"03 · 07","en":"THE PEOPLE AND THEIR ROOM: a delegation abroad, and the building it works in.","cn":"人与他们的房间：驻外代表团，以及它办公的馆舍。"},{"senses":"04","en":"THE STATION: missionaries were sent, so their posting took the name of the sending.","cn":"驻地：传教士被派出，因此驻地沿用了「派遣」之名。"},{"senses":"08","en":"ONE ERRAND: the whole picture shrinks to a single afternoon's task.","cn":"一件差事：整幅画面缩小到一个下午的任务。"}]},"affixes":{"intro":{"en":"Mission is a Latin participle and action noun from the verb 'to send', and the same verb reaches several common English words.","cn":"mission 是由「发送」动词来的拉丁分词与动作名词，同一个动词还通向若干常用英语词。"},"latinIntro":{"en":"Latin mittere gives mission, missile, dismiss, transmit and commission.","cn":"拉丁 mittere 衍生 mission、missile（导弹）、dismiss（打发走）、transmit（传送）与 commission（委托）。"},"items":[{"word":"mittere","structure":"Latin verb, third conjugation","meaning":"to send, let go","meaningCN":"发送；放出","example":"The root supplies the act of sending.","exampleCN":"这个词根提供「发送」这个动作。"},{"word":"missus","structure":"past participle of mittere","meaning":"sent","meaningCN":"被送出的","example":"The participle supplies the miss- of the family.","exampleCN":"这个分词提供词族里的 miss-。"},{"word":"missio","structure":"mittere plus -io (action)","meaning":"a sending, a letting go","meaningCN":"派遣；放行","example":"The action noun is the direct source of mission.","exampleCN":"这个动作名词是 mission 的直接来源。"},{"word":"mission","structure":"missio through French","meaning":"a task one is sent to do","meaningCN":"被派去完成的任务","example":"The English word widened from sending to errand.","exampleCN":"英语词从「派遣」扩到「差事」。"},{"word":"missionary","structure":"mission plus -ary (one connected with)","meaning":"one sent to spread a faith","meaningCN":"传教士","example":"The suffix marks the person sent.","exampleCN":"后缀标出被派出的人。"},{"word":"missile","structure":"missus plus -ile (able to be)","meaning":"a weapon that is sent","meaningCN":"导弹；投射物","example":"The same root sends a weapon instead of a person.","exampleCN":"同一词根送出的是武器而不是人。"},{"word":"dismiss","structure":"dis- (away) plus mittere","meaning":"to send away","meaningCN":"解散；解雇","example":"The prefix reverses the direction of sending.","exampleCN":"前缀把发送的方向反过来。"},{"word":"transmit","structure":"trans- (across) plus mittere","meaning":"to send across","meaningCN":"传送；传播","example":"The prefix lengthens the road of the sending.","exampleCN":"前缀把派遣的路拉长。"},{"word":"commission","structure":"com- (together) plus mittere","meaning":"to entrust; a body entrusted","meaningCN":"委托；委员会","example":"Entrusting is sending a task with authority.","exampleCN":"委托就是带着权力把任务送出去。"}],"latinEntries":[{"word":"mittere","structure":"mittere, misi, missum (verb, third conjugation)","meaning":"to send","meaningCN":"发送"},{"word":"missio","structure":"missio, missionis (n., third declension)","meaning":"a sending","meaningCN":"派遣"},{"word":"missus","structure":"missus, missus (n., fourth declension)","meaning":"a sending; a discharge","meaningCN":"派遣；释放"}],"derivatives":[{"word":"missionary","pos":"n./adj.","zh":"传教士；传教的"},{"word":"commission","pos":"n./v.","zh":"委员会；委托"},{"word":"dismiss","pos":"v.","zh":"解散；解雇"},{"word":"transmit","pos":"v.","zh":"传送；传播"}]}}]);
